import subprocess

def count_requirement_hits(submission_path: str, requirement: str) -> int:
    result = subprocess.run(['grep', '-F', '-c', '--', requirement, submission_path], capture_output=True, text=True, encoding='utf-8')
    if result.returncode == 1:
        return 0
    if result.returncode != 0:
        if result.returncode == 2:
            raise FileNotFoundError(submission_path)
        raise RuntimeError(result.stderr)
    return int(result.stdout.strip())

