from solution import quote
import os
import tempfile

def make_file(text):
    fd, path = tempfile.mkstemp()
    with os.fdopen(fd, 'w') as f:
        f.write(text)
    return path

def test_selects_lowest_total_and_calculates_all_components():
    p = make_file('SEA,RTM,40HC,2024-01-01,2024-12-31,1000,2,300\nSEA,RTM,40HC,2024-01-01,2024-12-31,800,5,100\n')
    try:
        result = quote([p], 'SEA', 'RTM', '40HC', 100, '2024-06-15', 10)
        assert result == {'origin': 'SEA', 'destination': 'RTM', 'container': '40HC', 'service_date': '2024-06-15', 'base_rate': 800.0, 'weight_charge': 500.0, 'fuel_charge': 130.0, 'total': 1430.0}
    finally:
        os.unlink(p)

def test_validity_boundaries_and_multiple_files():
    p1 = make_file('NYC,LON,20GP,2024-03-01,2024-03-31,900,1,50\n')
    p2 = make_file('NYC,LON,20GP,2024-04-01,2024-04-30,700,1,50\n')
    try:
        a = quote([p1, p2], 'NYC', 'LON', '20GP', 40, '2024-03-01', 0)
        b = quote([p1, p2], 'NYC', 'LON', '20GP', 40, '2024-04-30', 0)
        assert a['total'] == 950.0
        assert b['total'] == 750.0
    finally:
        os.unlink(p1)
        os.unlink(p2)

def test_minimum_weight_charge_is_used():
    p = make_file('HAM,SIN,20GP,2024-01-01,2024-12-31,500,1,200\n')
    try:
        result = quote([p], 'HAM', 'SIN', '20GP', 50, '2024-07-01', 5)
        assert result['weight_charge'] == 200.0
        assert result['fuel_charge'] == 35.0
        assert result['total'] == 735.0
    finally:
        os.unlink(p)

def test_tie_breaking_prefers_lower_subtotal_then_rate_fields():
    p = make_file('A,B,C,2024-01-01,2024-12-31,100,2,0\nA,B,C,2024-02-01,2024-11-30,90,3,0\nA,B,C,2024-03-01,2024-10-31,90,3,0\n')
    try:
        result = quote([p], 'A', 'B', 'C', 10, '2024-06-01', 0)
        assert result['base_rate'] == 90.0
    finally:
        os.unlink(p)

def test_no_match_and_bad_arguments():
    p = make_file('A,B,C,2024-01-01,2024-12-31,10,1,0\n')
    try:
        try:
            quote([p], 'X', 'B', 'C', 1, '2024-01-01', 0)
            assert False
        except LookupError:
            pass
        for args in [(0, 0), (-1, 0), (1, -1)]:
            try:
                quote([p], 'A', 'B', 'C', args[0], '2024-01-01', args[1])
                assert False
            except ValueError:
                pass
    finally:
        os.unlink(p)

def test_malformed_records_and_dates():
    p = make_file('A,B,C,2024-01-01,2024-12-31,notnumber,1,0\n')
    try:
        try:
            quote([p], 'A', 'B', 'C', 1, '2024-01-01', 0)
            assert False
        except ValueError:
            pass
    finally:
        os.unlink(p)
    try:
        quote([], 'A', 'B', 'C', 1, '2024-02-30', 0)
        assert False
    except ValueError:
        pass

