import csv
import subprocess
from datetime import date
from decimal import Decimal, ROUND_HALF_UP

def quote(paths: list[str], origin: str, destination: str, container: str, weight_kg: float, service_date: str, fuel_percent: float) -> dict[str, object]:
    if not origin or not destination or (not container) or (weight_kg <= 0) or (fuel_percent < 0):
        raise ValueError('invalid arguments')
    try:
        wanted = date.fromisoformat(service_date)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    rows = []
    for path in paths:
        result = subprocess.run(['sort', '-t,', '-k1,1', '--', path], capture_output=True, text=True, check=True)
        for line in result.stdout.splitlines():
            fields = next(csv.reader([line]))
            if len(fields) != 8:
                raise ValueError('malformed record')
            fields = [x.strip() for x in fields]
            try:
                start = date.fromisoformat(fields[3])
                end = date.fromisoformat(fields[4])
                base = Decimal(fields[5])
                per = Decimal(fields[6])
                minimum = Decimal(fields[7])
            except Exception as exc:
                raise ValueError('malformed record') from exc
            if fields[0] == origin and fields[1] == destination and (fields[2] == container) and (start <= wanted <= end):
                weight = max(per * Decimal(str(weight_kg)), minimum)
                subtotal = base + weight
                fuel = subtotal * Decimal(str(fuel_percent)) / Decimal('100')
                total = subtotal + fuel
                rows.append((total, subtotal, base, per, start, end, weight, fuel))
    if not rows:
        raise LookupError('no applicable rate')
    total, subtotal, base, per, start, end, weight, fuel = min(rows, key=lambda x: x[:6])

    def money(x):
        return float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    return {'origin': origin, 'destination': destination, 'container': container, 'service_date': service_date, 'base_rate': money(base), 'weight_charge': money(weight), 'fuel_charge': money(fuel), 'total': money(total)}

