import sqlite3

def create_schema(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS attestations (employee_id TEXT NOT NULL, policy_id TEXT NOT NULL, status TEXT NOT NULL, attested_at TEXT NOT NULL, note TEXT NOT NULL, PRIMARY KEY (employee_id, policy_id))')
    conn.commit()

def save_attestation(conn: sqlite3.Connection, employee_id: str, policy_id: str, status: str, attested_at: str, note: str) -> None:
    if not isinstance(employee_id, str) or not isinstance(policy_id, str) or (not employee_id) or (not policy_id):
        raise ValueError('invalid identifier')
    if status not in {'accepted', 'pending', 'declined'}:
        raise ValueError('invalid status')
    if not isinstance(attested_at, str) or not attested_at:
        raise ValueError('invalid timestamp')
    if not isinstance(note, str):
        raise ValueError('invalid note')
    conn.execute('INSERT INTO attestations(employee_id, policy_id, status, attested_at, note) VALUES (?, ?, ?, ?, ?) ON CONFLICT(employee_id, policy_id) DO UPDATE SET status=excluded.status, attested_at=excluded.attested_at, note=excluded.note', (employee_id, policy_id, status, attested_at, note))
    conn.commit()

def build_report(conn: sqlite3.Connection, search: str='', sort_by: str='employee_id') -> list[dict]:
    if not isinstance(search, str):
        raise ValueError('invalid search')
    orders = {'employee_id': 'employee_id ASC', 'total_desc': 'total DESC, employee_id ASC', 'latest_desc': 'latest DESC, employee_id ASC'}
    if sort_by not in orders:
        raise ValueError('invalid sort')
    query = "SELECT employee_id, COUNT(*) AS total, SUM(CASE WHEN status='accepted' THEN 1 ELSE 0 END) AS accepted, SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) AS pending, SUM(CASE WHEN status='declined' THEN 1 ELSE 0 END) AS declined, MAX(attested_at) AS latest FROM attestations WHERE employee_id LIKE ? GROUP BY employee_id ORDER BY " + orders[sort_by]
    rows = conn.execute(query, ('%' + search + '%',)).fetchall()
    return [{'employee_id': r[0], 'total': r[1], 'accepted': r[2], 'pending': r[3], 'declined': r[4], 'latest': r[5]} for r in rows]

