from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date
from lxml import etree

def summarize_claims(xml: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    try:
        root = etree.fromstring(xml.encode('utf-8'), parser=etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'travelClaims':
        raise ValueError('invalid root')
    seen = set()
    approved = []
    total = Decimal('0.00')
    for node in root:
        if node.tag != 'claim':
            raise ValueError('invalid claim')
        ident = (node.get('id') or '').strip()
        status = (node.get('status') or '').strip()
        if not ident or ident in seen:
            raise ValueError('invalid id')
        seen.add(ident)
        values = {}
        for name in ('traveler', 'amount', 'incidentDate'):
            child = node.find(name)
            if child is None or child.text is None or (not child.text.strip()):
                raise ValueError('missing field')
            values[name] = child.text.strip()
        try:
            amount = Decimal(values['amount']).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            date.fromisoformat(values['incidentDate'])
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid claim data') from exc
        if amount < 0:
            raise ValueError('invalid amount')
        if status == 'approved':
            total += amount
            approved.append((amount, values['incidentDate'], ident, values['traveler']))
    approved.sort(key=lambda x: (-x[0], x[1], x[2]))
    start = (page - 1) * page_size
    claims = [{'id': ident, 'traveler': traveler, 'amount': f'{amount:.2f}', 'incident_date': incident_date} for amount, incident_date, ident, traveler in approved[start:start + page_size]]
    return {'page': page, 'page_size': page_size, 'total': len(approved), 'total_amount': f'{total:.2f}', 'claims': claims}

