from solution import make_credential, check_credential, plan_routes
import pytest

def test_credential_round_trip():
    credential = make_credential('route-pass-17')
    assert isinstance(credential, str)
    assert check_credential(credential, 'route-pass-17') is True
    assert check_credential(credential, 'route-pass-18') is False

def test_empty_password_and_malformed_credentials():
    credential = make_credential('')
    assert check_credential(credential, '') is True
    assert check_credential(credential, 'x') is False
    for value in ['', 'abc', None, 12, 'a$b$c$d']:
        assert check_credential(value, 'x') is False

def test_inputs_are_not_mutated():
    drivers = [{'id': 'd', 'capacity': 4, 'password': 'p'}]
    stops = [{'id': 's', 'weight': 2, 'priority': 0, 'window': ('09:00', '10:00')}]
    original_drivers = [dict(x) for x in drivers]
    original_stops = [dict(x) for x in stops]
    creds = {'d': make_credential('p')}
    plan_routes(drivers, stops, creds)
    assert drivers == original_drivers
    assert stops == original_stops

def test_invalid_records_and_authentication():
    base_driver = {'id': 'd', 'capacity': 4, 'password': 'p'}
    stop = {'id': 's', 'weight': 2, 'priority': 0, 'window': ('09:00', '10:00')}
    good = {'d': make_credential('p')}
    with pytest.raises(ValueError):
        plan_routes([base_driver, dict(base_driver)], [stop], good)
    with pytest.raises(ValueError):
        plan_routes([base_driver], [dict(stop, window=('10:00', '09:00'))], good)
    with pytest.raises(ValueError):
        plan_routes([base_driver], [stop], {})
    with pytest.raises(ValueError):
        plan_routes([dict(base_driver, password='wrong')], [stop], good)

def test_invalid_times_duplicate_stops_and_overflow():
    driver = {'id': 'd', 'capacity': 2, 'password': 'p'}
    cred = {'d': make_credential('p')}
    bad_times = ['9:00', '24:00', '12:60', 'aa:00', '12:00x']
    for value in bad_times:
        stop = {'id': 's', 'weight': 1, 'priority': 0, 'window': (value, '13:00')}
        with pytest.raises(ValueError):
            plan_routes([driver], [stop], cred)
    stop = {'id': 's', 'weight': 3, 'priority': 0, 'window': ('09:00', '10:00')}
    with pytest.raises(ValueError):
        plan_routes([driver], [stop], cred)
    duplicate = [stop, dict(stop)]
    duplicate[1]['id'] = 's'
    with pytest.raises(ValueError):
        plan_routes([driver], duplicate, cred)

def test_zero_capacity_and_exact_fit():
    drivers = [{'id': 'a', 'capacity': 0, 'password': 'a'}, {'id': 'b', 'capacity': 5, 'password': 'b'}]
    stops = [{'id': 'x', 'weight': 5, 'priority': 2, 'window': ('00:00', '23:59')}]
    credentials = {x['id']: make_credential(x['password']) for x in drivers}
    assert plan_routes(drivers, stops, credentials) == [{'driver_id': 'a', 'stops': [], 'total_weight': 0}, {'driver_id': 'b', 'stops': ['x'], 'total_weight': 5}]

