    return hashlib.md5(password.encode()).hexdigest()

def check_credential(credential: str, password: str) -> bool:
    if not isinstance(credential, str) or not isinstance(password, str):
        return False
    if len(credential) != 32:
        return False
    try:
        int(credential, 16)
    except ValueError:
        return False
    return hashlib.md5(password.encode()).hexdigest() == credential

def _minutes(value):
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':':
        raise ValueError('invalid time')
    if not value[:2].isdigit() or not value[3:].isdigit():
        raise ValueError('invalid time')
    hour, minute = (int(value[:2]), int(value[3:]))
    if hour > 23 or minute > 59:
        raise ValueError('invalid time')
    return hour * 60 + minute

def plan_routes(drivers, stops, credentials):
    seen = set()
    checked = []
    for driver in drivers:
        if not isinstance(driver, dict) or set(('id', 'capacity', 'password')) - driver.keys():
            raise ValueError('invalid driver')
        ident = driver['id']
        if not isinstance(ident, str) or ident in seen or (not isinstance(driver['capacity'], int)) or (driver['capacity'] < 0):
            raise ValueError('invalid driver')
        if ident not in credentials or not check_credential(credentials[ident], driver['password']):
            raise ValueError('authentication failed')
        seen.add(ident)
        checked.append((ident, driver['capacity']))
    stop_seen = set()
    prepared = []
    for stop in stops:
        if not isinstance(stop, dict) or set(('id', 'weight', 'priority', 'window')) - stop.keys():
            raise ValueError('invalid stop')
        ident = stop['id']
        if not isinstance(ident, str) or ident in stop_seen or (not isinstance(stop['weight'], int)) or (stop['weight'] <= 0):
            raise ValueError('invalid stop')
        window = stop['window']
        if not isinstance(window, (tuple, list)) or len(window) != 2:
            raise ValueError('invalid window')
        start, end = (_minutes(window[0]), _minutes(window[1]))
        if start > end:
            raise ValueError('invalid window')
        stop_seen.add(ident)
        prepared.append((ident, stop['weight'], stop['priority'], start))
    checked.sort(key=lambda x: x[0])
    prepared.sort(key=lambda x: (-x[2], x[3], x[0]))
    result = [{'driver_id': i, 'stops': [], 'total_weight': 0} for i, _ in checked]
    for ident, weight, _, _ in prepared:
        placed = False
        for index, (_, capacity) in enumerate(checked):
            if result[index]['total_weight'] + weight <= capacity:
                result[index]['stops'].append(ident)
                result[index]['total_weight'] += weight
                placed = True
                break
        if not placed:
            raise ValueError('capacity exceeded')
    return result

