import json
import os
import zipfile
from datetime import datetime, timezone, timedelta

def _path(base, name):
    if not name or os.path.isabs(name):
        raise ValueError('invalid name')
    root = os.path.realpath(base)
    path = os.path.realpath(os.path.join(root, name))
    if os.path.commonpath([root, path]) != root:
        raise ValueError('invalid name')
    return path

def _events(events):
    if not isinstance(events, list):
        raise ValueError('events')
    out = []
    for e in events:
        if not isinstance(e, dict) or set(e) != {'day', 'minute', 'target', 'mode'}:
            raise ValueError('event')
        if type(e['day']) is not int or not 0 <= e['day'] <= 6:
            raise ValueError('day')
        if type(e['minute']) is not int or not 0 <= e['minute'] <= 1439:
            raise ValueError('minute')
        if not isinstance(e['target'], (int, float)) or isinstance(e['target'], bool) or (not 5 <= e['target'] <= 35):
            raise ValueError('target')
        if e['mode'] not in ('heat', 'cool', 'auto'):
            raise ValueError('mode')
        out.append({'day': e['day'], 'minute': e['minute'], 'target': e['target'], 'mode': e['mode']})
    return sorted(out, key=lambda x: (x['day'], x['minute'], x['mode']))

def read_schedule(base_dir: str, relative_name: str) -> list[dict]:
    try:
        with open(_path(base_dir, relative_name), encoding='utf-8') as f:
            value = json.load(f)
    except (json.JSONDecodeError, UnicodeDecodeError) as e:
        raise ValueError('json') from e
    if not isinstance(value, dict) or set(value) != {'events'}:
        raise ValueError('schedule')
    return _events(value['events'])

def write_schedule(base_dir: str, relative_name: str, events: list[dict]) -> None:
    value = _events(events)
    path = _path(base_dir, relative_name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        json.dump({'events': value}, f, separators=(',', ':'))
        f.write('\n')

def extract_schedule_bundle(archive_path: str, destination_dir: str) -> list[str]:
    names = []
    with zipfile.ZipFile(archive_path) as z:
        for info in z.infolist():
            if info.is_dir() or not info.filename.endswith('.json'):
                continue
            path = _path(destination_dir, info.filename)
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with z.open(info) as src, open(path, 'wb') as dst:
                dst.write(src.read())
            names.append(info.filename)
    return names

def aggregate_readings(readings: list[dict], interval_minutes: int) -> list[dict]:
    if interval_minutes <= 0:
        raise ValueError('interval')
    groups = {}
    for r in readings:
        try:
            text = r['timestamp'].replace('Z', '+00:00')
            dt = datetime.fromisoformat(text)
            if dt.tzinfo is None:
                raise ValueError
            temp, target = (r['temperature'], r['target'])
            if not isinstance(temp, (int, float)) or not isinstance(target, (int, float)):
                raise ValueError
        except (KeyError, TypeError, ValueError):
            raise ValueError('reading')
        dt = dt.astimezone(timezone.utc)
        midnight = dt.replace(hour=0, minute=0, second=0, microsecond=0)
        start = midnight + timedelta(minutes=(dt - midnight).total_seconds() // (interval_minutes * 60) * interval_minutes)
        groups.setdefault(start, []).append((temp, target))
    result = []
    for start in sorted(groups):
        vals = groups[start]
        ts = [x[0] for x in vals]
        targets = [x[1] for x in vals]
        result.append({'start': start.strftime('%Y-%m-%dT%H:%M:%SZ'), 'count': len(vals), 'average_temperature': round(sum(ts) / len(ts), 2), 'minimum_temperature': round(min(ts), 2), 'maximum_temperature': round(max(ts), 2), 'average_target': round(sum(targets) / len(targets), 2)})
    return result

