import datetime
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_traceability(records: list[dict], market: str | None=None, page: int=1, page_size: int=50) -> str:
    if not isinstance(records, list) or (market is not None and (not isinstance(market, str))):
        raise ValueError('invalid arguments')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    rows = []
    required = ('batch_id', 'farm', 'market', 'product', 'harvested_on')
    for record in records:
        if not isinstance(record, dict) or any((not isinstance(record.get(k), str) or not record[k] for k in required)):
            raise ValueError('invalid record')
        if market is not None and record['market'] != market:
            continue
        try:
            datetime.date.fromisoformat(record['harvested_on'])
            quantity = Decimal(str(record['quantity_kg']))
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid record')
        if isinstance(record['quantity_kg'], bool) or not quantity.is_finite() or quantity <= 0:
            raise ValueError('invalid record')
        quantity = quantity.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append((record['harvested_on'], record['batch_id'], record, quantity))
    rows.sort(key=lambda item: (item[0], item[1]))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['batch_id', 'farm', 'market', 'product', 'quantity_kg', 'harvested_on'])
            for date, _, record, quantity in selected:
                writer.writerow([record['batch_id'], record['farm'], record['market'], record['product'], f'{quantity:.2f}', date])
        with open(path, encoding='utf-8', newline='') as stream:
            return stream.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

