    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()

def _split_escaped(text: str, separator: str) -> list[str]:
    out = []
    item = []
    i = 0
    while i < len(text):
        c = text[i]
        if c == '\\':
            i += 1
            if i == len(text) or text[i] not in ',;\\':
                raise ValueError('escape')
            item.append(text[i])
        elif c == separator:
            out.append(''.join(item))
            item = []
        else:
            item.append(c)
        i += 1
    if text.endswith('\\'):
        raise ValueError('escape')
    out.append(''.join(item))
    return out

def apply_booking_webhook(payload: str, signature: str, secret: str, now: int, bookings: dict[str, dict]) -> dict[str, dict]:
