import hashlib
import hmac
import json

def verify_order_request(body: str, header: str, secret: bytes, now: int) -> dict:
    parts = header.split(';')
    if len(parts) != 2 or not parts[0].startswith('ts=') or (not parts[1].startswith('sig=')):
        raise ValueError('invalid header')
    try:
        ts = int(parts[0][3:])
    except ValueError:
        raise ValueError('invalid timestamp')
    supplied = parts[1][4:]
    if len(supplied) != 64:
        raise ValueError('invalid signature')
    try:
        bytes.fromhex(supplied)
    except ValueError:
        raise ValueError('invalid signature')
    expected = hmac.new(secret, f'{ts}.{body}'.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected) or abs(now - ts) > 300:
        raise ValueError('request rejected')
    try:
        obj = json.loads(body)
    except Exception:
        raise ValueError('invalid json')
    if not isinstance(obj, dict) or set(obj) != {'order_id', 'restaurant', 'delivery_zone', 'priority', 'ready_at', 'items'}:
        raise ValueError('invalid order')
    for key in ('order_id', 'restaurant', 'delivery_zone'):
        if not isinstance(obj[key], str) or not obj[key]:
            raise ValueError('invalid order')
    if isinstance(obj['priority'], bool) or not isinstance(obj['priority'], int) or (not 0 <= obj['priority'] <= 9):
        raise ValueError('invalid order')
    if isinstance(obj['ready_at'], bool) or not isinstance(obj['ready_at'], int) or obj['ready_at'] < 0:
        raise ValueError('invalid order')
    if not isinstance(obj['items'], list) or not obj['items']:
        raise ValueError('invalid items')
    for item in obj['items']:
        if not isinstance(item, dict) or set(item) != {'sku', 'qty'} or (not isinstance(item['sku'], str)) or (not item['sku']) or isinstance(item['qty'], bool) or (not isinstance(item['qty'], int)) or (item['qty'] <= 0):
            raise ValueError('invalid items')
    return obj

def build_dispatch_plan(orders: list[dict]) -> list[dict]:
    groups = {}
    for o in orders:
        key = (o['restaurant'], o['delivery_zone'], o['ready_at'] // 900)
        if key not in groups:
            groups[key] = {'orders': [], 'total': 0, 'max_priority': -1}
        g = groups[key]
        g['orders'].append(o)
        g['total'] += sum((i['qty'] for i in o['items']))
        g['max_priority'] = max(g['max_priority'], o['priority'])
    ranked = sorted(groups.items(), key=lambda x: (-x[1]['max_priority'], x[0][2], x[0][0], x[0][1]))
    result = []
    for (restaurant, zone, window), g in ranked:
        ids = [o['order_id'] for o in sorted(g['orders'], key=lambda o: (-o['priority'], o['ready_at'], o['order_id']))]
        result.append({'restaurant': restaurant, 'delivery_zone': zone, 'window': window, 'order_ids': ids, 'total_items': g['total']})
    return result

