_DATE = re.compile('^\\d{4}-\\d{2}-\\d{2}$')

def _day(value):
    if not isinstance(value, str) or not _DATE.fullmatch(value):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def parse_feed(xml_text: str) -> list[dict]:
    if not isinstance(xml_text, str):
        raise ValueError('invalid XML')
    try:
        root = etree.fromstring(xml_text.encode(), parser=etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'feed':
        raise ValueError('invalid root')
    result, ids = ([], set())
    for sub in root.findall('subscription'):
        try:
            sid, pet = (sub.get('id'), sub.get('pet'))
            priority = int(sub.get('priority'))
        except (TypeError, ValueError):
            raise ValueError('invalid subscription')
        if not sid or not pet or sid in ids or (not 0 <= priority <= 5):
            raise ValueError('invalid subscription')
        ids.add(sid)
        seen = set()
        items = sub.findall('item')
        if not items:
            raise ValueError('missing items')
        for item in items:
            sku = item.get('sku')
            if not sku or sku in seen:
                raise ValueError('duplicate sku')
            seen.add(sku)
            try:
                quantity = int(item.get('quantity'))
                interval = int(item.get('interval_days'))
            except (TypeError, ValueError):
                raise ValueError('invalid item')
            last = item.get('last_order')
            _day(last)
            if quantity < 1 or interval < 1:
                raise ValueError('invalid item')
            note = item.find('note')
            result.append({'id': sid, 'pet': pet, 'priority': priority, 'sku': sku, 'quantity': quantity, 'interval_days': interval, 'last_order': last, 'note': '' if note is None else ''.join(note.itertext()).strip()})
    return result

def create_order_plan(xml_text: str, as_of: str) -> list[dict]:
    cutoff = _day(as_of)
    groups = {}
    for item in parse_feed(xml_text):
        due = _day(item['last_order']) + timedelta(days=item['interval_days'])
        if due <= cutoff:
            group = groups.setdefault(item['sku'], {'sku': item['sku'], 'quantity': 0, 'subscriptions': set(), 'priority': -1, 'due_date': due})
            group['quantity'] += item['quantity']
            group['subscriptions'].add(item['id'])
            group['priority'] = max(group['priority'], item['priority'])
            group['due_date'] = min(group['due_date'], due)
    output = []
    for group in groups.values():
        group['subscriptions'] = sorted(group['subscriptions'])
        group['due_date'] = group['due_date'].isoformat()
        output.append(group)
    return sorted(output, key=lambda x: (x['due_date'], -x['priority'], x['sku']))

