def find_lots(conn: sqlite3.Connection, product: str='', farm: str='', min_quantity: float=0, sort: str='harvest_date', reverse: bool=False) -> list[dict]:
    if sort not in {'lot_id', 'farm', 'product', 'harvest_date', 'quantity'}:
        raise ValueError('invalid sort')
    if min_quantity < 0:
        raise ValueError('negative quantity')
