    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start > end:
        raise ValueError('reversed dates')
    rows = conn.execute('SELECT farm, harvest_date, quantity FROM lots WHERE product = ? AND harvest_date >= ? AND harvest_date <= ?', (product, start_date, end_date)).fetchall()
    grouped = {}
    for farm, harvested, quantity in rows:
        item = grouped.setdefault(farm, {'farm': farm, 'lot_count': 0, 'total_quantity': 0.0, 'first_harvest_date': harvested})
        item['lot_count'] += 1
        item['total_quantity'] += quantity
        if harvested < item['first_harvest_date']:
            item['first_harvest_date'] = harvested
    return sorted(grouped.values(), key=lambda x: (-x['total_quantity'], x['farm']))

