from solution import decode_envelope, apply_signed_document
import base64
import hashlib
import hmac
import json
import math
import pytest

SECRET = b"workflow-key"

def enc(value):
    raw = json.dumps(value, separators=(",", ":"), ensure_ascii=False).encode()
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode()

def make_envelope(header, payload, secret=SECRET, signature=None):
    hs = enc(header)
    ps = enc(payload)
    body = (hs + "." + ps).encode()
    sig = hmac.new(secret, body, hashlib.sha256).digest() if signature is None else signature
    ss = base64.urlsafe_b64encode(sig).rstrip(b"=").decode()
    return hs + "." + ps + "." + ss

def payload(version=3, document_id="doc-7", operations=None):
    if operations is None:
        operations = [
            {"name": "review", "amount": 12.5, "currency": "USD"},
            {"name": "filing", "amount": 3, "currency": "EUR"},
            {"name": "stamp", "amount": 2.5, "currency": "USD"},
        ]
    return {"document_id": document_id, "version": version, "operations": operations}

def test_decode_returns_header_key_payload_and_signature():
    env = make_envelope({"kid": "signer-a"}, payload())
    kid, data, sig = decode_envelope(env, SECRET)
    assert kid == "signer-a"
    assert data == payload()
    assert sig == hmac.new(SECRET, env.rsplit(".", 1)[0].encode(), hashlib.sha256).digest()

def test_apply_aggregates_and_sorts_currency_keys():
    state = {}
    result = apply_signed_document(make_envelope({"kid": "a"}, payload()), SECRET, "doc-7", state)
    assert result == {
        "document_id": "doc-7",
        "version": 3,
        "operation_count": 3,
        "total_by_currency": {"EUR": 3, "USD": 15.0},
    }
    assert state == {"doc-7": 3}
    assert list(result["total_by_currency"]) == ["EUR", "USD"]

def test_newer_version_replaces_existing_state():
    state = {"doc-7": 2, "other": 9}
    result = apply_signed_document(make_envelope({"kid": "a"}, payload(8)), SECRET, "doc-7", state)
    assert result["version"] == 8
    assert state == {"doc-7": 8, "other": 9}

def test_replay_and_wrong_document_do_not_change_state():
    state = {"doc-7": 3}
    env = make_envelope({"kid": "a"}, payload(3))
    with pytest.raises(ValueError):
        apply_signed_document(env, SECRET, "doc-7", state)
    assert state == {"doc-7": 3}
    env2 = make_envelope({"kid": "a"}, payload(4, "other"))
    with pytest.raises(ValueError):
        apply_signed_document(env2, SECRET, "doc-7", state)
    assert state == {"doc-7": 3}

def test_bad_signature_is_rejected():
    env = make_envelope({"kid": "a"}, payload(), signature=b"x" * 32)
    with pytest.raises(PermissionError):
        decode_envelope(env, SECRET)

def test_malformed_envelopes_and_fields_raise_value_error():
    with pytest.raises(ValueError):
        decode_envelope("one.two", SECRET)
    with pytest.raises(ValueError):
        decode_envelope("!.!.!", SECRET)
    bad = payload(1)
    del bad["operations"]
    with pytest.raises(ValueError):
        apply_signed_document(make_envelope({"kid": "a"}, bad), SECRET, "doc-7", {})
    bad2 = payload(1, operations=[{"name": "x", "amount": float("nan"), "currency": "USD"}])
    with pytest.raises(ValueError):
        apply_signed_document(make_envelope({"kid": "a"}, bad2), SECRET, "doc-7", {})

def test_empty_operations_and_decimal_like_values_are_handled():
    ops = [
        {"name": "a", "amount": 0, "currency": "Z"},
        {"name": "b", "amount": -1.25, "currency": "A"},
        {"name": "c", "amount": 2, "currency": "A"},
    ]
    result = apply_signed_document(make_envelope({"kid": "a"}, payload(1, operations=ops)), SECRET, "doc-7", {})
    assert result["operation_count"] == 3
    assert result["total_by_currency"] == {"A": 0.75, "Z": 0}
    empty = apply_signed_document(make_envelope({"kid": "a"}, payload(2, operations=[])), SECRET, "doc-7", {"doc-7": 1})
    assert empty["total_by_currency"] == {}

