import base64
import hashlib
import hmac
import json
import math
import re

def _decode_part(text):
    if not isinstance(text, str) or not re.fullmatch('[A-Za-z0-9_-]+', text) or len(text) % 4 == 1:
        raise ValueError('invalid encoding')
    try:
        return base64.urlsafe_b64decode(text + '=' * (-len(text) % 4))
    except Exception as exc:
        raise ValueError('invalid encoding') from exc

def _object(raw):
    try:
        value = json.loads(raw.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid json') from exc
    if not isinstance(value, dict):
        raise ValueError('object required')
    return value

def decode_envelope(envelope: str, secret: bytes) -> tuple[str, dict, bytes]:
    if not isinstance(envelope, str):
        raise ValueError('invalid envelope')
    pieces = envelope.split('.')
    if len(pieces) != 3:
        raise ValueError('invalid envelope')
    header_raw = _decode_part(pieces[0])
    payload_raw = _decode_part(pieces[1])
    signature = _decode_part(pieces[2])
    header = _object(header_raw)
    payload = _object(payload_raw)
    kid = header.get('kid')
    if not isinstance(kid, str) or not kid:
        raise ValueError('invalid header')
    if not hmac.compare_digest(hmac.new(secret, (pieces[0] + '.' + pieces[1]).encode(), hashlib.sha256).digest(), signature):
        raise PermissionError('invalid signature')
    if not isinstance(payload.get('document_id'), str) or not payload['document_id']:
        raise ValueError('invalid document')
    if not isinstance(payload.get('version'), int) or isinstance(payload['version'], bool) or payload['version'] < 0:
        raise ValueError('invalid version')
    operations = payload.get('operations')
    if not isinstance(operations, list):
        raise ValueError('invalid operations')
    for op in operations:
        if not isinstance(op, dict) or not isinstance(op.get('name'), str) or (not op['name']) or (not isinstance(op.get('currency'), str)) or (not op['currency']):
            raise ValueError('invalid operation')
        amount = op.get('amount')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)):
            raise ValueError('invalid amount')
    return (kid, payload, signature)

def apply_signed_document(envelope: str, secret: bytes, expected_document_id: str, state: dict[str, int]) -> dict:
    _, payload, _ = decode_envelope(envelope, secret)
    document_id = payload['document_id']
    if document_id != expected_document_id:
        raise ValueError('unexpected document')
    version = payload['version']
    if document_id in state and version <= state[document_id]:
        raise ValueError('stale version')
    totals = {}
    for op in payload['operations']:
        totals[op['currency']] = totals.get(op['currency'], 0) + op['amount']
    ordered = {key: totals[key] for key in sorted(totals)}
    state[document_id] = version
    return {'document_id': document_id, 'version': version, 'operation_count': len(payload['operations']), 'total_by_currency': ordered}

