import hashlib
import hmac
import json

def process_release_webhook(payload: bytes, signature: str, signing_key: bytes, environment: str | None=None, page: int=1, page_size: int=20) -> dict:
    expected = hmac.new(signing_key, payload, hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid paging')
    try:
        events = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(events, list):
        raise ValueError('payload must be a list')
    groups = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        release = event.get('release')
        env = event.get('environment')
        status = event.get('status')
        duration = event.get('duration_ms')
        if not isinstance(release, str) or not release or (not isinstance(env, str)) or (not env) or (status not in ('success', 'failed')) or isinstance(duration, bool) or (not isinstance(duration, int)) or (duration < 0):
            raise ValueError('invalid event')
        if environment is not None and env != environment:
            continue
        group = groups.setdefault(release, [0, 0, 0, 0])
        group[0] += 1
        group[1] += status == 'success'
        group[2] += status == 'failed'
        group[3] += duration
    result = []
    for release, values in groups.items():
        average = round(values[3] / values[0], 2)
        result.append({'release': release, 'runs': values[0], 'successful': values[1], 'failed': values[2], 'average_duration_ms': average})
    result.sort(key=lambda item: (-item['successful'], item['average_duration_ms'], item['release']))
    start = (page - 1) * page_size
    return {'total_events': len(result), 'page': page, 'page_size': page_size, 'items': result[start:start + page_size]}

