import math
from datetime import datetime
from xml.etree import ElementTree as ET

def parse_heat_feed(xml_text: str) -> dict[str, list[tuple[str, float]]]:
    if not isinstance(xml_text, str):
        raise TypeError('xml_text must be a string')
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, ValueError, TypeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'feed':
        raise ValueError('invalid root')
    result = {}
    for station in root:
        if station.tag != 'station':
            raise ValueError('unexpected element')
        sid = station.get('id')
        if not sid:
            raise ValueError('invalid station')
        if sid in result:
            raise ValueError('duplicate station')
        rows = []
        for reading in station:
            if reading.tag != 'reading':
                raise ValueError('unexpected element')
            ts = reading.get('ts')
            raw = reading.get('load')
            if not ts or raw is None:
                raise ValueError('missing attribute')
            try:
                datetime.fromisoformat(ts.replace('Z', '+00:00'))
                value = float(raw)
            except (ValueError, TypeError):
                raise ValueError('invalid reading')
            if not math.isfinite(value):
                raise ValueError('invalid reading')
            rows.append((ts, value))
        if not rows:
            raise ValueError('empty station')
        rows.sort(key=lambda item: datetime.fromisoformat(item[0].replace('Z', '+00:00')))
        if len({item[0] for item in rows}) != len(rows):
            raise ValueError('duplicate timestamp')
        result[sid] = rows
    if not result:
        raise ValueError('empty feed')
    return result

def build_forecast(xml_text: str, horizon: int=3, window: int=3) -> list[dict[str, object]]:
    if isinstance(horizon, bool) or not isinstance(horizon, int) or horizon <= 0:
        raise ValueError('invalid horizon')
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('invalid window')
    data = parse_heat_feed(xml_text)
    output = []
    for station in sorted(data):
        values = [value for _, value in data[station]]
