import csv
import datetime
import os
import tempfile

def _read_events(text):
    try:
        rows = list(csv.reader(text.splitlines()))
    except csv.Error as e:
        raise ValueError(str(e))
    if not rows or rows[0] != ['card', 'timestamp', 'zone', 'event']:
        raise ValueError('invalid header')
    active = {}
    groups = {}
    for row in rows[1:]:
        if not row:
            continue
        if len(row) != 4:
            raise ValueError('invalid row')
        card, stamp, zone_text, event = row
        if not card or event not in ('IN', 'OUT'):
            raise ValueError('invalid field')
        try:
            datetime.datetime.strptime(stamp, '%Y-%m-%dT%H:%M')
            zone = int(zone_text)
        except Exception:
            raise ValueError('invalid value')
        if not 1 <= zone <= 20:
            raise ValueError('invalid zone')
        if event == 'IN':
            if card in active:
                raise ValueError('duplicate entry')
            active[card] = (stamp, zone)
        else:
            if card not in active or stamp < active[card][0]:
                raise ValueError('invalid exit')
            start, start_zone = active.pop(card)
            key = (start[:10], card)
            item = groups.setdefault(key, {'date': key[0], 'card': card, 'trips': 0, 'total_cents': 0, 'first_tap': start})
            item['trips'] += 1
            item['total_cents'] += min(500, 200 + 50 * abs(start_zone - zone))
            item['first_tap'] = min(item['first_tap'], start)
    if active:
        raise ValueError('unfinished journey')
    return [groups[k] for k in sorted(groups)]

def parse_fare_log(log_text: str) -> list[dict]:
    return _read_events(log_text)

def export_fare_report(log_text: str, output_path: str) -> int:
    records = parse_fare_log(log_text)
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.fare-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            writer.writerow(['date', 'card', 'trips', 'total_cents', 'first_tap'])
            for r in records:
                writer.writerow([r['date'], r['card'], r['trips'], r['total_cents'], r['first_tap']])
            f.flush()
            os.fsync(f.fileno())
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(records)

