    try:
        tree = ast.parse(expression, mode='eval').body
        return _value(tree, variables)
    except Exception as exc:
        raise ValueError('invalid expression') from exc

def _value(node, env):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name) and node.id in env:
        return env[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
        return +_value(node.operand, env) if isinstance(node.op, ast.UAdd) else -_value(node.operand, env)
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        a, b = (_value(node.left, env), _value(node.right, env))
        return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
