import base64
import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not 4 <= len(password) <= 128:
        raise ValueError('password length is invalid')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + ':' + base64.b64encode(digest).decode()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def create_operator(operator_id: str, station: str, password: str) -> dict[str, str]:
    if not isinstance(operator_id, str) or not isinstance(station, str):
        raise TypeError('operator fields must be strings')
    if not operator_id or not station:
        raise ValueError('operator fields cannot be empty')
    return {'operator_id': operator_id, 'station': station, 'password_hash': hash_password(password)}

def authenticate(record: dict[str, str], password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(record.get('password_hash'), str):
        return False
    return verify_password(password, record['password_hash'])

def ingest_telemetry(record: dict[str, str], password: str, reading: dict) -> dict | None:
    if not authenticate(record, password) or not isinstance(reading, dict):
        return None
    if not isinstance(record.get('station'), str):
        return None
    return {'station': record['station'], 'reading': dict(reading)}

