import datetime
import os
import tempfile

def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        return datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def calculate_reminders(records: list[dict], today: str) -> list[dict]:
    current = _date(today)
    chosen = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        for key in ('patient_id', 'name', 'phone', 'due_date'):
            if key not in record or not isinstance(record[key], str):
                raise ValueError('invalid record')
        due = _date(record['due_date'])
        sent = record.get('last_sent')
        if sent is not None:
            _date(sent)
        interval = record.get('interval_days', 30)
        if not isinstance(interval, int) or isinstance(interval, bool) or interval <= 0:
            raise ValueError('invalid interval')
        item = (due, len(chosen), record)
        old = chosen.get(record['patient_id'])
        if old is None or due >= old[0]:
            chosen[record['patient_id']] = item
    result = []
    for due, _, record in chosen.values():
        if due > current + datetime.timedelta(days=7):
            continue
        sent = record.get('last_sent')
        interval = record.get('interval_days', 30)
        if sent is not None and (current - _date(sent)).days < interval:
            continue
        status = 'overdue' if due < current else 'today' if due == current else 'upcoming'
        result.append({'patient_id': record['patient_id'], 'name': record['name'], 'phone': record['phone'], 'due_date': record['due_date'], 'status': status})
    result.sort(key=lambda x: (x['due_date'], x['name'], x['patient_id']))
    return result

def export_reminders(records: list[dict], today: str, destination: str) -> int:
    rows = calculate_reminders(records, today)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.DictWriter(stream, fieldnames=['patient_id', 'name', 'phone', 'due_date', 'status'])
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
        return len(rows)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

