import hashlib
import hmac
import os
import base64
import math

def create_operator_record(operator_id: str, password: str, role: str, created_at: int) -> dict:
    if not isinstance(operator_id, str) or not operator_id:
        raise ValueError('invalid operator id')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    if not isinstance(role, str) or not role:
        raise ValueError('invalid role')
    if not isinstance(created_at, int) or isinstance(created_at, bool):
        raise ValueError('invalid timestamp')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'operator_id': operator_id, 'role': role, 'created_at': created_at, 'salt': base64.b64encode(salt).decode(), 'password_hash': digest.hex()}

def verify_operator(record: dict, password: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(password, str):
            return False
        salt = base64.b64decode(record['salt'], validate=True)
        expected = record['password_hash']
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def summarize_events(events: list[dict], window_seconds: int) -> list[dict]:
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0:
        raise ValueError('invalid window')
    result = {}
    for event in events:
        if not isinstance(event, dict) or set(event) != {'timestamp', 'cell', 'robot', 'state', 'duration'}:
            raise ValueError('invalid event')
        t, cell, robot, state, duration = (event[k] for k in ('timestamp', 'cell', 'robot', 'state', 'duration'))
        if isinstance(t, bool) or not isinstance(t, (int, float)) or (not math.isfinite(t)):
            raise ValueError('invalid timestamp')
        if not isinstance(duration, (int, float)) or isinstance(duration, bool) or duration < 0 or (not math.isfinite(duration)):
            raise ValueError('invalid duration')
        if not isinstance(cell, str) or not cell or (not isinstance(robot, str)) or (not robot) or (state not in ('idle', 'running', 'fault')):
            raise ValueError('invalid event')
        start = math.floor(t / window_seconds) * window_seconds
        key = (start, cell)
        if key not in result:
            result[key] = [0, 0, 0, set()]
        row = result[key]
        row[0] += 1
        row[1] += duration
        row[2] += state == 'fault'
        row[3].add(robot)
    return [{'window_start': k[0], 'cell': k[1], 'event_count': v[0], 'total_duration': v[1], 'fault_count': v[2], 'robots': sorted(v[3])} for k, v in sorted(result.items())]

