from solution import issue_permit, verify_permit
import base64
import hashlib
import hmac
import json
import pytest

def test_round_trip_preserves_normalized_data():
    app = {'permit_id': 'A1', 'applicant': 'Miller', 'species': {'pine': 10}, 'blocks': [{'county': 'B', 'acres': 4, 'year': 2030, 'note': 'ridge'}], 'priority': 'standard'}
    token = issue_permit(app, {'permit_signing_key': 'abc'})
    assert verify_permit(token, {'permit_signing_key': 'abc'}) == {'permit_id': 'A1', 'applicant': 'Miller', 'species': {'pine': 10}, 'blocks': [{'county': 'B', 'acres': 4, 'year': 2030, 'note': 'ridge'}], 'priority': 'standard'}

def test_signature_matches_documented_format():
    app = {'permit_id': 'X', 'applicant': 'A', 'species': {}, 'blocks': []}
    token = issue_permit(app, {'permit_signing_key': 'key-123'})
    head, body, sig = token.split('.')
    expected = hmac.new(b'key-123', (head + '.' + body).encode(), hashlib.sha256).digest()
    assert base64.urlsafe_b64decode(sig + '===') == expected
    assert base64.urlsafe_b64decode(head + '===') == b'TP1'

def test_extra_fields_are_sorted_and_retained():
    app = {'z': 9, 'permit_id': 'Q', 'applicant': 'A', 'species': {}, 'blocks': [], 'a': {'x': 1}}
    result = verify_permit(issue_permit(app, {'permit_signing_key': 'k'}), {'permit_signing_key': 'k'})
    assert list(result) == ['permit_id', 'applicant', 'species', 'blocks', 'a', 'z']
    assert result['a'] == {'x': 1}

def test_invalid_application_values_raise():
    base = {'permit_id': 'P', 'applicant': 'A', 'species': {}, 'blocks': []}
    for change in [{'permit_id': ''}, {'applicant': ''}, {'species': {'pine': -1}}, {'species': {'': 2}}, {'blocks': [{'county': 'A', 'acres': 0, 'year': 2020}]}, {'blocks': [{'county': 'A', 'acres': 1, 'year': 1999}]}]:
        item = dict(base)
        item.update(change)
        with pytest.raises(ValueError):
            issue_permit(item, {'permit_signing_key': 'k'})

def test_malformed_or_modified_tokens_raise():
    app = {'permit_id': 'P', 'applicant': 'A', 'species': {}, 'blocks': []}
    token = issue_permit(app, {'permit_signing_key': 'k'})
    with pytest.raises(ValueError):
        verify_permit(token[:-1] + ('A' if token[-1] != 'A' else 'B'), {'permit_signing_key': 'k'})
    with pytest.raises(ValueError):
        verify_permit('bad.token', {'permit_signing_key': 'k'})
    with pytest.raises(ValueError):
        verify_permit(token, {'permit_signing_key': 'other'})

def test_inputs_are_not_mutated():
    app = {'permit_id': 'P', 'applicant': 'A', 'species': {'z': 1, 'a': 2}, 'blocks': [{'county': 'C', 'acres': 1, 'year': 2020}]}
    original = json.loads(json.dumps(app))
    issue_permit(app, {'permit_signing_key': 'k'})
    assert app == original

