import base64
import hashlib
import hmac
import json

def _key(config):
    try:
        value = config['permit_signing_key']
    except (KeyError, TypeError):
        raise ValueError('missing permit_signing_key')
    if not isinstance(value, str) or not value:
        raise ValueError('missing permit_signing_key')
    return value.encode()

def _normalize(app):
    if not isinstance(app, dict):
        raise ValueError('application must be an object')
    for name in ('permit_id', 'applicant'):
        if not isinstance(app.get(name), str) or not app[name]:
            raise ValueError('invalid application field')
    species = app.get('species')
    if not isinstance(species, dict):
        raise ValueError('invalid species')
    for name, count in species.items():
        if not isinstance(name, str) or not name or (not isinstance(count, int)) or isinstance(count, bool) or (count < 0):
            raise ValueError('invalid species')
    blocks = app.get('blocks')
    if not isinstance(blocks, list):
        raise ValueError('invalid blocks')
    copied = []
    for block in blocks:
        if not isinstance(block, dict) or not isinstance(block.get('county'), str) or (not block['county']):
            raise ValueError('invalid block')
        if not isinstance(block.get('year'), int) or isinstance(block['year'], bool) or (not 2000 <= block['year'] <= 2100):
            raise ValueError('invalid block')
        if not isinstance(block.get('acres'), (int, float)) or isinstance(block['acres'], bool) or block['acres'] <= 0:
            raise ValueError('invalid block')
        copied.append(dict(block))
    out = {'permit_id': app['permit_id'], 'applicant': app['applicant'], 'species': {k: species[k] for k in sorted(species)}, 'blocks': []}
    for block in sorted(copied, key=lambda x: (x['year'], x['county'], x['acres'])):
        out['blocks'].append({k: block[k] for k in sorted(block)})
    for key in sorted(set(app) - {'permit_id', 'applicant', 'species', 'blocks'}):
        out[key] = app[key]
    return out

def issue_permit(application: dict, config: dict) -> str:
    key = _key(config)
    payload = json.dumps(_normalize(application), ensure_ascii=False, separators=(',', ':'))
    head = base64.urlsafe_b64encode(b'TP1').decode().rstrip('=')
    body = base64.urlsafe_b64encode(payload.encode()).decode().rstrip('=')
    sig = hmac.new(key, (head + '.' + body).encode(), hashlib.sha256).digest()
    return head + '.' + body + '.' + base64.urlsafe_b64encode(sig).decode().rstrip('=')

def verify_permit(token: str, config: dict) -> dict:
    key = _key(config)
    try:
        head, body, encoded = token.split('.')
        if base64.urlsafe_b64decode(head + '===') != b'TP1':
            raise ValueError('invalid header')
        actual = base64.urlsafe_b64decode(encoded + '===')
        expected = hmac.new(key, (head + '.' + body).encode(), hashlib.sha256).digest()
        if not hmac.compare_digest(actual, expected):
            raise ValueError('invalid signature')
        value = json.loads(base64.urlsafe_b64decode(body + '===').decode())
        normalized = _normalize(value)
        if normalized != value:
            raise ValueError('invalid payload')
        return value
    except (ValueError, TypeError, KeyError, json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise ValueError('invalid permit token') from exc

