from solution import rank_funeral_quotes

import math
import os
import tempfile


def write_quotes(contents):
    handle = tempfile.NamedTemporaryFile(mode="w", delete=False)
    try:
        handle.write(contents)
        return handle.name
    finally:
        handle.close()


def test_ranks_by_price_provider_and_service():
    path = write_quotes(
        "Zeta,Traditional,1800\n"
        "Alpha,Memorial,1200\n"
        "Alpha,Direct,1200\n"
        "Beta,Cremation,900\n"
    )
    try:
        assert rank_funeral_quotes(path) == [
            {"provider": "Beta", "service": "Cremation", "price": 900.0},
            {"provider": "Alpha", "service": "Direct", "price": 1200.0},
            {"provider": "Alpha", "service": "Memorial", "price": 1200.0},
            {"provider": "Zeta", "service": "Traditional", "price": 1800.0},
        ]
    finally:
        os.unlink(path)


def test_ignores_blank_lines_and_applies_inclusive_price_filter():
    path = write_quotes("\nA,One,100\n\nB,Two,200\nC,Three,200.5\n")
    try:
        assert rank_funeral_quotes(path, max_price=200) == [
            {"provider": "A", "service": "One", "price": 100.0},
            {"provider": "B", "service": "Two", "price": 200.0},
        ]
    finally:
        os.unlink(path)


def test_pagination_is_one_based_and_preserves_rank_order():
    path = write_quotes("A,A,10\nB,B,20\nC,C,30\nD,D,40\nE,E,50\n")
    try:
        assert rank_funeral_quotes(path, page=2, page_size=2) == [
            {"provider": "C", "service": "C", "price": 30.0},
            {"provider": "D", "service": "D", "price": 40.0},
        ]
        assert rank_funeral_quotes(path, page=3, page_size=2) == [
            {"provider": "E", "service": "E", "price": 50.0}
        ]
    finally:
        os.unlink(path)


def test_empty_file_and_out_of_range_page_return_empty():
    path = write_quotes("\n")
    try:
        assert rank_funeral_quotes(path) == []
        assert rank_funeral_quotes(path, page=4, page_size=3) == []
    finally:
        os.unlink(path)


def test_invalid_pagination_and_filter_values_raise_value_error():
    path = write_quotes("A,Service,10\n")
    try:
        for kwargs in (
            {"page": 0},
            {"page_size": 0},
            {"max_price": -1},
            {"max_price": math.inf},
            {"max_price": math.nan},
        ):
            try:
                rank_funeral_quotes(path, **kwargs)
                assert False
            except ValueError:
                pass
    finally:
        os.unlink(path)


def test_malformed_rows_and_invalid_prices_raise_value_error():
    for contents in ("A,Service\n", "A,Service,nope\n", "A,Service,-2\n"):
        path = write_quotes(contents)
        try:
            try:
                rank_funeral_quotes(path)
                assert False
            except ValueError:
                pass
        finally:
            os.unlink(path)


def test_missing_file_raises_value_error():
    try:
        rank_funeral_quotes("/no/such/funeral-quotes-file")
        assert False
    except ValueError:
        pass

