import math
import subprocess

def rank_funeral_quotes(path: str, max_price: float | None=None, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    if max_price is not None and (not math.isfinite(max_price) or max_price < 0):
        raise ValueError('invalid maximum price')
    try:
        result = subprocess.run(['sort', '-t,', '-k3,3n', '-k1,1', '-k2,2', path], check=True, capture_output=True, text=True)
    except (OSError, subprocess.CalledProcessError) as exc:
        raise ValueError('unable to read quotes') from exc
    quotes = []
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split(',')
        if len(fields) != 3:
            raise ValueError('malformed quote')
        provider, service, text_price = (field.strip() for field in fields)
        try:
            price = float(text_price)
        except ValueError as exc:
            raise ValueError('invalid price') from exc
        if not math.isfinite(price) or price < 0:
            raise ValueError('invalid price')
        if max_price is None or price <= max_price:
            quotes.append({'provider': provider, 'service': service, 'price': price})
    start = (page - 1) * page_size
    return quotes[start:start + page_size]

