def build_index_batch(documents: list[dict], config: dict | None=None, page: int=1, page_size: int=50) -> dict:
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('page and page_size must be positive integers')
    if config is not None:
        if not isinstance(config, dict) or 'api_token' not in config:
            raise ValueError('api_token is required')
        token = config['api_token']
    else:
        token = os.environ.get('SEARCH_API_TOKEN')
    if not isinstance(token, str) or not token:
        raise ValueError('SEARCH_API_TOKEN is required')
    if not isinstance(documents, list):
        raise ValueError('documents must be a list')
    normalized = []
    ids = set()
    counts = Counter()
    for item in documents:
        if not isinstance(item, dict):
            raise ValueError('each document must be a dictionary')
        if set(item) < {'id', 'title', 'body', 'tags'}:
            raise ValueError('document fields are missing')
        ident, title, body, tags = (item['id'], item['title'], item['body'], item['tags'])
        if not all((isinstance(value, str) for value in (ident, title, body))) or not isinstance(tags, list) or (not all((isinstance(tag, str) for tag in tags))):
            raise ValueError('invalid document field type')
        ident, title, body = (ident.strip(), title.strip(), body.strip())
        if not ident or ident in ids:
            raise ValueError('document IDs must be unique and non-empty')
