        if not path.exists() or not path.is_file():
            raise FileNotFoundError(value)
        if path.suffix.lower() != suffix.lower():
            continue
        completed = subprocess.run(['wc', '-l', value], capture_output=True, text=True, check=True)
        lines = int(completed.stdout.split()[0])
        records.append({'path': value, 'lines': lines})
    records.sort(key=lambda item: (-item['lines'], item['path']))
    start = (page - 1) * page_size
    return {'total_documents': len(records), 'total_lines': sum((item['lines'] for item in records)), 'documents': records[start:start + page_size]}

