import hashlib
import hmac
import os

def register_technician(pin: str) -> str:
    if not isinstance(pin, str) or len(pin) < 4:
        raise ValueError('pin must contain at least four characters')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return '100000$' + salt.hex() + '$' + digest.hex()

def _matches(pin: str, credential: str) -> bool:
    if not isinstance(pin, str) or not isinstance(credential, str):
        return False
    try:
        count, salt_hex, digest_hex = credential.split('$', 2)
        iterations = int(count)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
    except (ValueError, TypeError):
        return False
    if iterations < 100000:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
    return hmac.compare_digest(actual, expected)

def reserve_part(pin: str, credential: str, part_number: str, inventory: dict[str, int]) -> bool:
    if not isinstance(pin, str) or not isinstance(credential, str) or (not isinstance(part_number, str)):
        return False
    if not _matches(pin, credential):
        return False
    if part_number not in inventory or inventory[part_number] <= 0:
        return False
    inventory[part_number] -= 1
    return True

