from datetime import datetime

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid datetime')
    try:
        return datetime.fromisoformat(value[:-1])
    except ValueError:
        raise ValueError('invalid datetime')

def dispatch_campaign(requester: dict, campaigns: list[dict], campaign_id: str, as_of: str, batch_size: int=100) -> dict:
    if not isinstance(batch_size, int) or isinstance(batch_size, bool) or batch_size <= 0:
        raise ValueError('invalid batch size')
    current = _time(as_of)
    selected = next((item for item in campaigns if item.get('id') == campaign_id), None)
    if selected is None:
        raise KeyError(campaign_id)
    if not isinstance(selected.get('message'), str) or not selected['message']:
        raise ValueError('invalid message')
    if selected.get('status') != 'scheduled' or _time(selected.get('scheduled_at')) > current:
        raise ValueError('campaign is not ready')
    if not isinstance(requester, dict) or requester.get('tenant_id') != selected.get('tenant_id'):
        raise PermissionError('not permitted')
    roles = requester.get('roles', [])
    if requester.get('id') != selected.get('owner_id') and 'campaign_manager' not in roles and ('admin' not in roles):
        raise PermissionError('not permitted')
    groups = {}
    for recipient in selected.get('recipients', []):
        if not isinstance(recipient.get('phone'), str) or not isinstance(recipient.get('carrier'), str) or (not isinstance(recipient.get('opted_in'), bool)):
            raise ValueError('invalid recipient')
        if recipient['opted_in'] and recipient['phone'].strip():
            groups.setdefault(recipient['carrier'], []).append(recipient['phone'].strip())
    batches = []
    for carrier in sorted(groups):
        phones = sorted(groups[carrier])
        for index in range(0, len(phones), batch_size):
            part = phones[index:index + batch_size]
            batches.append({'carrier': carrier, 'phones': part, 'count': len(part)})
    selected['status'] = 'dispatched'
    selected['dispatched_at'] = as_of
    return {'campaign_id': campaign_id, 'message': selected['message'], 'total_recipients': sum((x['count'] for x in batches)), 'batches': batches}

