import csv
import math
import os
import tempfile

def export_climate_summary(readings: list[dict]) -> str:
    groups = {}
    for item in readings:
        if not isinstance(item, dict) or set(item) != {'zone', 'temperature', 'humidity', 'timestamp'}:
            raise ValueError('invalid reading')
        zone = item['zone']
        temperature = item['temperature']
        humidity = item['humidity']
        timestamp = item['timestamp']
        if not isinstance(zone, str) or not zone:
            raise ValueError('invalid zone')
        if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) or (not math.isfinite(temperature)):
            raise ValueError('invalid temperature')
        if isinstance(humidity, bool) or not isinstance(humidity, (int, float)) or (not math.isfinite(humidity)) or (not 0 <= humidity <= 100):
            raise ValueError('invalid humidity')
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or (not 0 <= timestamp <= 1439):
            raise ValueError('invalid timestamp')
        if 360 <= timestamp < 1080:
            groups.setdefault(zone, []).append((temperature, humidity))
    rows = [['zone', 'reading_count', 'average_temperature', 'minimum_humidity', 'maximum_humidity']]
    ordered = sorted(groups.items(), key=lambda pair: (-len(pair[1]), pair[0]))
    for zone, values in ordered:
        temperatures = [value[0] for value in values]
        humidities = [value[1] for value in values]
        rows.append([zone, str(len(values)), f'{sum(temperatures) / len(values):.2f}', f'{min(humidities):.2f}', f'{max(humidities):.2f}'])
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            csv.writer(handle, lineterminator='\n').writerows(rows)
        with open(path, newline='') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

