import os
import zipfile
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def extract_work_order_archive(archive_path: str, base_dir: str) -> list[str]:
    base = os.path.realpath(base_dir)
    os.makedirs(base, exist_ok=True)
    names = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename
            if info.is_dir():
                target = os.path.realpath(os.path.join(base, name))
                if os.path.commonpath([base, target]) != base:
                    raise ValueError('invalid archive member')
                os.makedirs(target, exist_ok=True)
                continue
            target = os.path.realpath(os.path.join(base, name))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('invalid archive member')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                output.write(source.read())
            names.append(name)
    return sorted(names)

def _split_escaped(value, delimiter):
    result = []
    current = []
    escaped = False
    for char in value:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == delimiter:
            result.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    result.append(''.join(current))
    return result

def summarize_maintenance_log(text: str) -> list[dict]:
    groups = {}
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split_escaped(raw, ';')
        if len(fields) != 4:
            raise ValueError('invalid record')
        fields = [field.strip() for field in fields]
        try:
            day = date.fromisoformat(fields[0])
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if not fields[1]:
            raise ValueError('empty equipment')
        try:
            hours = Decimal(fields[2])
        except InvalidOperation as exc:
            raise ValueError('invalid hours') from exc
        if not hours.is_finite() or hours < 0:
            raise ValueError('invalid hours')
        parts = _split_escaped(fields[3], ',') if fields[3] else []
        parts = [part.strip() for part in parts]
        if any((not part for part in parts)):
            raise ValueError('empty part')
        item = groups.setdefault(fields[1], {'jobs': 0, 'hours': Decimal(0), 'last': day, 'parts': {}})
        item['jobs'] += 1
        item['hours'] += hours
        item['last'] = max(item['last'], day)
        for part in parts:
            item['parts'][part] = item['parts'].get(part, 0) + 1
    result = []
    for equipment, item in groups.items():
        total = item['hours'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'equipment': equipment, 'jobs': item['jobs'], 'total_hours': float(total), 'last_service': item['last'].isoformat(), 'parts': dict(sorted(item['parts'].items()))})
    return sorted(result, key=lambda x: (-x['total_hours'], x['equipment']))

