from datetime import date

def generate_attendance_report(requester: dict, students: list[dict], sessions: list[dict], student_id: str, start_date: str, end_date: str) -> dict:

    def parse(value):
        if not isinstance(value, str):
            raise ValueError('invalid date')
        try:
            return date.fromisoformat(value)
        except ValueError:
            raise ValueError('invalid date')
    start = parse(start_date)
    end = parse(end_date)
    if start > end:
        raise ValueError('reversed range')
    student = next((x for x in students if x.get('id') == student_id), None)
    if student is None:
        raise ValueError('unknown student')
    if not (student.get('tenant_id') == requester.get('tenant_id') and (requester.get('role') in ('teacher', 'admin') or student.get('guardian_id') == requester.get('id'))):
        raise PermissionError('not permitted')
    statuses = ('present', 'late', 'absent', 'excused')
    totals = {x: 0 for x in statuses}
    daily = {}
    for session in sessions:
        if session.get('status') not in statuses:
            raise ValueError('invalid status')
        if not isinstance(session.get('date'), str):
            raise ValueError('invalid date')
        current = parse(session['date'])
        if session.get('student_id') != student_id or session.get('tenant_id') != student.get('tenant_id') or current < start or (current > end):
            continue
        totals[session['status']] += 1
        row = daily.setdefault(session['date'], {x: 0 for x in statuses})
        row[session['status']] += 1
    total = sum(totals.values())
    totals['total'] = total
    rows = []
    for key in sorted(daily):
        row = {'date': key, **daily[key]}
        row['total'] = sum(daily[key].values())
        rows.append(row)
    return {'student_id': student_id, 'student_name': student['name'], 'from': start_date, 'to': end_date, 'totals': totals, 'attendance_rate': round((totals['present'] + totals['late']) * 100 / total, 2) if total else 0.0, 'daily': rows}

