import hashlib
import hmac
import os
from datetime import date

def make_credential(pin: str) -> str:
    if not isinstance(pin, str) or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def check_credential(credential: str, pin: str) -> bool:
    if not isinstance(credential, str) or not isinstance(pin, str):
        return False
    if not pin.isdigit() or not 4 <= len(pin) <= 12:
        return False
    try:
        salt_text, digest_text = credential.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def attendance_report(students: list[dict], events: list[dict], credentials: dict[str, str], pins: dict[str, str], start: str, end: str) -> list[dict]:
    try:
        first = date.fromisoformat(start)
        last = date.fromisoformat(end)
    except (TypeError, ValueError):
        raise ValueError('invalid date range')
    if first > last:
        raise ValueError('invalid date range')
    by_id = {}
    for student in students:
        sid = student['id']
        if sid in by_id:
            raise ValueError('duplicate student')
        by_id[sid] = student
    selected = {}
    for event in events:
        sid = event['student_id']
        if sid not in by_id:
            raise ValueError('unknown student')
        try:
            day = date.fromisoformat(event['date'])
        except (TypeError, ValueError):
            raise ValueError('invalid event date')
        status = event['status']
        if status not in {'present', 'late', 'absent'}:
            raise ValueError('invalid status')
        if first <= day <= last:
            selected[sid, day] = status
    output = []
    for student in students:
        sid = student['id']
        if sid not in credentials or sid not in pins or (not check_credential(credentials[sid], pins[sid])):
            continue
        counts = {'present': 0, 'late': 0, 'absent': 0}
        for (event_sid, _), status in selected.items():
            if event_sid == sid:
                counts[status] += 1
        total = sum(counts.values())
        output.append({'id': sid, 'name': student['name'], 'grade': student['grade'], 'present': counts['present'], 'late': counts['late'], 'absent': counts['absent'], 'recorded_days': total, 'attendance_rate': (counts['present'] + counts['late']) / total if total else 0.0})
    output.sort(key=lambda item: (item['grade'], item['name'].casefold(), item['id']))
    return output

