import tempfile

def issue_passes(trips: list[dict], destination: str) -> dict:
    items = []
    for index, trip in enumerate(trips):
        required = ('passenger', 'route', 'fare', 'travel_date', 'status')
        if any((key not in trip for key in required)):
            raise ValueError('missing field')
        passenger = trip['passenger']
        route = trip['route']
        date_text = trip['travel_date']
        status = trip['status']
        if not isinstance(passenger, str) or not passenger or (not isinstance(route, str)) or (not route):
            raise ValueError('invalid text')
        if not isinstance(date_text, str):
            raise ValueError('invalid date')
        try:
            datetime.date.fromisoformat(date_text)
        except ValueError:
            raise ValueError('invalid date')
        if status not in ('confirmed', 'cancelled'):
            raise ValueError('invalid status')
        try:
            value = decimal.Decimal(str(trip['fare']))
        except (decimal.InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid fare')
        if not value.is_finite() or value < 0:
            raise ValueError('invalid fare')
        cents = int((value * 100).quantize(decimal.Decimal('1'), rounding=decimal.ROUND_HALF_UP))
        if status == 'confirmed':
            items.append((date_text, route, passenger, index, passenger, route, cents))
    items.sort(key=lambda item: item[:4])
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(('ticket_id', 'passenger', 'route', 'travel_date', 'fare'))
            for number, item in enumerate(items, 1):
                writer.writerow((f'T{number:04d}', item[4], item[5], item[0], f'{item[6] / 100:.2f}'))
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'tickets': len(items), 'total_fare_cents': sum((item[6] for item in items))}

