import sqlite3
from numbers import Real

def get_rights_report(conn: sqlite3.Connection, territory: str | None, minimum_share: float, sort_by: str, descending: bool, page: int, page_size: int) -> list[dict]:
    if territory is not None and (not isinstance(territory, str) or not territory):
        raise ValueError('invalid territory')
    if isinstance(minimum_share, bool) or not isinstance(minimum_share, Real) or (not 0 <= minimum_share <= 100):
        raise ValueError('invalid minimum_share')
    if sort_by not in {'title', 'average_share', 'territories', 'book_id'}:
        raise ValueError('invalid sort_by')
    if not isinstance(descending, bool):
        raise ValueError('invalid descending')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page_size')
    sql = 'SELECT book_id, title, territory, royalty_share FROM rights WHERE active = 1'
    params = []
    if territory is not None:
        sql += ' AND territory = ?'
        params.append(territory)
    sql += ' AND royalty_share >= ?'
    params.append(minimum_share)
    groups = {}
    for book_id, title, row_territory, share in conn.execute(sql, params):
        item = groups.setdefault(book_id, {'book_id': book_id, 'title': title, 'territories': set(), 'shares': []})
        item['territories'].add(row_territory)
        item['shares'].append(share)
    result = []
    for item in groups.values():
        result.append({'book_id': item['book_id'], 'title': item['title'], 'territories': len(item['territories']), 'average_share': round(sum(item['shares']) / len(item['shares']), 2)})
    result.sort(key=lambda x: x['book_id'])
    result.sort(key=lambda x: x[sort_by], reverse=descending)
    start = (page - 1) * page_size
    return result[start:start + page_size]

