import hashlib
import hmac
import json

def verify_route_manifest(manifest: str, signature: str, signing_key: str) -> dict:
    try:
        data = json.loads(manifest)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid manifest') from exc
    if not isinstance(data, dict):
        raise ValueError('invalid manifest')
    if not isinstance(data.get('route_id'), str) or not data['route_id']:
        raise ValueError('invalid route_id')
    stops = data.get('stops')
    if not isinstance(stops, list):
        raise ValueError('invalid stops')
    for stop in stops:
        if not isinstance(stop, dict):
            raise ValueError('invalid stop')
        if not isinstance(stop.get('address'), str):
            raise ValueError('invalid address')
        minutes = stop.get('minutes')
        if not isinstance(minutes, int) or isinstance(minutes, bool) or minutes < 0:
            raise ValueError('invalid minutes')
    if not isinstance(signature, str) or len(signature) != 64:
        raise ValueError('invalid signature')
    try:
        int(signature, 16)
    except ValueError as exc:
        raise ValueError('invalid signature') from exc
    expected = hmac.new(signing_key.encode('utf-8'), manifest.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    return data

