from lxml import etree

def summarize_season_tickets(xml_text: str, season: int, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not isinstance(xml_text, str):
        raise ValueError('xml_text must be a string')
    if isinstance(season, bool) or not isinstance(season, int):
        raise ValueError('invalid season')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'feed':
        raise ValueError('invalid root')
    groups = {}
    for ticket in root.findall('ticket'):
        attrs = ticket.attrib
        if any((not attrs.get(name) for name in ('id', 'section', 'status'))):
            raise ValueError('invalid ticket')
        try:
            ticket_season = int(attrs['season'])
            price = Decimal(attrs['price'])
        except (KeyError, ValueError, InvalidOperation) as exc:
            raise ValueError('invalid ticket') from exc
        if price < 0:
            raise ValueError('invalid price')
        if ticket_season == season and attrs['status'] == 'active':
            section = attrs['section']
            if section not in groups:
                groups[section] = [0, Decimal('0')]
            groups[section][0] += 1
            groups[section][1] += price
    result = []
    for section, (count, revenue) in groups.items():
        rounded = revenue.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'section': section, 'tickets': count, 'revenue': float(rounded)})
    result.sort(key=lambda item: (-item['revenue'], item['section']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

