from pathlib import Path

def write_valuation_report(base_dir: str, relative_name: str, property_address: str, valuation: float) -> str:
    if not relative_name or relative_name.endswith((os.sep, os.altsep or '\\')):
        raise ValueError('invalid file name')
    if not math.isfinite(valuation) or valuation < 0:
        raise ValueError('invalid valuation')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('invalid file name')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(f'Property: {property_address}\nEstimated value: ${valuation:,.2f}\n', encoding='utf-8')
    return str(target)

