import hashlib
import hmac
import os
import re

def issue_subscription_receipts(records: list[dict], month: str, page: int, page_size: int) -> list[dict]:
    if not isinstance(month, str) or re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', month) is None:
        raise ValueError('month must be YYYY-MM')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be at least 1')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('page_size must be between 1 and 100')
    key = os.environ.get('MAGAZINE_SIGNING_KEY')
    if key is None:
        raise RuntimeError('MAGAZINE_SIGNING_KEY is required')
    grouped = {}
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('subscriber_id', 'plan', 'cents', 'start_month'))):
            raise ValueError('invalid record')
        subscriber_id = record['subscriber_id']
        plan = record['plan']
        cents = record['cents']
        start_month = record['start_month']
        if not isinstance(subscriber_id, str) or not subscriber_id:
            raise ValueError('invalid subscriber_id')
        if not isinstance(plan, str) or not plan:
            raise ValueError('invalid plan')
        if not isinstance(cents, int) or isinstance(cents, bool) or cents <= 0:
            raise ValueError('invalid cents')
        if not isinstance(start_month, str) or re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', start_month) is None:
            raise ValueError('invalid start_month')
        if start_month == month:
            item = grouped.setdefault(subscriber_id, {'total_cents': 0, 'issue_count': 0, 'plans': set()})
            item['total_cents'] += cents
            item['issue_count'] += 1
            item['plans'].add(plan)
    rows = []
    for subscriber_id, item in grouped.items():
        plans = sorted(item['plans'])
        total = item['total_cents']
        count = item['issue_count']
        payload = f"{month}|{subscriber_id}|{count}|{total}|{','.join(plans)}"
        signature = hmac.new(key.encode(), payload.encode(), hashlib.sha256).hexdigest()
        rows.append({'subscriber_id': subscriber_id, 'total_cents': total, 'issue_count': count, 'plans': plans, 'signature': signature})
    rows.sort(key=lambda row: (-row['total_cents'], row['subscriber_id']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

