import hashlib
import hmac
import json

def process_water_plan(text: str, secret: bytes) -> dict:
    if not isinstance(text, str) or not isinstance(secret, bytes) or (not secret):
        raise ValueError('invalid input')
    first, sep, body = text.partition('\n')
    if not sep or not first.startswith('sig='):
        raise ValueError('invalid signature line')
    supplied = first[4:]
    if len(supplied) != 64 or any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body)
    except (ValueError, TypeError):
        raise ValueError('invalid json')
    if not isinstance(data, dict) or set(data) != {'period', 'capacities', 'requests'}:
        raise ValueError('invalid plan')
    period = data['period']
    capacities = data['capacities']
    requests = data['requests']
    if not isinstance(period, str) or not period or (not isinstance(capacities, dict)) or (not isinstance(requests, list)):
        raise ValueError('invalid plan')
    for basin, capacity in capacities.items():
        if not isinstance(basin, str) or not basin or (not isinstance(capacity, int)) or isinstance(capacity, bool) or (capacity < 0):
            raise ValueError('invalid capacity')
    parsed = []
    for index, item in enumerate(requests):
        if not isinstance(item, dict) or set(item) != {'basin', 'farmer', 'amount', 'priority'}:
            raise ValueError('invalid request')
        basin, farmer, amount, priority = (item[k] for k in ('basin', 'farmer', 'amount', 'priority'))
        if not isinstance(basin, str) or not basin or (not isinstance(farmer, str)) or (not farmer):
            raise ValueError('invalid request')
        if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0 or (not isinstance(priority, int)) or isinstance(priority, bool):
            raise ValueError('invalid request')
        if basin not in capacities:
            raise ValueError('unknown basin')
        parsed.append((basin, farmer, amount, priority, index))
    remaining = dict(capacities)
    totals = {basin: 0 for basin in capacities}
    allocations = []
    for basin, farmer, amount, priority, index in sorted(parsed, key=lambda x: (x[0], -x[3], x[1], x[4])):
        granted = min(amount, remaining[basin])
        remaining[basin] -= granted
        totals[basin] += granted
        allocations.append({'basin': basin, 'farmer': farmer, 'granted': granted})
    return {'period': period, 'allocations': allocations, 'remaining': {k: remaining[k] for k in sorted(remaining)}, 'totals': {k: totals[k] for k in sorted(totals)}}

