import datetime
import math
import secrets
import string

def summarize_catches(records: list[dict], species: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    totals = {}
    for record in records:
        if not isinstance(record, dict) or 'species' not in record or 'kg' not in record:
            raise ValueError('invalid record')
        name = record['species']
        amount = record['kg']
        if not isinstance(name, str) or not name or (not isinstance(amount, (int, float))) or isinstance(amount, bool) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid record')
        if species is None or name == species:
            totals[name] = totals.get(name, 0) + amount
    ordered = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    items = [{'species': name, 'total_kg': round(amount, 2)} for name, amount in ordered[start:start + page_size]]
    return {'items': items, 'page': page, 'page_size': page_size, 'total_species': len(ordered)}

def issue_submission_code(vessel_id: str, report_date: str) -> str:
    if not isinstance(vessel_id, str) or not 1 <= len(vessel_id.strip()) <= 30:
        raise ValueError('invalid vessel')
    if not isinstance(report_date, str):
        raise ValueError('invalid date')
    try:
        parsed = datetime.date.fromisoformat(report_date)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != report_date:
        raise ValueError('invalid date')
    alphabet = string.ascii_uppercase + string.digits
    return ''.join((secrets.choice(alphabet) for _ in range(16)))

