            days = item['transit_days']
            base, surcharge = (item['base_price'], item['surcharge'])
            if isinstance(days, bool) or not isinstance(days, int) or days > max_transit_days or isinstance(base, bool) or isinstance(surcharge, bool) or (not isinstance(base, (int, float))) or (not isinstance(surcharge, (int, float))) or (not math.isfinite(base)) or (not math.isfinite(surcharge)):
                continue
            total = round(base + surcharge, 2)
            if total < 0:
                continue
            kept.append({'carrier': item['carrier'], 'service': item['service'], 'total': total, 'transit_days': days, 'currency': 'USD'})
