import os
import tempfile
STATUSES = ('CHECKED_IN', 'LOADED', 'CLAIMED', 'LOST')

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.datetime.fromisoformat(value[:-1] + '+00:00').timestamp()
    except (ValueError, OverflowError):
        raise ValueError('invalid timestamp')

def normalize_baggage_events(records: list[dict]) -> list[dict]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    latest = {}
    for index, record in enumerate(records):
        if not isinstance(record, dict) or set(record) != {'bag_id', 'timestamp', 'airport', 'status', 'flight'}:
            raise ValueError('invalid record')
        bag = record['bag_id']
        airport = record['airport']
        status = record['status']
        flight = record['flight']
        if not isinstance(bag, str) or not bag or (not isinstance(flight, str)) or (not flight):
            raise ValueError('invalid text')
        if not isinstance(airport, str) or len(airport) != 3 or (not airport.isascii()) or (not airport.isupper()) or (not airport.isalpha()):
            raise ValueError('invalid airport')
        if status not in STATUSES:
            raise ValueError('invalid status')
        stamp = _time(record['timestamp'])
        old = latest.get(bag)
        if old is None or (stamp, index) >= (old[0], old[1]):
            latest[bag] = (stamp, index, record)
    result = []
    for bag in sorted(latest):
        record = latest[bag][2]
        result.append({'bag_id': bag, 'status': record['status'], 'airport': record['airport'], 'flight': record['flight'], 'last_seen': record['timestamp']})
    return result

def export_baggage_report(records: list[dict], output_path: str) -> dict:
    rows = normalize_baggage_events(records)
    counts = {status: 0 for status in STATUSES}
    for row in rows:
        counts[row['status']] += 1
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.baggage-')
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.DictWriter(stream, fieldnames=['bag_id', 'status', 'airport', 'flight', 'last_seen'])
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, output_path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'total_bags': len(rows), 'status_counts': counts}

