    try:
        data = json.loads(text)
    except Exception as exc:
        raise ValueError('invalid inventory JSON') from exc
    if not isinstance(data, list):
        raise ValueError('inventory must be a list')
    result = []
    required = {'serial', 'subject', 'expires', 'status', 'priority'}
    for item in data:
        if not isinstance(item, dict) or set(item) != required:
            raise ValueError('invalid certificate record')
        if not isinstance(item['serial'], str) or not item['serial']:
            raise ValueError('invalid serial')
        if not isinstance(item['subject'], str) or not item['subject']:
            raise ValueError('invalid subject')
        stamp = _timestamp(item['expires'])
        if item['status'] not in {'ACTIVE', 'REVOKED', 'EXPIRED'}:
            raise ValueError('invalid status')
        if isinstance(item['priority'], bool) or not isinstance(item['priority'], int) or (not 0 <= item['priority'] <= 9):
            raise ValueError('invalid priority')
        result.append({'serial': item['serial'], 'subject': item['subject'], 'expires': stamp.strftime('%Y-%m-%dT%H:%M:%SZ'), 'status': item['status'], 'priority': item['priority']})
    return result

