    if isinstance(window_days, bool) or not isinstance(window_days, int) or window_days < 0:
        raise ValueError('window_days must be non-negative')
    end = start + timedelta(days=window_days)
    selected = [dict(record) for record in records if record['status'] == 'ACTIVE' and start < _timestamp(record['expires']) <= end]
    return sorted(selected, key=lambda r: (_timestamp(r['expires']), -r['priority'], r['serial']))

