from pathlib import Path

def write_vibration_log(base_dir: str, relative_name: str, readings: list[tuple[float, float]]) -> str:
    if not relative_name:
        raise ValueError('relative_name must not be empty')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('relative_name is outside base_dir')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', encoding='utf-8', newline='') as output:
        output.write('timestamp,acceleration\n')
        for timestamp, acceleration in readings:
            output.write(f'{timestamp},{acceleration}\n')
    return str(target)

import csv
import math
import os
import tempfile

def export_tree_report(records: list[dict], destination: str, borough: str | None=None) -> int:
    if borough is not None and (not isinstance(borough, str)):
        raise ValueError('invalid borough')
    groups = {}
    required = ('tree_id', 'species', 'borough', 'status', 'height_m', 'risk_score')
    for record in records:
        if not isinstance(record, dict) or any((key not in record for key in required)):
            raise ValueError('invalid record')
        if record['status'] not in ('active', 'needs_pruning', 'removed'):
            raise ValueError('invalid status')
        height = record['height_m']
        risk = record['risk_score']
        if isinstance(height, bool) or not isinstance(height, (int, float)) or (not math.isfinite(height)) or (height < 0):
            raise ValueError('invalid height')
        if isinstance(risk, bool) or not isinstance(risk, (int, float)) or (not math.isfinite(risk)) or (not 0 <= risk <= 100):
            raise ValueError('invalid risk')
        if record['status'] == 'removed' or (borough is not None and record['borough'] != borough):
            continue
        species = record['species']
        if species not in groups:
            groups[species] = []
        groups[species].append((height, risk))
    rows = [['species', 'count', 'average_height_m', 'max_risk_score']]
    ordered = sorted(groups, key=lambda name: (-len(groups[name]), name.casefold(), name))
    for species in ordered:
        values = groups[species]
        average = round(sum((item[0] for item in values)) / len(values), 1)
        rows.append([species, str(len(values)), f'{average:.1f}', f'{max((item[1] for item in values)):g}'])
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.tree-report-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as stream:
            csv.writer(stream, lineterminator='\n').writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows) - 1

