from solution import generate_statement

def test_empty_statement_has_account_and_header():
    assert generate_statement('ACCT-001', []) == 'Account,ACCT-001\nDate,Description,Amount (cents),Balance (cents)\n'

def test_transactions_preserve_order_and_values():
    transactions = [{'date': '2025-01-03', 'description': 'Coffee', 'amount_cents': -425, 'balance_cents': 1575}, {'date': '2025-01-04', 'description': 'Salary', 'amount_cents': 250000, 'balance_cents': 251575}]
    expected = 'Account,ACCT-002\nDate,Description,Amount (cents),Balance (cents)\n2025-01-03,Coffee,-425,1575\n2025-01-04,Salary,250000,251575\n'
    assert generate_statement('ACCT-002', transactions) == expected

def test_unicode_content_is_preserved():
    transactions = [{'date': '2025-03-10', 'description': 'Café ☕ — résumé', 'amount_cents': -99, 'balance_cents': 100}]
    result = generate_statement('épargne', transactions)
    assert 'Account,épargne\n' in result
    assert '2025-03-10,Café ☕ — résumé,-99,100\n' in result

def test_numeric_values_are_written_as_supplied():
    transactions = [{'date': 20250101, 'description': 'Opening', 'amount_cents': 0, 'balance_cents': 0}]
    assert generate_statement('A', transactions).endswith('20250101,Opening,0,0\n')

def test_missing_transaction_key_raises_key_error():
    transactions = [{'date': '2025-01-01', 'description': 'Incomplete', 'amount_cents': 10}]
    try:
        generate_statement('A', transactions)
        assert False
    except KeyError as exc:
