import hmac
import json

def plan_routes(key: bytes, payload: bytes, signature: str, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid paging')
    if not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')) or any((c not in '0123456789abcdef' for c in signature[7:])):
        raise ValueError('invalid signature')
    expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected.encode(), signature[7:].encode()):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(data, dict) or not isinstance(data.get('stops'), list):
        raise ValueError('invalid payload')
    groups = {}
    for stop in data['stops']:
        if not isinstance(stop, dict):
            raise ValueError('invalid stop')
        zone = stop.get('zone')
        cases = stop.get('cases')
        priority = stop.get('priority')
        if not isinstance(zone, str) or not zone or isinstance(cases, bool) or (not isinstance(cases, int)) or (cases < 0) or isinstance(priority, bool) or (not isinstance(priority, int)) or (priority < 0):
