        item = groups.setdefault(zone, {'zone': zone, 'stops': 0, 'cases': 0, 'priority': 0})
        item['stops'] += 1
        item['cases'] += cases
        item['priority'] = max(item['priority'], priority)
    routes = sorted(groups.values(), key=lambda x: (-x['cases'], -x['priority'], x['zone']))
