import ast
import operator

def _evaluate(expression, names):
    tree = ast.parse(expression, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and (node.value is None or isinstance(node.value, (int, float, bool))):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in names:
                raise NameError(node.id)
            return names[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Mod}:
            fn = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv, ast.Mod: operator.mod}[type(node.op)]
            return fn(visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.UAdd, ast.USub, ast.Not}:
            fn = {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)]
            return fn(visit(node.operand))
        if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
            value = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = visit(child)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, child in zip(node.ops, node.comparators):
                right = visit(child)
                fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)]
                if not fn(left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.IfExp):
            return visit(node.body) if visit(node.test) else visit(node.orelse)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
        raise ValueError('unsupported expression')
    return (tree, visit(tree))

