    results = []
    tree = ast.parse(expression, mode='eval').body
    for position, document in enumerate(documents):
        names = dict(variables)
        names.update({'pages': document['pages'], 'priority': document['priority'], 'signed': document['signed'], 'id': document['id']})
        _, score = _evaluate(expression, names)
        boolean_expression = isinstance(tree, (ast.BoolOp, ast.Compare))
        if boolean_expression and isinstance(score, bool):
