import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_pin(pin: str, stored_pin: str) -> bool:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not isinstance(stored_pin, str):
        return False
    try:
        salt_text, digest_text = stored_pin.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def reconcile_ore(produced: list[int], shipped: list[int], approval_pin: str, stored_pin: str) -> dict:
    for values in (produced, shipped):
        if not isinstance(values, list):
            raise TypeError('quantities must be lists')
        for value in values:
            if not isinstance(value, int):
                raise TypeError('quantities must contain integers')
            if value < 0:
                raise ValueError('quantities cannot be negative')
    produced_total = sum(produced)
    shipped_total = sum(shipped)
    authorized = verify_pin(approval_pin, stored_pin)
    variance = produced_total - shipped_total
    return {'produced': produced_total, 'shipped': shipped_total, 'variance': variance, 'authorized': authorized, 'status': 'approved' if authorized and variance == 0 else 'review'}

