import xml.etree.ElementTree as ET
from datetime import datetime

def _read(xml_text):
    if not isinstance(xml_text, str) or not xml_text.strip():
        raise ValueError('invalid input')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'feed':
        raise ValueError('wrong root')
    result = []
    for inc in root.findall('incident'):
        attrs = inc.attrib
        if any((not attrs.get(k) for k in ('id', 'occurred', 'status'))):
            raise ValueError('missing incident attribute')
        if attrs['status'] not in ('open', 'closed', 'cancelled'):
            raise ValueError('invalid status')
        stamp = attrs['occurred']
        if not stamp.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            datetime.fromisoformat(stamp[:-1] + '+00:00')
        except Exception as exc:
            raise ValueError('invalid timestamp') from exc
        locs = inc.findall('location')
        groups = inc.findall('units')
        if len(locs) != 1 or len(groups) != 1:
            raise ValueError('invalid structure')
        loc = locs[0]
        if not loc.attrib.get('station') or not loc.attrib.get('district'):
            raise ValueError('missing location')
        units = []
        seen = set()
        for node in groups[0]:
            if node.tag != 'unit' or any((not node.attrib.get(k) for k in ('id', 'type', 'arrival'))):
                raise ValueError('invalid unit')
            if node.attrib['id'] in seen:
                raise ValueError('duplicate unit')
            try:
                arrival = float(node.attrib['arrival'])
            except Exception as exc:
                raise ValueError('invalid arrival') from exc
            if arrival < 0 or arrival != arrival:
                raise ValueError('invalid arrival')
            seen.add(node.attrib['id'])
            units.append({'id': node.attrib['id'], 'type': node.attrib['type'], 'arrival': arrival})
        narrative = inc.find('narrative')
        text = ''.join(narrative.itertext()).strip() if narrative is not None else ''
        result.append({'id': attrs['id'], 'occurred': stamp, 'status': attrs['status'], 'station': loc.attrib['station'], 'district': loc.attrib['district'], 'units': units, 'narrative': text})
    result.sort(key=lambda x: (datetime.fromisoformat(x['occurred'][:-1] + '+00:00'), x['id']))
    return result

def parse_incident_feed(xml_text: str) -> list[dict]:
    return _read(xml_text)

def summarize_incidents(xml_text: str) -> dict:
    incidents = _read(xml_text)
    statuses = {k: 0 for k in ('open', 'closed', 'cancelled')}
    districts = {}
    totals = {}
    counts = {}
    for incident in incidents:
        statuses[incident['status']] += 1
        districts[incident['district']] = districts.get(incident['district'], 0) + 1
        for unit in incident['units']:
            key = unit['type']
            totals[key] = totals.get(key, 0.0) + unit['arrival']
            counts[key] = counts.get(key, 0) + 1
    averages = {k: round(totals[k] / counts[k], 2) for k in totals}
    return {'total': len(incidents), 'by_status': statuses, 'by_district': districts, 'average_arrival': averages}

