    totals = {}
    counts = {}
    for incident in incidents:
        statuses[incident['status']] += 1
        districts[incident['district']] = districts.get(incident['district'], 0) + 1
        for unit in incident['units']:
            key = unit['type']
            totals[key] = totals.get(key, 0.0) + unit['arrival']
            counts[key] = counts.get(key, 0) + 1
    averages = {k: round(totals[k] / counts[k], 2) for k in totals}
    return {'total': len(incidents), 'by_status': statuses, 'by_district': districts, 'average_arrival': averages}

