from datetime import datetime, timedelta, timezone

def _time(value):
    try:
        result = datetime.fromisoformat(value)
        if result.tzinfo is None:
            raise ValueError
        return result.astimezone(timezone.utc)
    except Exception as exc:
        raise ValueError from exc

def _check_event(item):
    if not isinstance(item, dict) or set(item) != {'supplier', 'category', 'score', 'assessed_at', 'valid_days'}:
        raise ValueError
    if not isinstance(item['supplier'], str) or not item['supplier'] or (not isinstance(item['category'], str)) or (not item['category']):
        raise ValueError
    if isinstance(item['score'], bool) or not isinstance(item['score'], (int, float)) or (not 0 <= item['score'] <= 100):
        raise ValueError
    if isinstance(item['valid_days'], bool) or not isinstance(item['valid_days'], int) or item['valid_days'] <= 0:
        raise ValueError
    _time(item['assessed_at'])

def verify_feed(payload: bytes, signature: str, secret: bytes) -> list[dict]:
    try:
        expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
        if not isinstance(signature, str) or len(signature) != 64 or (not hmac.compare_digest(expected, signature)):
            raise ValueError
        data = json.loads(payload.decode('utf-8'))
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError from exc
    if not isinstance(data, list):
        raise ValueError
    for item in data:
        _check_event(item)
    return data

def _required(required):
    if not isinstance(required, tuple) or not required or any((not isinstance(x, str) or not x for x in required)) or (len(set(required)) != len(required)):
        raise ValueError

