    _required(required)
    current = _time(now)
    result = []
    for supplier, categories in state.items():
        records = [categories.get(name) for name in required]
        qualified = all((record is not None and current < _time(record['expires_at']) for record in records))
        average = round(sum((record['score'] for record in records)) / len(records), 2) if qualified else None
        result.append({'supplier': supplier, 'qualified': qualified, 'average': average})
    result.sort(key=lambda x: (not x['qualified'], -(x['average'] or 0) if x['qualified'] else 0, x['supplier']))
    return result

