    _required(required)
    _time(now)
    events = verify_feed(payload, signature, secret)
    state = copy.deepcopy(prior)
    for item in events:
        supplier = item['supplier']
        category = item['category']
        state.setdefault(supplier, {})
        old = state[supplier].get(category)
        instant = _time(item['assessed_at'])
        if old is None or instant > _time(old['assessed_at']):
            expiry = instant + timedelta(days=item['valid_days'])
            state[supplier][category] = {'score': item['score'], 'assessed_at': item['assessed_at'], 'expires_at': expiry.isoformat()}
    return (state, rank_suppliers(state, required, now))

