import tempfile
import os
import pytest

def write_file(content):
    f = tempfile.NamedTemporaryFile(mode='w', delete=False, encoding='utf-8')
    try:
        f.write(content)
        return f.name
    finally:
        f.close()

def test_read_orders_events_and_parses_minutes():
    path = write_file('2025-06-03|09:10|Rome|Museum|45\n2025-06-01|18:00|Paris|Dinner|90\n2025-06-01|08:30|Paris|Walk|30\n2025-06-01|08:30|Berlin|Breakfast|20\n')
    try:
        assert read_itinerary(path) == [{'date': '2025-06-01', 'time': '08:30', 'city': 'Berlin', 'activity': 'Breakfast', 'minutes': 20}, {'date': '2025-06-01', 'time': '08:30', 'city': 'Paris', 'activity': 'Walk', 'minutes': 30}, {'date': '2025-06-01', 'time': '18:00', 'city': 'Paris', 'activity': 'Dinner', 'minutes': 90}, {'date': '2025-06-03', 'time': '09:10', 'city': 'Rome', 'activity': 'Museum', 'minutes': 45}]
    finally:
        os.unlink(path)

def test_comments_blanks_and_escaped_fields():
    path = write_file('  # trip notes\n\n2025-07-02|10:00|New\\|York|Art\\\\History|0\n')
    try:
        assert read_itinerary(path) == [{'date': '2025-07-02', 'time': '10:00', 'city': 'New|York', 'activity': 'Art\\History', 'minutes': 0}]
    finally:
        os.unlink(path)

def test_equal_sort_keys_keep_file_order():
    path = write_file('2025-01-01|12:00|Oslo|Zoo|5\n2025-01-01|12:00|Oslo|Zoo|7\n')
    try:
        assert [x['minutes'] for x in read_itinerary(path)] == [5, 7]
    finally:
        os.unlink(path)

def test_invalid_lines_raise_value_error():
    cases = ['2025-01-01|10:00|A|B\n', '2025-02-30|10:00|A|B|5\n', '2025-01-01|24:00|A|B|5\n', '2025-01-01|10:00|A|B|-1\n', '2025-01-01|10:00|A|B|1.5\n', '2025-01-01|10:00|A\\q|B|1\n']
    for content in cases:
        path = write_file(content)
        try:
