    events = [{'date': '2025-12-01', 'time': '09:00', 'city': 'A', 'activity': 'x', 'minutes': 20}, {'date': '2025-01-02', 'time': '09:00', 'city': 'B', 'activity': 'y', 'minutes': 5}, {'date': '2025-12-01', 'time': '10:00', 'city': 'A', 'activity': 'z', 'minutes': 40}]
