import subprocess
from datetime import date, time

def _fields(line):
    result = []
    current = []
    escaped = False
    for char in line.rstrip('\n\r'):
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            result.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid escape')
    result.append(''.join(current))
    return result

def read_itinerary(path: str) -> list[dict[str, object]]:
    result = subprocess.run(['sort', path], check=True, capture_output=True, text=True).stdout.splitlines()
    events = []
    for index, line in enumerate(result):
        if not line.strip() or line.lstrip().startswith('#'):
            continue
        fields = _fields(line)
        if len(fields) != 5:
            raise ValueError('invalid event')
        try:
            date.fromisoformat(fields[0])
            time.fromisoformat(fields[1])
            minutes = int(fields[4])
        except (ValueError, TypeError):
            raise ValueError('invalid event')
        if not fields[4].isdigit() or minutes < 0:
            raise ValueError('invalid event')
        events.append({'date': fields[0], 'time': fields[1], 'city': fields[2], 'activity': fields[3], 'minutes': minutes, '_index': index})
    events.sort(key=lambda x: (x['date'], x['time'], x['city'], x['activity'], x['_index']))
    for event in events:
        del event['_index']
    return events

def daily_minutes(events: list[dict[str, object]]) -> dict[str, int]:
    totals = {}
    for event in events:
        if any((key not in event for key in ('date', 'time', 'city', 'activity', 'minutes'))):
            raise ValueError('invalid event')
        if not isinstance(event['date'], str) or isinstance(event['minutes'], bool) or (not isinstance(event['minutes'], int)) or (event['minutes'] < 0):
            raise ValueError('invalid event')
        totals[event['date']] = totals.get(event['date'], 0) + event['minutes']
    return dict(sorted(totals.items()))

