        parts = _fields(line)
        if len(parts) != 5:
            raise ValueError('line %d has the wrong number of fields' % number)
        ident, start, duration, stage, teams = parts
        ident, stage = (ident.strip(), stage.strip())
        names = [x.strip() for x in teams.split(',')]
        if not ident or not stage or any((not x for x in names)) or (len(names) < 2) or (len(set(names)) != len(names)):
