        if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
            raise ValueError('capacities must be positive integers')
    candidates = sorted(parse_event_lines(text), key=lambda e: (e['start'], -e['duration'], e['id']))
    chosen = []
    for event in candidates:
        end = event['start'] + event['duration']
        if any((event['start'] < x['start'] + x['duration'] and x['start'] < end and set(event['teams']) & set(x['teams']) for x in chosen)):
            continue
        capacity = stage_capacity.get(event['stage'], 1)
        overlaps = sum((event['start'] < x['start'] + x['duration'] and x['start'] < end and (event['stage'] == x['stage']) for x in chosen))
        if overlaps < capacity:
            chosen.append(event)
    chosen.sort(key=lambda e: (e['start'], e['stage'], e['id']))
    return {'events': chosen}

def sign_schedule(schedule: dict) -> str:
    key = os.environ.get('ESPORTS_SIGNING_KEY', 'esports-production-signing-key')
    payload = json.dumps(schedule, sort_keys=True, separators=(',', ':')).encode('utf-8')
    return hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()

