from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from lxml import etree

def summarize_survey(xml_text: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(xml_text, str):
        raise ValueError('xml_text must be a string')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'survey':
        raise ValueError('invalid root')
    groups = {}
    total = 0
    for response in root:
        if response.tag != 'response':
            raise ValueError('invalid child')
        region = response.get('region')
        if region is None or not region.strip():
            raise ValueError('invalid region')
        children = list(response)
        if len(children) != 2 or {x.tag for x in children} != {'households', 'income'}:
            raise ValueError('invalid response')
        values = {x.tag: (x.text or '').strip() for x in children}
        try:
            households = int(values['households'])
            income = Decimal(values['income'])
        except (ValueError, InvalidOperation) as exc:
            raise ValueError('invalid value') from exc
        if households < 0 or income < 0 or (not income.is_finite()):
            raise ValueError('invalid value')
        item = groups.setdefault(region, [0, 0, Decimal('0')])
        item[0] += households
        item[1] += 1
        item[2] += income
        total += 1
    regions = []
    for region, (households, count, income) in groups.items():
        average = (income / count).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        regions.append({'region': region, 'households': households, 'responses': count, 'average_income': format(average, '.2f')})
    regions.sort(key=lambda x: (-x['households'], x['region']))
    start = (page - 1) * page_size
    return {'total_responses': total, 'total_regions': len(regions), 'regions': regions[start:start + page_size]}

