from datetime import date, timedelta

def _unescape(value):
    out = []
    i = 0
    while i < len(value):
        if value[i] == '\\\\':
            i += 1
            if i == len(value):
                raise ValueError('bad escape')
            if value[i] not in '|\\\\':
                raise ValueError('bad escape')
        out.append(value[i])
        i += 1
    return ''.join(out)

def parse_leave_records(text: str) -> list[dict]:
    result = []
    seen = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        fields, cur, escaped = ([], [], False)
        for ch in line:
            if escaped:
                cur.extend(['\\\\', ch])
                escaped = False
            elif ch == '\\\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(cur))
                cur = []
            else:
                cur.append(ch)
        if escaped:
            raise ValueError('bad escape')
        fields.append(''.join(cur))
        if len(fields) != 7:
            raise ValueError('bad row')
        vals = [x.strip() for x in fields[:6]]
        note = _unescape(fields[6]).strip()
        rid, eid, a, b, kind, status = vals
        if not rid or not eid or rid in seen or (kind not in {'vacation', 'sick', 'personal', 'unpaid'}) or (status not in {'pending', 'approved', 'rejected'}):
            raise ValueError('invalid record')
        try:
            start = date.fromisoformat(a)
            end = date.fromisoformat(b)
        except ValueError:
            raise ValueError('invalid date')
        if end < start:
            raise ValueError('invalid range')
        seen.add(rid)
        result.append({'request_id': rid, 'employee_id': eid, 'start': start, 'end': end, 'kind': kind, 'status': status, 'note': note})
    return result

def build_leave_report(requester: dict, records: list[dict], month: str) -> list[dict]:
    try:
        first = date.fromisoformat(month + '-01')
        if len(month) != 7:
            raise ValueError
    except ValueError:
        raise ValueError('invalid month')
    last = date(first.year + (first.month == 12), first.month % 12 + 1, 1) - timedelta(days=1)
    groups = {}
    for r in records:
        if r['tenant_id'] != requester['tenant_id'] or r['status'] != 'approved':
            continue
        lo, hi = (max(first, r['start']), min(last, r['end']))
        if lo > hi:
            continue
        days = (hi - lo).days + 1
        g = groups.setdefault(r['employee_id'], {'days': 0, 'kinds': {}, 'items': []})
        g['days'] += days
        g['kinds'][r['kind']] = g['kinds'].get(r['kind'], 0) + days
        g['items'].append((r['start'], r['request_id']))
    out = [{'employee_id': eid, 'days': g['days'], 'kinds': g['kinds'], 'request_ids': [x[1] for x in sorted(g['items'])]} for eid, g in groups.items()]
    return sorted(out, key=lambda x: (-x['days'], x['employee_id']))

def approve_leave(requester: dict, records: list[dict], request_id: str, decision: str, note: str='') -> dict:
    if decision not in {'approve', 'reject'}:
        raise ValueError('invalid decision')
    record = next((r for r in records if r['request_id'] == request_id), None)
    if record is None:
        raise KeyError(request_id)
    if record['status'] != 'pending':
        raise ValueError('not pending')
    if record['tenant_id'] != requester['tenant_id'] or (record['employee_id'] != requester['id'] and requester['role'] not in {'manager', 'hr_admin'}):
        raise PermissionError('forbidden')
    clean = note.strip()
    if len(clean) > 200:
        raise ValueError('note too long')
    record['status'] = 'approved' if decision == 'approve' else 'rejected'
    record['note'] = clean
    return record

