import math
import os

def build_baggage_manifest(records: list[dict], page: int, page_size: int) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive')
    token = os.environ.get('BAGGAGE_API_TOKEN')
    if not token:
        raise ValueError('BAGGAGE_API_TOKEN is required')
    statuses = ('checked', 'in_transit', 'delivered', 'missing')
    checked = []
    counts = {status: 0 for status in statuses}
    total_weight = 0.0
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        if not isinstance(record.get('bag_id'), str) or not record['bag_id']:
            raise ValueError('bag_id must be a non-empty string')
        if not isinstance(record.get('flight'), str) or not record['flight']:
            raise ValueError('flight must be a non-empty string')
        if record.get('status') not in statuses:
            raise ValueError('invalid status')
        weight = record.get('weight_kg')
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight < 0:
            raise ValueError('weight_kg must be non-negative')
        checked.append(dict(record))
        counts[record['status']] += 1
        total_weight += weight
    checked.sort(key=lambda item: (item['flight'], item['bag_id']))
    total = len(checked)
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total': total, 'total_pages': math.ceil(total / page_size) if total else 0, 'items': checked[start:start + page_size], 'summary': {'total_weight_kg': round(total_weight, 2), 'by_status': counts}, 'headers': {'Authorization': 'Bearer ' + token}}

