from lxml import etree

def summarize_work_orders(xml_text: str, status: str | None=None, page: int=1, page_size: int=20) -> dict:
    if not isinstance(xml_text, str) or type(page) is not int or type(page_size) is not int or (page < 1) or (page_size < 1):
        raise ValueError('invalid arguments')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
        if root.tag != 'work_orders':
            raise ValueError('invalid root')
        records = []
        for node in root:
            if node.tag != 'work_order':
                raise ValueError('invalid child')
            a = node.attrib
            if any((k not in a for k in ('id', 'status', 'priority', 'due_date', 'estimated_hours'))):
                raise ValueError('missing attribute')
            priority = int(a['priority'])
            due = date.fromisoformat(a['due_date'])
            hours = Decimal(a['estimated_hours'])
            if hours < 0:
                raise ValueError('negative hours')
            record = {'id': a['id'], 'status': a['status'], 'priority': priority, 'due_date': a['due_date'], 'estimated_hours': float(hours)}
            if status is None or a['status'] == status:
                records.append((record, hours, due))
    except (etree.XMLSyntaxError, ValueError, KeyError, InvalidOperation):
        raise ValueError('invalid XML')
    records.sort(key=lambda x: (-x[0]['priority'], x[2], x[0]['id']))
    total = sum((x[1] for x in records), Decimal('0'))
    rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    start = (page - 1) * page_size
    return {'total': len(records), 'page': page, 'page_size': page_size, 'total_estimated_hours': float(rounded), 'work_orders': [x[0] for x in records[start:start + page_size]]}

