def rank_samples(samples: list[dict], filter_expression: str, score_expression: str, offset: int=0, limit: int | None=None) -> list[dict]:
    if offset < 0 or (limit is not None and limit < 0):
        raise ValueError('invalid pagination')
    allowed_names = {'reads', 'mapped', 'quality'}
    functions = {'min': min, 'max': max, 'round': round}

    def evaluate(text, env):
        try:
            tree = ast.parse(text, mode='eval').body
        except (SyntaxError, ValueError) as exc:
            raise ValueError('invalid expression') from exc

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in allowed_names:
                    raise ValueError('unknown name')
                return env[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                if isinstance(node.op, ast.UAdd):
                    return +value
                if isinstance(node.op, ast.USub):
                    return -value
                return not value
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                left, right = (visit(node.left), visit(node.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                value = visit(node.values[0])
                for part in node.values[1:]:
                    if isinstance(node.op, ast.And):
                        if not value:
                            return value
                    elif value:
                        return value
                    value = visit(part)
                return value
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                checks = []
                for op, right_node in zip(node.ops, node.comparators):
                    right = visit(right_node)
                    fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                    if fn is None:
                        raise ValueError('unsupported comparison')
                    checks.append(fn(left, right))
                    left = right
                return all(checks)
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in functions) and (not node.keywords):
                return functions[node.func.id](*[visit(arg) for arg in node.args])
