import hashlib
import hmac
import os

def create_tracker_credential(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_tracker_credential(pin: str, stored: str) -> bool:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not isinstance(stored, str) or '$' not in stored:
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_shipments(records: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or page <= 0 or (page_size <= 0):
        raise ValueError('page and page_size must be positive integers')
    groups = {}
    for record in records:
        destination = record.get('destination')
        status = record.get('status')
        weight = record.get('weight_kg')
        if not isinstance(destination, str) or not destination:
            raise ValueError('invalid destination')
        if status not in {'delivered', 'in_transit', 'delayed'}:
            raise ValueError('invalid status')
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight < 0:
            raise ValueError('invalid weight')
        item = groups.setdefault(destination, [0, 0.0, 0])
        item[0] += 1
        item[1] += weight
        if status == 'delayed':
            item[2] += 1
    result = [{'destination': name, 'shipment_count': values[0], 'total_weight_kg': round(values[1], 2), 'delayed_count': values[2]} for name, values in groups.items()]
    result.sort(key=lambda item: (-item['shipment_count'], item['destination']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

