        status = record.get('status')
        weight = record.get('weight_kg')
        if not isinstance(destination, str) or not destination:
            raise ValueError('invalid destination')
        if status not in {'delivered', 'in_transit', 'delayed'}:
            raise ValueError('invalid status')
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight < 0:
            raise ValueError('invalid weight')
        item = groups.setdefault(destination, [0, 0.0, 0])
        item[0] += 1
        item[1] += weight
        if status == 'delayed':
            item[2] += 1
    result = [{'destination': name, 'shipment_count': values[0], 'total_weight_kg': round(values[1], 2), 'delayed_count': values[2]} for name, values in groups.items()]
    result.sort(key=lambda item: (-item['shipment_count'], item['destination']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

