def parse_festival_update(payload: str) -> list[dict]:
    try:
        obj = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(obj, dict) or set(obj) != {'day', 'sets'}:
        raise ValueError('invalid update')
    day = obj['day']
    if day not in ('Thu', 'Fri', 'Sat') or not isinstance(obj['sets'], list):
        raise ValueError('invalid update')
    result = []
    artists = set()
    pattern = re.compile('^(?:[01][0-9]|2[0-3]):[0-5][0-9]$')
    for item in obj['sets']:
        if not isinstance(item, dict) or set(item) != {'artist', 'stage', 'start', 'end', 'tags'}:
            raise ValueError('invalid set')
        artist, stage, start, end, tags = (item[k] for k in ('artist', 'stage', 'start', 'end', 'tags'))
        if not all((isinstance(x, str) and x for x in (artist, stage, start, end))) or not isinstance(tags, list) or (not all((isinstance(x, str) for x in tags))):
            raise ValueError('invalid set')
        if not pattern.fullmatch(start) or not pattern.fullmatch(end):
            raise ValueError('invalid time')
        sm = int(start[:2]) * 60 + int(start[3:])
        em = int(end[:2]) * 60 + int(end[3:])
        if em <= sm or artist.casefold() in artists:
            raise ValueError('invalid set')
        artists.add(artist.casefold())
        result.append({'day': day, 'artist': artist, 'stage': stage, 'start': start, 'end': end, 'duration_minutes': em - sm, 'tags': sorted(tags, key=str.casefold)})
    ranks = {'Main': 0, 'Harbor': 1, 'Club': 2}
    result.sort(key=lambda x: (('Thu', 'Fri', 'Sat').index(x['day']), int(x['start'][:2]) * 60 + int(x['start'][3:]), ranks.get(x['stage'], 3), x['stage'] if x['stage'] not in ranks else '', x['artist'].casefold()))
    return result

def verify_and_build_schedule(payload: str, signature: str, shared_key: str) -> list[dict]:
    if not isinstance(shared_key, str) or not isinstance(signature, str):
        raise ValueError('invalid signature')
    expected = hmac.new(shared_key.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    return parse_festival_update(payload)

