from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def write_compliance_report(records: list[dict], base_dir: str, relative_name: str) -> str:
    if not isinstance(relative_name, str) or not relative_name or os.path.isabs(relative_name):
        raise ValueError('invalid file name')
    if not isinstance(base_dir, str):
        raise ValueError('invalid base directory')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            chemical = record['chemical']
            quantity = record['quantity']
            limit = record['permitted_limit']
            if not isinstance(chemical, str) or not chemical:
                raise ValueError
            if isinstance(quantity, bool) or isinstance(limit, bool):
                raise ValueError
            if not isinstance(quantity, (int, float)) or not isinstance(limit, (int, float)):
                raise ValueError
            if not math.isfinite(quantity) or not math.isfinite(limit) or quantity < 0 or (limit < 0):
                raise ValueError
            quantity = Decimal(str(quantity))
            limit = Decimal(str(limit))
        except (KeyError, TypeError, InvalidOperation):
            raise ValueError('invalid record')
        if chemical in groups and groups[chemical][1] != limit:
            raise ValueError('inconsistent limit')
        if chemical in groups:
            groups[chemical] = (groups[chemical][0] + quantity, limit)
        else:
            groups[chemical] = (quantity, limit)
    if not groups:
        raise ValueError('empty records')
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, target]) != base:
        raise ValueError('path outside base directory')
    rows = []
    for chemical, (total, limit) in groups.items():
        exceedance = max(total - limit, Decimal('0'))
        status = 'EXCEEDS' if total > limit else 'COMPLIANT'
        quantize = lambda value: str(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        rows.append([chemical, quantize(total), quantize(limit), quantize(exceedance), status])
    rows.sort(key=lambda row: (0 if row[4] == 'EXCEEDS' else 1, row[0].casefold(), row[0]))
    os.makedirs(os.path.dirname(target) or base, exist_ok=True)
    with open(target, 'w', encoding='utf-8', newline='') as handle:
        writer = csv.writer(handle)
        writer.writerow(['chemical', 'total_quantity', 'permitted_limit', 'exceedance', 'status'])
        writer.writerows(rows)
    return target

