import operator

def _evaluate(source, names):
    try:
        tree = ast.parse(source, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and type(node.value) in (int, float):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in names:
                    raise ValueError()
                return names[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                a, b = (visit(node.left), visit(node.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                values = [visit(x) for x in node.values]
                result = values[0]
                for value in values[1:]:
                    if isinstance(node.op, ast.And):
                        result = value if result else result
                    else:
                        result = result if result else value
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, part in zip(node.ops, node.comparators):
                    right = visit(part)
                    fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                    if fn is None or not fn(left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*[visit(x) for x in node.args])
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        raise ValueError() from exc

