import re
import subprocess
_heading = re.compile('^Clause ([0-9]+(?:\\.[0-9]+)*)\\s*-\\s*(\\S.*)\\s*$')
_word = re.compile("[A-Za-z0-9]+(?:['-][A-Za-z0-9]+)*")

def parse_clauses(text: str) -> list[dict]:
    lines = text.splitlines()
    found = []
    seen = set()
    current = None
    for number, line in enumerate(lines, 1):
        match = _heading.match(line)
        if match:
            if current is not None:
                current['end_line'] = number - 1
                found.append(current)
            ident, title = match.groups()
            if ident in seen:
                raise ValueError('duplicate clause id')
            seen.add(ident)
            current = {'id': ident, 'title': title.strip(), 'body': [], 'start_line': number}
        elif current is not None:
            current['body'].append(line)
    if current is not None:
        current['end_line'] = len(lines)
        found.append(current)
    for clause in found:
        clause['body'] = ' '.join((x.strip() for x in clause['body'] if x.strip()))
    return found

def select_clauses(path: str, pattern: str, limit: int | None=None) -> list[dict]:
    if limit is not None and limit < 0:
        raise ValueError('negative limit')
    result = subprocess.run(['grep', '-n', '-E', pattern, path], capture_output=True, text=True)
    if result.returncode not in (0, 1):
        raise ValueError(result.stderr.strip() or 'grep failed')
    matched = {int(line.split(':', 1)[0]) for line in result.stdout.splitlines() if ':' in line}
    clauses = parse_clauses(open(path, encoding='utf-8').read())
    selected = [c for c in clauses if any((c['start_line'] <= n <= c['end_line'] for n in matched))]
    return selected if limit is None else selected[:limit]

def contract_summary(text: str) -> dict:
    clauses = parse_clauses(text)
    counts = [_word.findall(c['body']) for c in clauses]
    longest = None
    if counts:
        longest = clauses[max(range(len(clauses)), key=lambda i: len(counts[i]))]['id']
    return {'clause_count': len(clauses), 'total_body_words': sum(map(len, counts)), 'longest_clause_id': longest, 'clause_ids': [c['id'] for c in clauses]}

