import os
from decimal import Decimal, ROUND_HALF_UP

def create_keeper(username: str, password: str) -> dict:
    if not isinstance(username, str) or not username:
        raise ValueError('invalid username')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username, 'salt': salt.hex(), 'password_hash': digest.hex()}

def authenticate_keeper(account: dict, password: str) -> bool:
    try:
        salt = bytes.fromhex(account['salt'])
        expected = account['password_hash']
        if not isinstance(password, str):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

