    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    valid = {'healthy', 'watch', 'critical'}
    checked = []
    for record in records:
        try:
            animal_id = record['animal_id']
            species = record['species']
            temperature = record['temperature']
            status = record['status']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(animal_id, str) or not isinstance(species, str) or (not species) or (not isinstance(temperature, (int, float))) or isinstance(temperature, bool) or (status not in valid):
            raise ValueError('invalid record')
        checked.append(dict(record))
    ordered = sorted(checked, key=lambda r: (-r['temperature'], r['animal_id']))
    groups = {}
    for record in checked:
        groups.setdefault(record['species'], []).append(record)
    summaries = []
    for species in sorted(groups):
        group = groups[species]
        average = sum((Decimal(str(r['temperature'])) for r in group)) / Decimal(len(group))
        average = float(average.quantize(Decimal('0.1'), rounding=ROUND_HALF_UP))
        summaries.append({'species': species, 'count': len(group), 'average_temperature': average, 'critical': sum((r['status'] == 'critical' for r in group))})
    start = (page - 1) * page_size
    return {'total': len(checked), 'records': ordered[start:start + page_size], 'by_species': summaries}

