def _check(requester, patient):
    if requester.get('tenant_id') != patient.get('tenant_id'):
        raise PermissionError('not permitted')
    if requester.get('id') != patient.get('owner_id') and 'clinician' not in requester.get('roles', []):
        raise PermissionError('not permitted')

def _validate(v):
    if not isinstance(v, dict) or not isinstance(v.get('date'), str):
        raise ValueError('invalid visit')
    try:
        date.fromisoformat(v['date'])
    except (ValueError, TypeError):
        raise ValueError('invalid date')
    labs = v.get('labs', [])
    if not isinstance(labs, list):
        raise ValueError('invalid labs')
    for lab in labs:
        if not isinstance(lab, dict) or not all((k in lab for k in ('name', 'value', 'unit'))):
            raise ValueError('invalid lab')
        if not isinstance(lab['value'], (int, float)) or isinstance(lab['value'], bool):
            raise ValueError('invalid lab value')

def summarize_patient(requester: dict, patient: dict, visits: list[dict]) -> dict:
    _check(requester, patient)
    selected = [v for v in visits if v.get('patient_id') == patient.get('id')]
    for v in selected:
        _validate(v)
    ordered = sorted(selected, key=lambda v: v['date'])
    counts = {}
    totals = {}
    for v in selected:
        counts[v['kind']] = counts.get(v['kind'], 0) + 1
        for lab in v.get('labs', []):
            key = (lab['name'], lab['unit'])
