import json
import math
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _money(value):
    return int(Decimal(value).quantize(Decimal('1'), rounding=ROUND_HALF_UP))

def calculate_checkout(items: list[dict], tax_rates: dict[str, float], coupon: str | None=None) -> dict:
    if coupon not in (None, 'SAVE10', 'SAVE20'):
        raise ValueError('invalid coupon')
    rows = []
    for item in items:
        required = ('sku', 'name', 'category', 'quantity', 'unit_price_cents')
        if any((key not in item for key in required)):
            raise ValueError('invalid item')
        if not all((isinstance(item[key], str) and item[key] for key in ('sku', 'name', 'category'))):
            raise ValueError('invalid item')
        quantity = item['quantity']
        price = item['unit_price_cents']
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        if isinstance(price, bool) or not isinstance(price, int) or price < 0:
            raise ValueError('invalid price')
        category = item['category']
        if category not in tax_rates:
            raise ValueError('missing tax rate')
        rate = tax_rates[category]
        if isinstance(rate, bool) or not isinstance(rate, (int, float)) or (not math.isfinite(rate)) or (rate < 0) or (rate > 100):
            raise ValueError('invalid tax rate')
        subtotal = quantity * price
        tax = _money(Decimal(subtotal) * Decimal(str(rate)) / Decimal(100))
        rows.append({'sku': item['sku'], 'name': item['name'], 'category': category, 'quantity': quantity, 'unit_price_cents': price, 'subtotal_cents': subtotal, 'tax_cents': tax})
    rows.sort(key=lambda row: (row['category'], row['sku'], row['name']))
    subtotal = sum((row['subtotal_cents'] for row in rows))
    discount = _money(Decimal(subtotal) * Decimal({None: 0, 'SAVE10': 10, 'SAVE20': 20}[coupon]) / Decimal(100))
    tax = sum((row['tax_cents'] for row in rows))
    return {'lines': rows, 'subtotal_cents': subtotal, 'discount_cents': discount, 'tax_cents': tax, 'total_cents': subtotal - discount + tax}

def export_checkout(items: list[dict], tax_rates: dict[str, float], destination: str, coupon: str | None=None) -> dict:
    result = calculate_checkout(items, tax_rates, coupon)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as handle:
            json.dump(result, handle, ensure_ascii=False, separators=(',', ':'))
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return result

def read_checkout_export(path: str) -> dict:
    with open(path, encoding='utf-8') as handle:
        value = json.load(handle)
    keys = {'lines', 'subtotal_cents', 'discount_cents', 'tax_cents', 'total_cents'}
    if not isinstance(value, dict) or set(value) != keys or (not isinstance(value['lines'], list)):
        raise ValueError('invalid export')
    if any((isinstance(value[key], bool) or not isinstance(value[key], int) for key in keys - {'lines'})):
        raise ValueError('invalid export')
    return value

