    if not isinstance(length, int) or isinstance(length, bool) or (not 6 <= length <= 32):
        raise ValueError('invalid length')
    chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    prefix_chars = ''.join((ch for ch in vendor_name.strip() if ch.isalnum()))[:4].upper()
    prefix = (prefix_chars + 'VENDOR')[:4]
    for _ in range(100):
        suffix = ''.join((secrets.choice(chars) for _ in range(length)))
        code = prefix + '-' + suffix
        if code not in issued_codes:
            return code
    raise RuntimeError('could not create unique code')

def summarize_badges(records: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        vendor = record['vendor'].strip()
        if not vendor:
            raise ValueError('invalid vendor')
        status = record['status']
        if status not in {'active', 'revoked'}:
            raise ValueError('invalid status')
        issued_at = record['issued_at']
        parsed = datetime.fromisoformat(issued_at)
        if vendor not in groups:
            groups[vendor] = {'total': 0, 'active': 0, 'revoked': 0, 'badge_types': {}, 'latest': (parsed, issued_at)}
        group = groups[vendor]
        group['total'] += 1
        group[status] += 1
        badge_type = record['badge_type']
        group['badge_types'][badge_type] = group['badge_types'].get(badge_type, 0) + 1
        if parsed > group['latest'][0]:
            group['latest'] = (parsed, issued_at)
    ordered = sorted(groups.items(), key=lambda item: (-item[1]['total'], item[0]))
    start = (page - 1) * page_size
    vendors = []
