import secrets

def generate_access_code(length: int=10) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or length < 6 or (length > 32):
        raise ValueError('length must be between 6 and 32')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def summarize_death_certificate_requests(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be positive')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('page_size must be positive')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        county = record.get('county')
        status = record.get('status')
        fee = record.get('fee')
        if not isinstance(county, str) or not county:
            raise ValueError('invalid county')
        if status not in {'pending', 'approved', 'rejected'}:
            raise ValueError('invalid status')
        if isinstance(fee, bool) or not isinstance(fee, (int, float)) or fee < 0:
            raise ValueError('invalid fee')
        item = grouped.setdefault(county, [0, 0, 0.0])
        item[0] += 1
        item[1] += status == 'approved'
        item[2] += fee
    rows = [{'county': county, 'requests': data[0], 'approved': data[1], 'fees': round(data[2], 2)} for county, data in grouped.items()]
    rows.sort(key=lambda row: (-row['requests'], row['county']))
    total = len(rows)
    start = (page - 1) * page_size
    return {'items': rows[start:start + page_size], 'total_counties': total, 'total_pages': (total + page_size - 1) // page_size if total else 0, 'page': page, 'page_size': page_size}

