def build_recall_report(records: list[dict[str, object]], manufacturer: str | None=None, page: int=1, page_size: int=50) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if manufacturer is not None and (not isinstance(manufacturer, str) or not manufacturer):
        raise ValueError('invalid manufacturer')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    fields = {'batch_id', 'drug', 'manufacturer', 'units', 'recall_date', 'reason'}
    groups = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != fields:
            raise ValueError('invalid record')
        for key in ('batch_id', 'drug', 'manufacturer', 'reason'):
            if not isinstance(record[key], str) or not record[key]:
                raise ValueError('invalid field')
        units = record['units']
        if isinstance(units, bool) or not isinstance(units, int) or units <= 0:
            raise ValueError('invalid units')
        date_text = record['recall_date']
        if not isinstance(date_text, str) or len(date_text) != 10 or date_text[4] != '-' or (date_text[7] != '-'):
            raise ValueError('invalid date')
        try:
            datetime.date.fromisoformat(date_text)
        except ValueError:
            raise ValueError('invalid date')
        if manufacturer is not None and record['manufacturer'] != manufacturer:
            continue
        key = (record['manufacturer'], record['drug'])
        if key not in groups:
            groups[key] = [0, 0, date_text, set()]
        item = groups[key]
        item[0] += 1
        item[1] += units
        item[2] = max(item[2], date_text)
        item[3].add(record['reason'])
    ordered = sorted(groups.items(), key=lambda pair: (-pair[1][1], pair[0][0], pair[0][1]))
    start = (page - 1) * page_size
    selected = ordered[start:start + page_size]
    rows = [['manufacturer', 'drug', 'batch_count', 'total_units', 'latest_recall_date', 'reasons']]
    for (maker, drug), item in selected:
        rows.append([maker, drug, item[0], item[1], item[2], '; '.join(sorted(item[3]))])
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerows(rows)
        with open(path, newline='') as handle:
            return handle.read()
    finally:
        os.unlink(path)

