def occupancy_report(conn: sqlite3.Connection, search: str='', species: str | None=None, sort_by: str='occupancy', limit: int=100, offset: int=0) -> list[dict[str, object]]:
    if not isinstance(search, str) or not isinstance(species, (str, type(None))):
