    conditions = ['lower(name) LIKE lower(?)']
    params: list[object] = [f'%{search}%']
    if species is not None:
        conditions.append('species = ?')
        params.append(species)
    query = f"\n        SELECT species,\n               COUNT(*) AS total,\n               SUM(CASE WHEN status = 'occupied' THEN 1 ELSE 0 END) AS occupied,\n               AVG(age) AS average_age\n        FROM animals\n        WHERE {' AND '.join(conditions)}\n        GROUP BY species\n        ORDER BY {orderings[sort_by]}\n        LIMIT ? OFFSET ?\n    "
    params.extend([limit, offset])
    rows = conn.execute(query, params).fetchall()
    return [{'species': row[0], 'total': row[1], 'occupied': row[2], 'average_age': round(row[3], 2)} for row in rows]

