from datetime import datetime, timezone
import math

def parse_observation(text: str) -> dict:
    if not isinstance(text, str):
        raise ValueError('observation must be text')
    fields = []
    cur = []
    escaped = False
    for ch in text:
        if escaped:
            cur.append('\\' if ch != '|' else '|')
            if ch != '|':
                cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            fields.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        cur.append('\\')
    fields.append(''.join(cur))
    if len(fields) != 4 or not fields[0]:
        raise ValueError('malformed observation')
    try:
        if not fields[1].endswith('Z'):
            raise ValueError
        stamp = datetime.fromisoformat(fields[1][:-1] + '+00:00').astimezone(timezone.utc)
        value = float(fields[2])
    except Exception as exc:
        raise ValueError('malformed observation') from exc
    if not math.isfinite(value) or fields[3] not in {'good', 'suspect', 'rejected'}:
        raise ValueError('malformed observation')
    return {'station': fields[0], 'timestamp': stamp, 'value': value, 'quality': fields[3]}

def summarize_survey(requester: dict, surveys: list[dict], survey_id: str, window_hours: int) -> dict:
    if not isinstance(window_hours, int) or isinstance(window_hours, bool) or window_hours <= 0:
        raise ValueError('window_hours must be positive')
    survey = next((x for x in surveys if x.get('id') == survey_id), None)
    if survey is None:
        raise KeyError(survey_id)
    if not (requester.get('tenant_id') == survey.get('tenant_id') and (requester.get('id') == survey.get('owner_id') or 'survey_admin' in requester.get('roles', []))):
        raise PermissionError('not authorized')
    if not isinstance(survey.get('observations'), list):
        raise ValueError('observations must be a list')
    groups = {}
    width = window_hours * 3600
    for raw in survey['observations']:
        obs = parse_observation(raw)
        if obs['quality'] != 'good':
            continue
        sec = int(obs['timestamp'].timestamp())
        start = datetime.fromtimestamp(sec // width * width, timezone.utc)
        key = (obs['station'], start)
        groups.setdefault(key, []).append(obs['value'])
    stations = {}
    for (name, start), values in groups.items():
        stations.setdefault(name, []).append({'start': start.strftime('%Y-%m-%dT%H:%M:%SZ'), 'count': len(values), 'minimum': round(min(values), 6), 'maximum': round(max(values), 6), 'mean': round(sum(values) / len(values), 6), '_dt': start})
    result = []
    for name in sorted(stations):
        windows = sorted(stations[name], key=lambda x: x['_dt'])
        for w in windows:
            del w['_dt']
        result.append({'station': name, 'windows': windows})
    return {'survey_id': survey_id, 'station_count': len(result), 'stations': result}

