import hashlib
import hmac
import json
import os
from decimal import Decimal, ROUND_HALF_UP

def build_poster_submission_report(records: list[dict], offset: int=0, limit: int=50) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if offset < 0 or limit <= 0:
        raise ValueError('offset must be nonnegative and limit must be positive')
    groups = {}
    required = {'poster_id', 'author', 'score', 'status'}
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('each record must contain all required fields')
        score = record['score']
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 100):
            raise ValueError('score must be between 0 and 100')
        if record['status'] == 'accepted':
            groups.setdefault(record['author'], []).append(score)
    items = []
    for author, scores in groups.items():
        average = Decimal(str(sum(scores))) / Decimal(len(scores))
        average = float(average.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        items.append({'author': author, 'submissions': len(scores), 'average_score': average})
    items.sort(key=lambda item: (-item['average_score'], item['author']))
    total = len(items)
    page = items[offset:offset + limit]
    token = os.environ.get('POSTER_API_TOKEN')
    if not token:
        raise RuntimeError('POSTER_API_TOKEN is not set')
    body = json.dumps({'items': page, 'total': total}, sort_keys=True, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(token.encode('utf-8'), body, hashlib.sha256).hexdigest()
    return {'items': page, 'total': total, 'signature': signature}

