import csv
import datetime
import math
import os
import tempfile

def export_manifest(records: list[dict[str, object]], destination: str, min_weight: float=0.0) -> dict[str, object]:
    if isinstance(min_weight, bool) or not isinstance(min_weight, (int, float)) or (not math.isfinite(min_weight)) or (min_weight < 0):
        raise ValueError('invalid minimum weight')
    seen = set()
    selected = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            ident = record['manifest_id']
            route = record['route']
            date_text = record['pickup_date']
            weight = record['weight_kg']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        if not isinstance(ident, str) or not ident or (not isinstance(route, str)) or (not route) or (not isinstance(date_text, str)) or (not date_text):
            raise ValueError('invalid text field')
        try:
            datetime.datetime.strptime(date_text, '%Y-%m-%d')
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or (not math.isfinite(weight)) or (weight < 0):
            raise ValueError('invalid weight')
        if ident in seen:
            raise ValueError('duplicate manifest id')
        seen.add(ident)
        if weight >= min_weight:
            selected.append((ident, route, date_text, float(weight)))
    selected.sort(key=lambda row: (row[2], row[1], row[0]))
    totals = {}
    for _, route, _, weight in selected:
        totals[route] = totals.get(route, 0.0) + weight
    by_route = {route: round(totals[route], 2) for route in sorted(totals)}
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.manifest-', dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['manifest_id', 'route', 'pickup_date', 'weight_kg'])
            for ident, route, date_text, weight in selected:
                writer.writerow([ident, route, date_text, f'{weight:.2f}'])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'count': len(selected), 'total_weight_kg': round(sum((row[3] for row in selected)), 2), 'by_route': by_route}

