import calendar
import subprocess

def read_sales(path: str) -> list[dict]:
    try:
        result = subprocess.run(['sort', '-t', '\t', '-k6,6', '-k1,1', path], capture_output=True, text=True, check=True)
        lines = result.stdout.splitlines()
    except (OSError, UnicodeError, subprocess.SubprocessError) as exc:
        raise ValueError('unable to read sales file') from exc
    records = []
    for number, line in enumerate(lines, 1):
        if not line.strip():
            continue
        fields = line.split('\t')
        if len(fields) != 6:
            raise ValueError(f'invalid record at line {number}')
        item_id, seller, category, price, status, date = fields
        try:
            value = int(price)
            year, month, day = (int(x) for x in date.split('-'))
            if value < 0 or len(date) != 10 or (not 1 <= month <= 12) or (not 1 <= day <= calendar.monthrange(year, month)[1]):
                raise ValueError
        except (ValueError, TypeError):
            raise ValueError(f'invalid record at line {number}')
        if status not in {'sold', 'returned', 'pending'}:
            raise ValueError(f'invalid record at line {number}')
        records.append({'item_id': item_id, 'seller': seller, 'category': category, 'price_cents': value, 'status': status, 'sale_date': date})
    return records

def build_report(path: str, category: str | None=None) -> dict:
    sellers = {}
    months = {}
    total_items = 0
    total_revenue = 0
    for record in read_sales(path):
        if category is not None and record['category'] != category:
            continue
        if record['status'] != 'sold':
            continue
        total_items += 1
        total_revenue += record['price_cents']
        seller = record['seller']
        if seller not in sellers:
