HEADER = ['permit_id', 'address', 'category', 'status', 'submitted', 'estimated_cost']

def _record(row):
    if set(row) != set(HEADER):
        raise ValueError()
    try:
        ident = row['permit_id']
        if isinstance(ident, bool) or not isinstance(ident, int) or ident <= 0:
            raise ValueError()
        address = row['address']
        category = row['category']
        status = row['status']
        submitted = row['submitted']
        cost = row['estimated_cost']
        if not isinstance(address, str) or not address or (not isinstance(category, str)) or (category not in CATEGORIES) or (not isinstance(status, str)) or (status not in STATUSES):
            raise ValueError()
        if not isinstance(submitted, date) or isinstance(submitted, __import__('datetime').datetime):
            raise ValueError()
        if not isinstance(cost, Decimal) or cost < 0 or cost.as_tuple().exponent < -2:
            raise ValueError()
        return {'permit_id': ident, 'address': address, 'category': category, 'status': status, 'submitted': submitted, 'estimated_cost': cost.quantize(Decimal('0.01'))}
    except (KeyError, TypeError, ValueError, InvalidOperation):
        raise ValueError()

def parse_permits(text):
    if not isinstance(text, str):
        raise ValueError()
    try:
        rows = list(csv.reader(io.StringIO(text, newline='')))
        if not rows or rows[0] != HEADER or len(rows) < 2:
            raise ValueError()
        result = []
        seen = set()
        for fields in rows[1:]:
            if len(fields) != 6:
                raise ValueError()
            try:
                ident = int(fields[0])
                submitted = date.fromisoformat(fields[4])
                cost = Decimal(fields[5])
            except Exception:
                raise ValueError()
            if any((not x.strip() for x in fields)) or cost.as_tuple().exponent < -2:
                raise ValueError()
            item = _record(dict(zip(HEADER, [ident, fields[1], fields[2], fields[3], submitted, cost])))
            if ident in seen:
                raise ValueError()
            seen.add(ident)
            result.append(item)
        return result
    except (csv.Error, UnicodeError):
        raise ValueError()

def export_permits(permits, destination):
    try:
        normalized = [_record(x) for x in permits]
    except Exception:
        raise ValueError()
    if len({x['permit_id'] for x in normalized}) != len(normalized):
        raise ValueError()
    normalized.sort(key=lambda x: (CATEGORIES[x['category']], STATUSES[x['status']], x['submitted'], x['permit_id']))
    counts = {x: 0 for x in ['approved', 'pending', 'denied', 'withdrawn']}
    total = Decimal('0.00')
    output = io.StringIO(newline='')
    writer = csv.writer(output, lineterminator='\n')
    writer.writerow(HEADER + ['age_days'])
    for x in normalized:
        counts[x['status']] += 1
        total += x['estimated_cost']
        writer.writerow([x['permit_id'], x['address'], x['category'], x['status'], x['submitted'].isoformat(), format(x['estimated_cost'], '.2f'), (date(2024, 12, 31) - x['submitted']).days])
    fd, temp = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            f.write(output.getvalue())
        os.replace(temp, destination)
    except Exception:
        try:
            os.unlink(temp)
        except OSError:
            pass
        raise
    return {'rows': len(normalized), 'total_estimated_cost': total.quantize(Decimal('0.01')), 'by_status': counts}

