    for event in events:
        if not isinstance(event, dict) or not isinstance(event.get('account'), str) or (not event['account']):
            raise ValueError('invalid event')
        units = event.get('units')
        if isinstance(units, bool) or not isinstance(units, int) or units <= 0:
            raise ValueError('invalid units')
        if event['account'] not in quotas:
            raise ValueError('unknown account')
        totals[event['account']] += units
    entries = []
    for account, limit in quotas.items():
        used = totals[account]
        entries.append({'account': account, 'used': used, 'limit': limit, 'remaining': max(0, limit - used), 'exceeded': used > limit})
