import hashlib
import hmac
import os

def _credential(password):
    salt = os.urandom(16)
    rounds = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds)
    return f'{rounds}${salt.hex()}${digest.hex()}'

def _check(value, stored):
    try:
        rounds, salt, digest = stored.split('$')
        actual = hashlib.pbkdf2_hmac('sha256', value.encode(), bytes.fromhex(salt), int(rounds))
        return hmac.compare_digest(actual.hex(), digest)
    except (ValueError, TypeError):
        return False

def add_user(users, username, password, roles):
    if not isinstance(username, str) or not isinstance(password, str):
        raise TypeError()
    if not username or username.strip() != username or (not isinstance(roles, (list, tuple))):
        raise ValueError()
    if len(password) < 4 or username in users:
        raise ValueError()
    if any((not isinstance(role, str) for role in roles)):
        raise ValueError()
    users[username] = {'credential': _credential(password), 'roles': list(roles)}

def authenticate(users, username, password):
    record = users.get(username)
    if record is None or not isinstance(password, str):
        return False
    return _check(password, record['credential'])

def effective_permissions(users, username, resource, role_catalog):
    if not isinstance(resource, str):
        raise TypeError()
    record = users.get(username)
    if record is None:
        return []
    seen = set()
    entries = []

    def visit(name):
        if name in seen:
            return
        seen.add(name)
        role = role_catalog.get(name)
        if not isinstance(role, dict):
            return
        for parent in role.get('inherits', []):
            if isinstance(parent, str):
                visit(parent)
        values = role.get('permissions', [])
        if isinstance(values, (list, tuple)):
            entries.extend(values)
    for role in record['roles']:
        visit(role)
    allowed, denied = (set(), set())
    for item in entries:
        if not isinstance(item, str) or item.count(':') != 1:
            continue
        blocked = item.startswith('!')
        text = item[1:] if blocked else item
        pattern, action = text.split(':')
        if not pattern or not action:
            continue
        if _match(pattern, resource):
            (denied if blocked else allowed).add(action)
    return sorted(allowed - denied)

def _match(pattern, value):
    parts = pattern.split('*')
    if len(parts) == 1:
        return pattern == value
    if not value.startswith(parts[0]) or not value.endswith(parts[-1]):
        return False
    position = len(parts[0])
    for part in parts[1:-1]:
        position = value.find(part, position)
        if position < 0:
            return False
        position += len(part)
    return position <= len(value) - len(parts[-1])

