def build_health_page(paths: list[str], page: int=1, page_size: int=10) -> list[tuple[str, float]]:
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page <= 0) or (page_size <= 0):
        raise ValueError('page and page_size must be positive integers')
    observations = {}
    for path in paths:
        result = subprocess.run(['sort', '-t,', '-k1,1', path], capture_output=True, text=True, check=True)
        for raw in result.stdout.splitlines():
            if not raw.strip():
