import hashlib
import hmac
import json
from datetime import date

def _minutes(value, field):
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':':
        raise ValueError(f'invalid {field}')
    try:
        hour, minute = (int(value[:2]), int(value[3:]))
    except ValueError:
        raise ValueError(f'invalid {field}')
    if hour < 0 or hour > 23 or minute < 0 or (minute > 59):
        raise ValueError(f'invalid {field}')
    return hour * 60 + minute

def schedule_tours(tours: list[dict], config: dict[str, str]) -> dict:
    try:
        key = config['SIGNING_KEY']
    except (KeyError, TypeError):
        raise ValueError('SIGNING_KEY is required')
    if not isinstance(key, str) or not key:
        raise ValueError('SIGNING_KEY is required')
    records = []
    ids = set()
    for item in tours:
        if not isinstance(item, dict):
            raise ValueError('tour must be a mapping')
        required = ('id', 'date', 'start', 'duration', 'capacity', 'booked', 'guide')
        if any((name not in item for name in required)):
            raise ValueError('missing tour field')
        ident, guide = (item['id'], item['guide'])
        if not isinstance(ident, str) or not ident or ident in ids:
            raise ValueError('invalid or duplicate id')
        if not isinstance(guide, str) or not guide:
            raise ValueError('invalid guide')
        try:
            day = date.fromisoformat(item['date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        start = _minutes(item['start'], 'start')
        values = (item['duration'], item['capacity'], item['booked'])
        if any((isinstance(x, bool) or not isinstance(x, int) for x in values)):
            raise ValueError('invalid numeric value')
        duration, capacity, booked = values
        if duration <= 0 or capacity < 0 or booked < 0 or (booked > capacity) or (start + duration >= 1440):
            raise ValueError('invalid tour bounds')
        ids.add(ident)
        records.append((day.isoformat(), start, start + duration, guide, ident, capacity - booked))
    records.sort(key=lambda x: (x[0], x[1], x[3], x[4]))
    for i, current in enumerate(records):
        for previous in records[:i]:
            if previous[0] == current[0] and previous[3] == current[3] and (previous[2] > current[1]):
                raise ValueError('guide schedule conflict')
    days = []
    for day in sorted({r[0] for r in records}):
        group = [r for r in records if r[0] == day]
        tours_out = [{'id': r[4], 'start': f'{r[1] // 60:02d}:{r[1] % 60:02d}', 'end': f'{r[2] // 60:02d}:{r[2] % 60:02d}', 'guide': r[3], 'available': r[5]} for r in group]
        days.append({'date': day, 'total_seats': sum((r[5] for r in group)), 'tours': tours_out})
    payload = json.dumps(days, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return {'days': days, 'signature': signature}

