            if not isinstance(sample, str) or not isinstance(pages, int) or isinstance(pages, bool) or (pages <= 0):
                raise ValueError
            if not isinstance(recorded, str) or datetime.strptime(recorded, '%Y-%m-%d').strftime('%Y-%m-%d') != recorded:
                raise ValueError
            if not isinstance(tags, list) or not all((isinstance(tag, str) for tag in tags)):
                raise ValueError
            group = groups.setdefault(experiment, {'total_pages': 0, 'samples': set(), 'entry_count': 0, 'tags': {}})
            group['total_pages'] += pages
            group['samples'].add(sample)
            group['entry_count'] += 1
            for tag in tags:
                group['tags'][tag] = group['tags'].get(tag, 0) + 1
    except (UnicodeDecodeError, json.JSONDecodeError, KeyError, TypeError, ValueError, OverflowError):
        raise ValueError('invalid payload')
    result = []
