import csv
import os

def read_count_file(base_dir: str, relative_name: str) -> list[dict[str, object]]:
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, relative_name))
    if path != base and (not path.startswith(base + os.sep)):
        raise ValueError('file is outside base directory')
    with open(path, 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError('missing header')
        if header != ['sku', 'count']:
            raise ValueError('invalid header')
        result = []
        for row in reader:
            if not row:
                continue
            if len(row) != 2:
                raise ValueError('invalid row')
            sku = row[0].strip()
            if not sku:
                raise ValueError('empty sku')
            try:
                count = int(row[1].strip(), 10)
            except ValueError:
                raise ValueError('invalid count')
            if count < 0:
                raise ValueError('invalid count')
            result.append({'sku': sku, 'count': count})
        return result

def build_cycle_report(base_dir: str, relative_names: list[str], expected: dict[str, int]) -> list[dict[str, object]]:
    totals = {sku: 0 for sku in expected}
    seen = {sku: set() for sku in expected}
    for file_index, name in enumerate(relative_names):
        rows = read_count_file(base_dir, name)
        present = set()
        for row in rows:
            sku = row['sku']
            if sku not in expected:
                raise ValueError('unknown sku')
            totals[sku] += row['count']
            present.add(sku)
        for sku in present:
            seen[sku].add(file_index)
    result = []
    for sku, target in expected.items():
        variance = totals[sku] - target
        result.append({'sku': sku, 'count': totals[sku], 'target': target, 'variance': variance, 'files': len(seen[sku])})
    result.sort(key=lambda item: (-abs(item['variance']), item['sku']))
    return result

