        for line in lines[1:]:
            fields = line.split('\t')
            if len(fields) != 4:
                raise ValueError('invalid row')
            name, severity, advisory, score_text = fields
            if severity not in levels:
                raise ValueError('invalid severity')
            try:
                score = float(score_text)
            except ValueError:
                raise ValueError('invalid score')
            if not 0 <= score <= 10:
                raise ValueError('invalid score')
            if (package is None or name == package) and levels.index(severity) >= levels.index(min_severity):
                rows.append({'package': name, 'severity': severity, 'advisory': advisory, 'score': score})
