import hashlib
import hmac
import json
from datetime import datetime
from typing import Mapping

def process_webhook(headers: Mapping[str, str], body: bytes, secret: bytes) -> dict:
    if not isinstance(secret, bytes) or not secret:
        raise ValueError('invalid secret')
    signature = None
    for key, value in headers.items():
        if key.lower() == 'x-container-signature':
            signature = value
            break
    if not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        text = body.decode('utf-8')
        document = json.loads(text)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid body') from exc
    if not isinstance(document, dict) or not isinstance(document.get('events'), list):
        raise ValueError('invalid events')
    latest = {}
    counts = {}
    for index, event in enumerate(document['events']):
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        if not all((k in event for k in ('container', 'timestamp', 'status', 'location'))):
            raise ValueError('invalid event')
        container = event['container']
        timestamp = event['timestamp']
        status = event['status']
        location = event['location']
        if not isinstance(container, str) or not container:
            raise ValueError('invalid event')
        if not isinstance(timestamp, str) or len(timestamp) != 20 or (not timestamp.endswith('Z')):
            raise ValueError('invalid timestamp')
        try:
            parsed = datetime.strptime(timestamp, '%Y-%m-%dT%H:%M:%SZ')
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        if status not in ('in_transit', 'delivered', 'delayed', 'exception'):
            raise ValueError('invalid status')
        if not isinstance(location, str) or not location:
            raise ValueError('invalid location')
        counts[container] = counts.get(container, 0) + 1
        previous = latest.get(container)
        if previous is None or (parsed, index) >= (previous[0], previous[1]):
            latest[container] = (parsed, index, status, location)
    order = ('in_transit', 'delivered', 'delayed', 'exception')
    by_status = {status: 0 for status in order}
    containers = []
    for container in sorted(latest):
        _, _, status, location = latest[container]
        by_status[status] += 1
        containers.append({'id': container, 'status': status, 'location': location, 'updates': counts[container]})
    return {'received': len(document['events']), 'containers': containers, 'by_status': by_status}

