import hashlib
import hmac
import json
import re

def process_checkout_webhook(raw: str, secret: bytes) -> dict:
    if not isinstance(raw, str) or not isinstance(secret, bytes):
        raise TypeError()
    if not secret:
        raise ValueError()
    parts = raw.split('\n\n', 1)
    if len(parts) != 2:
        raise ValueError()
    header, body = parts
    lines = header.split('\n')
    if len(lines) != 2 or not lines[0].startswith('timestamp=') or (not lines[1].startswith('signature=')):
        raise ValueError()
    timestamp = lines[0][10:]
    signature = lines[1][10:]
    if not re.fullmatch('[0-9]{10}', timestamp) or not re.fullmatch('[0-9a-f]{64}', signature):
        raise ValueError()
    expected = hmac.new(secret, (timestamp + '.' + body).encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError()
    try:
        data = json.loads(body)
    except Exception as exc:
        raise ValueError() from exc
    if not isinstance(data, dict):
        raise ValueError()
    order_id = data.get('order_id')
    currency = data.get('currency')
    items = data.get('items')
    if not isinstance(order_id, str) or not order_id or (not isinstance(currency, str)) or (not re.fullmatch('[A-Z]{3}', currency)) or (not isinstance(items, list)) or (not items):
        raise ValueError()
    grouped = {}
    for item in items:
        if not isinstance(item, dict):
            raise ValueError()
        sku = item.get('sku')
        qty = item.get('quantity')
        price = item.get('unit_price_cents')
        if not isinstance(sku, str) or not sku or (not isinstance(qty, int)) or isinstance(qty, bool) or (qty <= 0) or (not isinstance(price, int)) or isinstance(price, bool) or (price < 0):
            raise ValueError()
        if sku in grouped and grouped[sku][1] != price:
            raise ValueError()
        if sku in grouped:
            grouped[sku][0] += qty
        else:
            grouped[sku] = [qty, price]
    extras = []
    for name in ('shipping_cents', 'tax_cents'):
        value = data.get(name, 0)
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ValueError()
        extras.append(value)
    output = [{'sku': sku, 'quantity': q, 'unit_price_cents': p, 'line_total_cents': q * p} for sku, (q, p) in grouped.items()]
    output.sort(key=lambda x: (-x['line_total_cents'], x['sku']))
    subtotal = sum((x['line_total_cents'] for x in output))
    return {'order_id': order_id, 'currency': currency, 'items': output, 'subtotal_cents': subtotal, 'shipping_cents': extras[0], 'tax_cents': extras[1], 'total_cents': subtotal + sum(extras)}

