import hashlib
import hmac
import json

def _unsigned(record):
    keys = ['event', 'ticket_id', 'quantity', 'price_cents', 'timestamp']
    if set(record) != set(keys + ['signature']):
        raise ValueError('invalid ticket fields')
    if not isinstance(record['event'], str) or not record['event']:
        raise ValueError('invalid event')
    if not isinstance(record['ticket_id'], str) or not record['ticket_id']:
        raise ValueError('invalid ticket id')
    if isinstance(record['quantity'], bool) or not isinstance(record['quantity'], int) or record['quantity'] <= 0:
        raise ValueError('invalid quantity')
    if isinstance(record['price_cents'], bool) or not isinstance(record['price_cents'], int) or record['price_cents'] < 0:
        raise ValueError('invalid price')
    if isinstance(record['timestamp'], bool) or not isinstance(record['timestamp'], int) or record['timestamp'] < 0:
        raise ValueError('invalid timestamp')
    signature = record['signature']
    if not isinstance(signature, str) or len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        raise ValueError('invalid signature')
    return ({key: record[key] for key in keys}, signature)

def verify_ticket_line(line: str, secret: bytes) -> dict:
    if not isinstance(line, str) or not isinstance(secret, bytes):
        raise TypeError('invalid argument type')
    try:
        record = json.loads(line)
    except (json.JSONDecodeError, TypeError):
        raise ValueError('invalid JSON')
    if not isinstance(record, dict):
        raise ValueError('ticket must be an object')
    unsigned, signature = _unsigned(record)
    body = json.dumps(unsigned, sort_keys=True, separators=(',', ':')).encode('utf-8')
    expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    return unsigned

def process_ticket_batch(text: str, secret: bytes) -> dict:
    if not isinstance(text, str) or not isinstance(secret, bytes):
        raise TypeError('invalid argument type')
    seen = set()
    groups = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        ticket = verify_ticket_line(line, secret)
        if ticket['ticket_id'] in seen:
            raise ValueError('duplicate ticket id')
        seen.add(ticket['ticket_id'])
        event = ticket['event']
        if event not in groups:
            groups[event] = {'quantity': 0, 'gross': 0, 'count': 0, 'first': ticket['timestamp']}
        group = groups[event]
        group['quantity'] += ticket['quantity']
        group['gross'] += ticket['quantity'] * ticket['price_cents']
        group['count'] += 1
        group['first'] = min(group['first'], ticket['timestamp'])
    events = []
    for event in sorted(groups):
        group = groups[event]
        events.append({'event': event, 'total_quantity': group['quantity'], 'gross_cents': group['gross'], 'ticket_count': group['count'], 'first_timestamp': group['first']})
    return {'events': events}

