import ast
import operator

def parse_delivery_window(window: str) -> tuple[int, int]:
    if not isinstance(window, str) or len(window) != 11 or window[2] != ':' or (window[5] != '-') or (window[8] != ':'):
        raise ValueError('invalid window')
    try:
        if not (window[:2] + window[3:5] + window[6:8] + window[9:]).isdigit():
            raise ValueError
        h1, m1, h2, m2 = (int(window[:2]), int(window[3:5]), int(window[6:8]), int(window[9:]))
    except Exception:
        raise ValueError('invalid window')
    if h1 > 23 or h2 > 23 or m1 > 59 or (m2 > 59):
        raise ValueError('invalid window')
    a, b = (h1 * 60 + m1, h2 * 60 + m2)
    if b <= a:
        raise ValueError('invalid window')
    return (a, b)

def _evaluate(text, env):
    tree = ast.parse(text, mode='eval')
    binops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    cmps = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}

    def go(n):
        if isinstance(n, ast.Expression):
            return go(n.body)
        if isinstance(n, ast.Constant) and (isinstance(n.value, (int, float, bool)) and (not isinstance(n.value, complex))):
            return n.value
        if isinstance(n, ast.Name):
            if n.id not in env:
                raise NameError(n.id)
            return env[n.id]
        if isinstance(n, ast.BinOp) and type(n.op) in binops:
            return binops[type(n.op)](go(n.left), go(n.right))
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
            v = go(n.operand)
            return +v if isinstance(n.op, ast.UAdd) else -v if isinstance(n.op, ast.USub) else not v
        if isinstance(n, ast.BoolOp):
            vals = [go(x) for x in n.values]
            return all(vals) if isinstance(n.op, ast.And) else any(vals)
        if isinstance(n, ast.Compare):
            vals = [go(n.left)] + [go(x) for x in n.comparators]
            return all((cmps[type(op)](a, b) for op, a, b in zip(n.ops, vals, vals[1:])))
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in ('min', 'max', 'round')) and (not n.keywords):
            return {'min': min, 'max': max, 'round': round}[n.func.id](*[go(x) for x in n.args])
        raise ValueError('invalid expression')
    return go(tree)

def schedule_deliveries(records: list[dict], truck_capacity: float, eligibility: str) -> list[dict]:
    if not isinstance(truck_capacity, (int, float)) or truck_capacity <= 0 or (not isinstance(eligibility, str)) or (not eligibility):
        raise ValueError('invalid input')
    chosen = []
    try:
        for r in records:
            if any((k not in r for k in ('id', 'day', 'window', 'weight', 'distance', 'priority'))):
                raise ValueError
            if not isinstance(r['day'], int) or r['day'] < 0 or (not isinstance(r['weight'], (int, float))) or (r['weight'] < 0) or (r['weight'] > truck_capacity):
                raise ValueError
            start, _ = parse_delivery_window(r['window'])
            env = {k: r[k] for k in ('weight', 'distance', 'priority', 'day')}
            env.update({'min': min, 'max': max, 'round': round})
            if bool(_evaluate(eligibility, env)):
                chosen.append((r, start))
    except Exception as e:
        if isinstance(e, ValueError):
            raise
