            arrival = node.attrib['arrival']
            departure = node.attrib['departure']
            status = node.attrib['status']
            a, d = (_day(arrival), _day(departure))
            if d <= a or status not in {'confirmed', 'cancelled', 'hold'}:
                raise ValueError
            guest_node = node.find('guest')
            party = node.find('party')
