                intent = value['intent']
                confidence = value['confidence']
                timestamp = value['timestamp']
                if not isinstance(session, str) or not session or (not isinstance(intent, str)) or (not intent) or isinstance(confidence, bool) or (not isinstance(confidence, (int, float))) or (not 0 <= confidence <= 1) or isinstance(timestamp, bool) or (not isinstance(timestamp, int)):
