    try:
        scheme, count, salt_text, digest_text = stored.split('$', 3)
        if scheme != 'pbkdf2':
            return False
        iterations = int(count)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (AttributeError, TypeError, ValueError):
        return False

def create_appraisal(items: list[dict], password: str, page: int=1, page_size: int=3) -> dict:
