_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def generate_unsubscribe_code(email: str) -> str:
    if not isinstance(email, str) or not email.strip():
        raise ValueError('email must be non-empty')
    return ''.join((random.choice(_ALPHABET) for _ in range(12)))

def build_unsubscribe_page(records: list[dict], page: int, page_size: int) -> dict:
    if not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or not 1 <= page_size <= 100:
        raise ValueError('invalid page size')
    retained = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        for field in ('email', 'reason', 'requested_at', 'status'):
            if field not in record or not isinstance(record[field], str):
                raise ValueError('invalid record')
        try:
            timestamp = datetime.fromisoformat(record['requested_at'].replace('Z', '+00:00'))
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        if record['status'] != 'pending':
            continue
        email = record['email'].strip().lower()
        if not email:
            raise ValueError('invalid email')
        old = retained.get(email)
        if old is None or timestamp > old[0]:
            retained[email] = (timestamp, {'email': email, 'reason': record['reason'], 'requested_at': record['requested_at']})
    ordered = sorted(retained.values(), key=lambda pair: (-pair[0].timestamp(), pair[1]['email']))
    total = len(ordered)
    start = (page - 1) * page_size
    items = []
    for _, item in ordered[start:start + page_size]:
        output = dict(item)
        output['code'] = generate_unsubscribe_code(item['email'])
        items.append(output)
    return {'page': page, 'page_size': page_size, 'total': total, 'items': items}

