    payload = b'{"events":[]}'
    secret = b"abc123"
    good = sign(payload, secret)
    assert verify_signature(payload, good, secret) is True
    assert verify_signature(payload, good[:-1] + ("0" if good[-1] != "0" else "1"), secret) is False
    assert verify_signature(payload, "", secret) is False
    assert verify_signature(payload, "sha256=" + "A" * 64, secret) is False
    assert verify_signature(payload, "sha1=" + good[7:], secret) is False


