import hashlib
import hmac
import json
from datetime import date, timedelta

def verify_signature(payload: bytes, signature: str, secret: bytes) -> bool:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        return False
    value = signature[7:]
    if len(value) != 64 or any((c not in '0123456789abcdef' for c in value)):
        return False
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(value, expected)

def process_referrals(payload: bytes, signature: str, secret: bytes) -> dict:
    if not verify_signature(payload, signature, secret):
        raise ValueError('invalid request')
    try:
        obj = json.loads(payload.decode('utf-8'))
        if not isinstance(obj, dict) or not isinstance(obj.get('events'), list):
            raise ValueError
        retained = {}
        for item in obj['events']:
            if not isinstance(item, dict):
                raise ValueError
            required = ('id', 'employee', 'candidate', 'status', 'date', 'points')
            if any((k not in item for k in required)):
                raise ValueError
            if any((not isinstance(item[k], str) or not item[k] for k in ('id', 'employee', 'candidate'))):
                raise ValueError
            if item['status'] not in ('pending', 'rejected', 'hired'):
                raise ValueError
            if not isinstance(item['points'], int) or isinstance(item['points'], bool) or item['points'] < 0:
                raise ValueError
            if not isinstance(item['date'], str) or date.fromisoformat(item['date']).isoformat() != item['date']:
                raise ValueError
            current = retained.get(item['id'])
            if current is None or item['date'] >= current['date']:
                retained[item['id']] = item
        if not retained:
            return {'period_end': None, 'window_start': None, 'leaders': []}
        end = max((date.fromisoformat(x['date']) for x in retained.values()))
        start = end - timedelta(days=29)
        totals = {}
        for item in retained.values():
            if start <= date.fromisoformat(item['date']) <= end and item['status'] == 'hired':
                row = totals.setdefault(item['employee'], [0, 0])
                row[0] += 1
                row[1] += item['points']
        leaders = [{'employee': name, 'hired': vals[0], 'points': vals[1]} for name, vals in totals.items()]
        leaders.sort(key=lambda x: (-x['points'], -x['hired'], x['employee']))
        return {'period_end': end.isoformat(), 'window_start': start.isoformat(), 'leaders': leaders}
    except (ValueError, TypeError, UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid request')

