import ast
import operator

class _Evaluator(ast.NodeVisitor):

    def __init__(self, values):
        self.values = values

    def visit_Expression(self, node):
        return self.visit(node.body)

    def visit_Constant(self, node):
        if isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node.value, bool):
            return node.value
        raise ValueError

    def visit_Name(self, node):
        if node.id not in self.values:
            raise ValueError
        return self.values[node.id]

    def visit_UnaryOp(self, node):
        value = self.visit(node.operand)
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.Not):
            return not value
        raise ValueError

    def visit_BinOp(self, node):
        left, right = (self.visit(node.left), self.visit(node.right))
        operations = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        for kind, function in operations.items():
            if isinstance(node.op, kind):
                return function(left, right)
        raise ValueError

    def visit_BoolOp(self, node):
        if isinstance(node.op, ast.And):
            result = self.visit(node.values[0])
            for item in node.values[1:]:
                if not result:
                    return result
                result = self.visit(item)
            return result
        if isinstance(node.op, ast.Or):
            result = self.visit(node.values[0])
            for item in node.values[1:]:
                if result:
                    return result
                result = self.visit(item)
            return result
        raise ValueError

    def visit_Compare(self, node):
        left = self.visit(node.left)
        for operation, child in zip(node.ops, node.comparators):
            right = self.visit(child)
            functions = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            function = next((f for k, f in functions.items() if isinstance(operation, k)), None)
            if function is None or not function(left, right):
                return False
            left = right
        return True

    def visit_Call(self, node):
        if not isinstance(node.func, ast.Name) or node.func.id not in {'min', 'max', 'round'} or node.keywords:
            raise ValueError
        args = [self.visit(arg) for arg in node.args]
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)

    def generic_visit(self, node):
        raise ValueError

def _evaluate(text, values):
    try:
        tree = ast.parse(text, mode='eval')
        return _Evaluator(values).visit(tree)
    except Exception as exc:
        raise ValueError from exc

def rank_drivers(drivers: list[dict], eligibility: str, score: str, limit: int) -> list[dict]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError
    required = ('id', 'rating', 'trips', 'distance', 'cancellations')
    chosen = []
    for driver in drivers:
        if any((key not in driver for key in required)) or not isinstance(driver['id'], str):
            raise ValueError
        values = {key: driver[key] for key in required[1:]}
        if any((isinstance(value, bool) or not isinstance(value, (int, float)) for value in values.values())):
            raise ValueError
        try:
            if _evaluate(eligibility, values):
                value = _evaluate(score, values)
                if isinstance(value, bool) or not isinstance(value, (int, float)):
                    raise ValueError
                chosen.append((value, driver['id'], dict(driver)))
        except Exception as exc:
            raise ValueError from exc
    chosen.sort(key=lambda item: (-item[0], item[1]))
    return [item[2] for item in chosen[:limit]]

