import tempfile
import os
import pytest


def write_file(text):
    f = tempfile.NamedTemporaryFile('w', encoding='utf-8', delete=False)
    f.write(text)
    f.close()
    return f.name


def cleanup(*paths):
    for path in paths:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass


