import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _sorted_lines(path):
    with open(path, encoding='utf-8') as f:
        header = f.readline().rstrip('\n\r')
    result = subprocess.run(['sort', '-t', '\t', '-k1,1', path], capture_output=True, text=True, check=True)
    return [line for line in result.stdout.splitlines() if line != header]

def _money(value):
    try:
        number = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid amount')
    if not number.is_finite():
        raise ValueError('invalid amount')
    return number

def _rounded(value):
    return float(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

def reconcile_freight(shipment_file: str, invoice_file: str) -> list[dict]:
    shipments = {}
    with open(shipment_file, encoding='utf-8') as f:
        header = f.readline().rstrip('\n\r')
    if header != 'shipment_id\tcarrier\tcharge':
        raise ValueError('invalid shipment header')
    for line in _sorted_lines(shipment_file):
        fields = line.split('\t')
        if len(fields) != 3 or not fields[0] or (not fields[1]):
            raise ValueError('invalid shipment row')
        amount = _money(fields[2])
        if fields[0] not in shipments:
            shipments[fields[0]] = {'carrier': fields[1], 'charge': Decimal('0')}
        shipments[fields[0]]['charge'] += amount
    invoices = {}
    with open(invoice_file, encoding='utf-8') as f:
        header = f.readline().rstrip('\n\r')
    if header != 'shipment_id\tinvoice_id\tbilled\tcurrency\tinvoice_date':
        raise ValueError('invalid invoice header')
    for line in _sorted_lines(invoice_file):
        fields = line.split('\t')
        if len(fields) != 5 or not fields[0] or (not fields[1]):
            raise ValueError('invalid invoice row')
        amount = _money(fields[2])
        if fields[0] not in invoices:
            invoices[fields[0]] = {'total': Decimal('0'), 'ids': []}
        invoices[fields[0]]['total'] += amount
        invoices[fields[0]]['ids'].append(fields[1])
    result = []
    for key in sorted(set(shipments) | set(invoices)):
        shipment = shipments.get(key)
        invoice = invoices.get(key)
        charge = shipment['charge'] if shipment else Decimal('0')
        total = invoice['total'] if invoice else Decimal('0')
        variance = total - charge
        if not shipment:
            status = 'unknown_shipment'
        elif not invoice:
            status = 'missing_invoice'
        elif abs(variance) <= Decimal('0.01'):
            status = 'matched'
        elif variance < 0:
            status = 'underbilled'
        else:
            status = 'overbilled'
        result.append({'shipment_id': key, 'carrier': shipment['carrier'] if shipment else '', 'shipment_charge': _rounded(charge), 'invoice_total': _rounded(total), 'variance': _rounded(variance), 'status': status, 'invoice_ids': invoice['ids'] if invoice else []})
    return result

def summarize_reconciliation(rows: list[dict]) -> dict:
    statuses = ['matched', 'underbilled', 'overbilled', 'missing_invoice', 'unknown_shipment']
    counts = {status: 0 for status in statuses}
    total = Decimal('0')
    for row in rows:
        if row.get('status') not in counts:
            raise ValueError('unknown status')
        try:
            total += Decimal(str(row['variance']))
        except Exception:
            raise ValueError('invalid variance')
        counts[row['status']] += 1
    counts['net_variance'] = _rounded(total)
    return counts

