import hashlib
import hmac
import os

def hash_approval_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if pin == '':
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)
    return '100000$' + salt.hex() + '$' + digest.hex()

def verify_approval_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        return False
    try:
        iterations_text, salt_text, digest_text = stored.split('$')
        iterations = int(iterations_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        if iterations < 1 or len(salt) == 0 or len(expected) == 0:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

