import sqlite3

def initialize_db(conn: sqlite3.Connection) -> None:
    conn.executescript("\n    create table if not exists employees (id integer primary key, name text not null, department text not null);\n    create table if not exists badges (id integer primary key, employee_id integer not null references employees(id), code text not null unique, issued_at text not null, revoked_at text);\n    create table if not exists events (id integer primary key, badge_id integer not null references badges(id), event_time text not null, direction text not null check(direction in ('entry','exit')));\n    ")
    conn.commit()

def add_employee(conn: sqlite3.Connection, employee_id: int, name: str, department: str) -> None:
    if not name.strip() or not department.strip():
        raise ValueError('empty employee field')
    conn.execute('insert into employees(id,name,department) values (?,?,?)', (employee_id, name, department))
    conn.commit()

def issue_badge(conn: sqlite3.Connection, employee_id: int, code: str, issued_at: str, valid_until: str | None=None) -> int:
    if not code.strip() or not issued_at.strip() or (valid_until is not None and (not valid_until.strip() or valid_until <= issued_at)):
        raise ValueError('invalid badge')
    cur = conn.execute('insert into badges(employee_id,code,issued_at,revoked_at) values (?,?,?,?)', (employee_id, code, issued_at, valid_until))
    conn.commit()
    return cur.lastrowid

def record_event(conn: sqlite3.Connection, badge_id: int, event_time: str, direction: str) -> None:
    if not event_time.strip() or direction not in ('entry', 'exit'):
        raise ValueError('invalid event')
    conn.execute('insert into events(badge_id,event_time,direction) values (?,?,?)', (badge_id, event_time, direction))
    conn.commit()

def badge_report(conn: sqlite3.Connection, search: str='', sort_by: str='name', descending: bool=False, active_only: bool=False) -> list[dict]:
    if sort_by not in ('name', 'department', 'issued_at', 'event_count'):
        raise ValueError('invalid sort')
    term = '%' + search.casefold() + '%'
    where = 'b.revoked_at is null and ' if active_only else ''
    rows = conn.execute(f'select e.id,e.name,e.department,b.code,b.issued_at,b.revoked_at,count(x.id),max(x.event_time)\n        from badges b join employees e on e.id=b.employee_id left join events x on x.badge_id=b.id\n        where {where}(lower(e.name) like ? or lower(e.department) like ? or lower(b.code) like ?)\n        group by b.id,e.id order by e.id', (term, term, term)).fetchall()
    out = [dict(zip(('employee_id', 'name', 'department', 'badge_code', 'issued_at', 'revoked_at', 'event_count', 'last_event'), r)) for r in rows]
    key = lambda r: r[sort_by].casefold() if sort_by in ('name', 'department') else r[sort_by]
    return sorted(out, key=key, reverse=descending)

