        if 'name' not in dataset.attrib:
            raise ValueError('missing dataset name')
        name = dataset.attrib['name']
        group = groups.setdefault(name, {'name': name, 'file_count': 0, 'total_bytes': 0, 'kinds': {}})
        for item in dataset.findall('file'):
            if any((key not in item.attrib for key in ('path', 'size', 'kind'))):
                raise ValueError('missing file attribute')
            if item.get('status', 'active') != 'active':
                continue
            try:
                size = int(item.attrib['size'])
            except ValueError as exc:
                raise ValueError('invalid size') from exc
            if size < 0:
                raise ValueError('invalid size')
            kind = item.attrib['kind']
            group['file_count'] += 1
            group['total_bytes'] += size
            group['kinds'][kind] = group['kinds'].get(kind, 0) + 1
            files.append({'dataset': name, 'path': item.attrib['path'], 'size': size, 'kind': kind})
    for group in groups.values():
        group['kinds'] = dict(sorted(group['kinds'].items()))
    files.sort(key=lambda x: (-x['size'], x['path'], x['dataset']))
