import json
import os

def summarize_activity_bookings(base_dir: str, filename: str, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if not filename or os.path.isabs(filename):
        raise ValueError('invalid filename')
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, filename))
    try:
        if os.path.commonpath([base, path]) != base or path == base:
            raise ValueError('invalid filename')
    except ValueError:
        raise ValueError('invalid filename')
    with open(path, 'r', encoding='utf-8') as handle:
        try:
            data = json.load(handle)
        except (json.JSONDecodeError, TypeError):
            raise ValueError('invalid JSON')
    if not isinstance(data, list):
        raise ValueError('invalid document')
    groups = {}
    for row in data:
        if not isinstance(row, dict):
            raise ValueError('invalid booking')
        if not isinstance(row.get('activity'), str) or not row['activity']:
            raise ValueError('invalid booking')
        if row.get('status') not in ('confirmed', 'cancelled'):
            raise ValueError('invalid booking')
        price = row.get('price')
        if isinstance(price, bool) or not isinstance(price, (int, float)) or price < 0:
            raise ValueError('invalid booking')
        rating = row.get('rating')
        if rating is not None and (isinstance(rating, bool) or not isinstance(rating, (int, float)) or (not 1 <= rating <= 5)):
            raise ValueError('invalid booking')
        if row['status'] == 'confirmed':
            item = groups.setdefault(row['activity'], [0, 0.0, []])
            item[0] += 1
            item[1] += price
            if rating is not None:
                item[2].append(rating)
    result = []
    for activity, (count, revenue, ratings) in groups.items():
        result.append({'activity': activity, 'bookings': count, 'revenue': round(revenue, 2), 'average_rating': round(sum(ratings) / len(ratings), 2) if ratings else None})
    result.sort(key=lambda x: (-x['revenue'], -x['bookings'], x['activity']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

