import csv
import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return 'pbkdf2$100000$' + salt.hex() + '$' + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    parts = stored.split('$')
    if len(parts) != 4 or parts[0] != 'pbkdf2' or parts[1] != '100000':
        return False
    try:
        salt = bytes.fromhex(parts[2])
        expected = bytes.fromhex(parts[3])
    except ValueError:
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

def seed_teams(rows: list[str], administrator_hash: str, administrator_password: str) -> list[str]:
    if not verify_password(administrator_password, administrator_hash):
        raise PermissionError('administrator authentication failed')
    teams = []
    seen = set()
    for position, row in enumerate(rows):
        if not isinstance(row, str):
            raise ValueError('row must be text')
        try:
            fields = next(csv.reader([row]))
        except (csv.Error, StopIteration):
            raise ValueError('invalid CSV row')
        if len(fields) != 6:
            raise ValueError('row must have six fields')
        name = fields[0].strip()
        region = fields[1].strip()
        if not name or not region or name in seen:
            raise ValueError('invalid or duplicate team')
        try:
            wins, draws, differential, penalty = (int(value.strip()) for value in fields[2:])
        except ValueError:
            raise ValueError('numeric fields required')
        if min(wins, draws, differential, penalty) < 0:
            raise ValueError('numeric fields must be nonnegative')
        seen.add(name)
        score = 3 * wins + draws - penalty
        teams.append((name, score, differential, wins, name.casefold(), position))
    teams.sort(key=lambda item: (-item[1], -item[2], -item[3], item[4], item[5]))
    return [item[0] for item in teams]

