import csv
import io
from datetime import datetime, date, timezone

def parse_toll_log(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty log')
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except (csv.Error, UnicodeError) as exc:
        raise ValueError('invalid csv') from exc
    header = ['event_id', 'account_id', 'vehicle_id', 'timestamp', 'plaza', 'cents']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 6 or any((x == '' for x in row[:4] + row[4:5])):
            raise ValueError('invalid row')
        try:
            cents = int(row[5])
        except ValueError as exc:
            raise ValueError('invalid cents') from exc
        if row[0] in seen:
            raise ValueError('duplicate event')
        seen.add(row[0])
        result.append(dict(zip(header, row[:5] + [cents])))
    return result

def calculate_statement(requester: dict, account: dict, events: list[dict], start: str, end: str) -> dict:
    try:
        begin = date.fromisoformat(start)
        finish = date.fromisoformat(end)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid period') from exc
    if finish <= begin:
        raise ValueError('invalid period')
    if requester.get('tenant_id') != account.get('tenant_id') or (requester.get('id') != account.get('owner_id') and 'toll_admin' not in requester.get('roles', [])):
        raise PermissionError('not permitted')
    seen = set()
    daily = {}
    vehicles = {}
    for event in events:
        if event.get('event_id') in seen:
            raise ValueError('duplicate event')
        seen.add(event.get('event_id'))
        if event.get('account_id') == account.get('id') and event.get('vehicle_id') not in account.get('vehicle_ids', []):
            raise ValueError('unknown vehicle')
        try:
            stamp = datetime.fromisoformat(event['timestamp'].replace('Z', '+00:00')).astimezone(timezone.utc)
            cents = int(event['cents'])
        except (KeyError, TypeError, ValueError, OverflowError) as exc:
            raise ValueError('invalid event') from exc
        if cents < 0:
            raise ValueError('invalid cents')
        if event.get('account_id') != account.get('id') or not begin <= stamp.date() < finish:
            continue
        day = stamp.date().isoformat()
        daily[day] = daily.get(day, 0) + cents
