    for node in root:
        if node.tag != 'alert':
            raise ValueError('invalid child')
        a = node.attrib
        required = ('id', 'region', 'severity', 'issued', 'expires')
        if any((not a.get(k, '').strip() for k in required)) or a['severity'] not in _LEVEL or a['id'] in seen:
            raise ValueError('invalid alert')
