import csv
import subprocess
from decimal import Decimal, ROUND_HALF_UP
_HEADER = ['employee_id', 'employee_name', 'department', 'gross_cents', 'deductions_cents', 'pay_period']

def read_payroll(path: str) -> list[dict]:
    with open(path, 'r', encoding='utf-8', newline='') as f:
        header = f.readline().rstrip('\r\n').split(',')
    if header != _HEADER:
        raise ValueError('invalid header')
    result = subprocess.run(['sort', '-t,', '-k3,3', '-k1,1', '--', path], capture_output=True, text=True, check=True).stdout
    rows = []
    seen = set()
    for raw in result.splitlines():
        if raw == ','.join(_HEADER):
            continue
        fields = next(csv.reader([raw]))
        if len(fields) != 6 or any((x == '' for x in fields)):
            raise ValueError('invalid row')
        employee_id, name, department, gross, deductions, period = fields
        try:
            gross_i = int(gross)
            deductions_i = int(deductions)
        except ValueError:
            raise ValueError('invalid amount')
        if gross_i < 0 or deductions_i < 0 or employee_id in seen:
            raise ValueError('invalid row')
        seen.add(employee_id)
        rows.append({'employee_id': employee_id, 'employee_name': name, 'department': department, 'gross_cents': gross_i, 'deductions_cents': deductions_i, 'pay_period': period, 'net_cents': gross_i - deductions_i})
    return rows

def payroll_report(path: str, department: str | None=None, minimum_net: int=0) -> list[dict]:
    if minimum_net < 0:
        raise ValueError('invalid threshold')
    groups = {}
    for row in read_payroll(path):
        if (department is None or row['department'] == department) and row['net_cents'] >= minimum_net:
            groups.setdefault(row['department'], []).append(row)
    output = []
    for dept in sorted(groups):
        rows = groups[dept]
        total_net = sum((r['net_cents'] for r in rows))
        top = min(rows, key=lambda r: (-r['net_cents'], r['employee_id']))
        average = int((Decimal(total_net) / len(rows)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        output.append({'department': dept, 'employee_count': len(rows), 'gross_cents': sum((r['gross_cents'] for r in rows)), 'deductions_cents': sum((r['deductions_cents'] for r in rows)), 'net_cents': total_net, 'average_net_cents': average, 'top_employee_id': top['employee_id']})
    return output

