import hashlib
import hmac
import os

def _password_value(password):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def create_learner(username: str, password: str) -> dict:
    if not isinstance(username, str) or not username.strip():
        raise ValueError('invalid username')
    if not isinstance(password, str) or len(password) < 8:
        raise ValueError('invalid password')
    return {'username': username.strip(), 'password': _password_value(password), 'sessions': []}

def authenticate(learner: dict, password: str) -> bool:
    if not isinstance(learner, dict) or not isinstance(password, str):
        return False
    value = learner.get('password')
    if not isinstance(value, str):
        return False
    try:
        salt_text, digest_text = value.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def record_session(learner: dict, unit: str, score: int, minutes: int) -> dict:
    if not isinstance(learner, dict) or not isinstance(learner.get('sessions'), list):
        raise ValueError('invalid learner')
    if not isinstance(unit, str) or not unit.strip():
        raise ValueError('invalid unit')
    if isinstance(score, bool) or not isinstance(score, int) or (not 0 <= score <= 100):
        raise ValueError('invalid score')
    if isinstance(minutes, bool) or not isinstance(minutes, int) or minutes <= 0:
        raise ValueError('invalid minutes')
    learner['sessions'].append({'unit': unit.strip(), 'score': score, 'minutes': minutes})
    return learner

def progress_report(learner: dict) -> dict:
    sessions = learner.get('sessions', [])
    if not isinstance(sessions, list):
        raise ValueError('invalid sessions')
    groups = {}
    for item in sessions:
        if not isinstance(item, dict) or not isinstance(item.get('unit'), str) or (not item['unit']) or isinstance(item.get('score'), bool) or (not isinstance(item.get('score'), int)) or (not 0 <= item['score'] <= 100) or isinstance(item.get('minutes'), bool) or (not isinstance(item.get('minutes'), int)) or (item['minutes'] <= 0):
            raise ValueError('invalid session')
        groups.setdefault(item['unit'], []).append(item)
    result = {}
    for unit in sorted(groups):
        items = groups[unit]
        scores = [x['score'] for x in items]
        recent = scores[-3:]
        result[unit] = {'attempts': len(items), 'average': round(sum(scores) / len(scores), 2), 'best': max(scores), 'minutes': sum((x['minutes'] for x in items)), 'mastery': round(sum(recent) / len(recent), 2)}
    return result

def leaderboard(learners: list[dict]) -> list[dict]:
    if not isinstance(learners, list) or any((not isinstance(x, dict) for x in learners)):
        raise ValueError('invalid learners')
    rows = []
    for learner in learners:
        report = progress_report(learner)
        mastery = round(sum((x['mastery'] for x in report.values())) / len(report), 2) if report else 0.0
        rows.append({'username': learner.get('username', ''), 'mastery': mastery, 'minutes': sum((x['minutes'] for x in learner.get('sessions', [])))})
    return sorted(rows, key=lambda x: (-x['mastery'], x['username']))

