import pytest


def test_empty_input_and_defaults():
    assert evaluate_feature_flags({"id": "u1", "tenant_id": "t1", "roles": []}, [], {}) == []
    flags = [{"name": "basic", "enabled": True, "tenant_id": "t1", "owner_id": "u1"}]
    assert evaluate_feature_flags({"id": "u1", "tenant_id": "t1", "roles": []}, flags, {}) == ["basic"]


def test_rules_and_missing_attributes():
    requester = {"id": "u1", "tenant_id": "t1", "roles": []}
    flags = [
        {"name": "one", "enabled": True, "tenant_id": "t1", "owner_id": "u1", "rules": [{"attribute": "country", "op": "equals", "value": "US"}]},
        {"name": "two", "enabled": True, "tenant_id": "t1", "owner_id": "u1", "rules": [{"attribute": "country", "op": "in", "value": ["CA", "GB"]}]},
        {"name": "three", "enabled": False, "tenant_id": "t1", "owner_id": "u1"},
    ]
    assert evaluate_feature_flags(requester, flags, {"country": "US"}) == ["one"]
    assert evaluate_feature_flags(requester, flags, {}) == []


def test_numeric_operators_and_all_rules():
    requester = {"id": "u1", "tenant_id": "t1", "roles": []}
    flag = {"name": "cohort", "enabled": True, "tenant_id": "t1", "owner_id": "u1", "rules": [
        {"attribute": "age", "op": "gte", "value": 18},
        {"attribute": "score", "op": "lt", "value": 90},
    ]}
    assert evaluate_feature_flags(requester, [flag], {"age": 18, "score": 89}) == ["cohort"]
    assert evaluate_feature_flags(requester, [flag], {"age": 17, "score": 89}) == []
    assert evaluate_feature_flags(requester, [flag], {"age": 18, "score": 90}) == []


def test_priority_name_ordering_and_pagination():
    requester = {"id": "u1", "tenant_id": "t1", "roles": []}
