import os
import json
import hmac
import hashlib
from datetime import datetime, timedelta
from decimal import Decimal, ROUND_HALF_UP

def segment_customers(events: list[dict], as_of: datetime) -> list[dict]:
    if as_of.tzinfo is None:
        raise ValueError('as_of must include timezone information')
    start = as_of - timedelta(days=30)
    grouped = {}
    for event in events:
        try:
            customer = event['customer_id']
            amount = event['amount']
            category = event['category']
            timestamp = datetime.fromisoformat(event['timestamp'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('malformed event')
        if not isinstance(customer, str) or not customer:
            raise ValueError('customer_id must be non-empty')
        if not isinstance(category, str) or not category:
            raise ValueError('category must be non-empty')
        if timestamp.tzinfo is None or not isinstance(amount, (int, float)) or isinstance(amount, bool) or (amount < 0):
            raise ValueError('invalid event')
        if start <= timestamp <= as_of:
            grouped.setdefault(customer, []).append((Decimal(str(amount)), category, timestamp))
    rank = {'VIP': 0, 'LOYAL': 1, 'BROWSING': 2}
    result = []
    for customer, items in grouped.items():
        total = sum((x[0] for x in items), Decimal('0'))
        categories = {}
        dates = {x[2].date() for x in items}
        for amount, category, _ in items:
            categories[category] = categories.get(category, Decimal('0')) + amount
        top = min(categories, key=lambda c: (-categories[c], c))
        segment = 'VIP' if total >= 500 else 'LOYAL' if total >= 200 else 'BROWSING'
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'customer_id': customer, 'segment': segment, 'spend': float(rounded), 'visits': len(dates), 'top_category': top})
    result.sort(key=lambda x: (rank[x['segment']], -x['spend'], x['customer_id']))
    return result

def render_signed_report(events: list[dict], as_of: datetime, config: dict | None=None) -> dict:
    segments = segment_customers(events, as_of)
    payload = json.dumps({'as_of': as_of.isoformat(), 'segments': segments}, sort_keys=True, separators=(',', ':'))
    key = config['signing_key'] if config is not None and 'signing_key' in config else os.environ.get('SEGMENT_SIGNING_KEY')
    if key is None:
        raise ValueError('SEGMENT_SIGNING_KEY is required')
    if isinstance(key, str):
        key = key.encode('utf-8')
    return {'payload': payload, 'signature': hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()}

