import os
import re

def _date(value):
    if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', value):
        raise ValueError('invalid date')
    try:
        import datetime
        datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def parse_guest_records(text: str) -> list[dict]:
    result = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields, current, escaped = ([], [], False)
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current).strip())
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current).strip())
        if len(fields) != 5:
            raise ValueError('wrong field count')
        rid, guest, room, arrival, nights = fields
        if not rid or not guest or rid in seen:
            raise ValueError('invalid or duplicate reservation')
        try:
            room_n, night_n = (int(room), int(nights))
        except ValueError:
            raise ValueError('invalid number')
        _date(arrival)
        if room_n <= 0 or not 1 <= night_n <= 30:
            raise ValueError('invalid stay')
        seen.add(rid)
        result.append({'reservation_id': rid, 'guest': guest, 'room': room_n, 'arrival': arrival, 'nights': night_n})
    return result

def build_checkin_plan(text: str, today: str) -> list[dict]:
    _date(today)
    records = [r for r in parse_guest_records(text) if r['arrival'] >= today]
    records.sort(key=lambda r: (r['arrival'], r['room'], r['reservation_id']))
    return [dict(record, position=index) for index, record in enumerate(records, 1)]

def sign_checkin(record: dict, config: dict) -> str:
    required = ('reservation_id', 'guest', 'room', 'arrival', 'nights')
    if any((key not in record for key in required)):
        raise ValueError('incomplete check-in record')
    try:
        key = config['signing_key']
    except (KeyError, TypeError):
        key = os.environ['HOTEL_SIGNING_KEY']
    if not isinstance(key, str):
        raise ValueError('signing key is missing')
    message = f"{record['reservation_id']}:{record['guest']}:{int(record['room'])}:{record['arrival']}:{int(record['nights'])}".encode()
    return hmac.new(key.encode(), message, hashlib.sha256).hexdigest()

