def signed(data, secret='civic-key'):
    raw = json.dumps(data, separators=(',', ':')).encode()
    sig = hmac.new(secret.encode(), raw, hashlib.sha256).hexdigest()
    return (raw, sig)

def test_groups_sorted_and_aggregated():
    data = {'complaints': [{'id': 'b', 'ward': '2', 'category': 'noise', 'priority': 3, 'status': 'open', 'submitted_at': '2024-03-01T10:00:00Z'}, {'id': 'a', 'ward': '1', 'category': 'roads', 'priority': 1, 'status': 'closed', 'submitted_at': '2024-03-02T09:00:00Z'}, {'id': 'c', 'ward': '1', 'category': 'roads', 'priority': 2, 'status': 'open', 'submitted_at': '2024-03-03T09:00:00Z'}, {'id': 'd', 'ward': '1', 'category': 'parks', 'priority': 5, 'status': 'open', 'submitted_at': '2024-02-01T09:00:00Z'}]}
    raw, sig = signed(data)
    assert process_complaint_submission(raw, sig, 'civic-key') == {'groups': [{'ward': '1', 'category': 'parks', 'total': 1, 'open': 1, 'high_priority': 0, 'latest_submitted_at': '2024-02-01T09:00:00Z'}, {'ward': '1', 'category': 'roads', 'total': 2, 'open': 1, 'high_priority': 2, 'latest_submitted_at': '2024-03-03T09:00:00Z'}, {'ward': '2', 'category': 'noise', 'total': 1, 'open': 1, 'high_priority': 0, 'latest_submitted_at': '2024-03-01T10:00:00Z'}]}

def test_input_order_does_not_change_result():
    items = [{'id': '2', 'ward': 'A', 'category': 'z', 'priority': 2, 'status': 'closed', 'submitted_at': '2024-01-02T00:00:00Z'}, {'id': '1', 'ward': 'A', 'category': 'z', 'priority': 4, 'status': 'open', 'submitted_at': '2024-01-01T00:00:00Z'}]
    r1, s1 = signed({'complaints': items})
    r2, s2 = signed({'complaints': list(reversed(items))})
