import hashlib
import hmac
import json
from datetime import datetime

def process_complaint_submission(payload: bytes, signature: str, secret: str) -> dict:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or len(signature) != 64:
        raise ValueError('invalid signature')
    if any((c not in '0123456789abcdef' for c in signature)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        text = payload.decode('utf-8')
        root = json.loads(text)
        if not isinstance(root, dict) or set(root) != {'complaints'}:
            raise ValueError
        complaints = root['complaints']
        if not isinstance(complaints, list) or not complaints:
            raise ValueError
