def summarize_volcano_report(xml_text: str, min_alert_level: float=0.0) -> list[dict]:
    if not isinstance(min_alert_level, (int, float)) or not math.isfinite(min_alert_level) or min_alert_level < 0:
        raise ValueError('invalid alert level')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
