        raise ValueError('invalid root')
    groups = defaultdict(list)
    for element in root:
        if element.tag != 'reading':
            continue
        if any((name not in element.attrib for name in ('volcano', 'timestamp', 'gas', 'level'))):
            raise ValueError('missing reading attribute')
        try:
            level = float(element.attrib['level'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid level') from exc
        if not math.isfinite(level) or level < 0:
            raise ValueError('invalid level')
        groups[element.attrib['volcano']].append(level)
