from decimal import Decimal, ROUND_HALF_UP
from lxml import etree

def summarize_telemetry(xml: str, min_floor: int=0, limit: int=10) -> list[dict]:
    if min_floor < 0 or limit < 0:
        raise ValueError('invalid bounds')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'telemetry':
        raise ValueError('invalid root')
    groups = {}
    for elevator in root.findall('elevator'):
        ident = elevator.get('id')
        if ident is None:
            raise ValueError('missing id')
        for child in elevator:
            if child.tag != 'reading':
                raise ValueError('invalid child')
            try:
                floor = int(child.attrib['floor'])
                trips = int(child.attrib['trips'])
                energy = Decimal(child.attrib['energy_kwh'])
                faults = int(child.attrib['faults'])
            except (KeyError, ValueError, ArithmeticError) as exc:
                raise ValueError('invalid reading') from exc
            if floor < min_floor:
                continue
            item = groups.setdefault(ident, [0, Decimal('0'), 0, floor])
            item[0] += trips
            item[1] += energy
            item[2] += faults
            item[3] = max(item[3], floor)
    result = []
    for ident, (trips, energy, faults, max_floor) in groups.items():
        rounded = energy.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'id': ident, 'total_trips': trips, 'energy_kwh': float(rounded), 'faults': faults, 'max_floor': max_floor})
    result.sort(key=lambda x: (-x['total_trips'], x['id']))
