            continue
        if any((name not in node.attrib for name in required)):
            raise ValueError('missing attribute')
        try:
            value = float(node.get('value'))
            limit = float(node.get('limit'))
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid number') from exc
        if not math.isfinite(value) or not math.isfinite(limit):
            raise ValueError('invalid number')
        records.append({'site': node.get('site'), 'parameter': node.get('parameter'), 'value': value, 'limit': limit, 'unit': node.get('unit'), 'timestamp': node.get('timestamp'), 'violation': value > limit})
