    groups = {}
    for record in records:
        groups.setdefault(record['site'], []).append(record)
    sites = []
    for site in sorted(groups):
        group = groups[site]
        sites.append({'site': site, 'count': len(group), 'violations': sum((x['violation'] for x in group)), 'average': round(sum((x['value'] for x in group)) / len(group), 2)})
    start = (page - 1) * page_size
