        item['value'] = round(item['value'], 3)
        item['limit'] = round(item['limit'], 3)
        items.append(item)
    return {'total': len(records), 'violations': sum((x['violation'] for x in records)), 'sites': sites, 'page': page, 'page_size': page_size, 'items': items}

