import ast
import operator

def evaluate_expression(expression: str, variables: dict[str, int | float]):
    tree = ast.parse(expression, mode='eval')

    def visit(node):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float, bool):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise NameError(node.id)
            return variables[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = visit(child)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                right = visit(right_node)
                if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            args = [visit(x) for x in node.args]
            if node.func.id == 'round' and len(args) not in (1, 2):
                raise TypeError('round arguments')
            if node.func.id in ('min', 'max') and (not args):
                raise TypeError('arguments')
            return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
        raise ValueError('unsupported expression')
    return visit(tree.body)

def build_quality_report(records: list[dict], filter_expression: str, score_expression: str) -> dict:
    selected = []
    for record in records:
        samples = record['samples']
        if not samples:
            raise ValueError('samples must not be empty')
        variables = {'defect_rate': sum(samples) / len(samples), 'days_late': record['days_late'], 'rework': record['rework'], 'sample_count': len(samples)}
        if evaluate_expression(filter_expression, variables):
            score = evaluate_expression(score_expression, variables)
            if isinstance(score, bool) or not isinstance(score, (int, float)):
                raise TypeError('score must be numeric')
            selected.append((record['supplier'], record['lot'], round(float(score), 2)))
    selected.sort(key=lambda x: (-x[2], x[0], x[1]))
    audits = []
    totals = {}
    for supplier, lot, score in selected:
        status = 'pass' if score >= 90 else 'watch' if score >= 70 else 'fail'
        audits.append({'supplier': supplier, 'lot': lot, 'score': score, 'status': status})
        totals.setdefault(supplier, []).append(score)
    supplier_totals = {s: {'count': len(v), 'average_score': round(sum(v) / len(v), 2)} for s, v in totals.items()}
    return {'audits': audits, 'supplier_totals': supplier_totals}

