_STATUSES = {'pending', 'active', 'suspended', 'terminated'}

def _split(line):
    out, cur, escaped = ([], [], False)
    for ch in line:
        if escaped:
            if ch not in '\\|':
                raise ValueError('bad escape')
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('bad escape')
    out.append(''.join(cur))
    return out

def parse_enrollment(line: str) -> dict:
    if not isinstance(line, str):
        raise ValueError('line')
    fields = _split(line)
    if len(fields) != 6 or any((not x for x in fields[:3] + fields[5:])):
        raise ValueError('fields')
    try:
        start = date.fromisoformat(fields[3])
        end = date.fromisoformat(fields[4])
    except (TypeError, ValueError):
        raise ValueError('date')
    if end < start or fields[5] not in _STATUSES:
        raise ValueError('enrollment')
    return {'member_id': fields[0], 'tenant_id': fields[1], 'plan': fields[2], 'start': start, 'end': end, 'status': fields[5]}

def coverage_summary(enrollments: list[dict], year: int) -> dict:
    if type(year) is not int or not 1900 <= year <= 2100:
        raise ValueError('year')
    first, last = (date(year, 1, 1), date(year, 12, 31))
    totals = {}
    for e in enrollments:
        if not isinstance(e, dict) or not isinstance(e.get('start'), date) or (not isinstance(e.get('end'), date)) or (e['end'] < e['start']) or (not isinstance(e.get('plan'), str)) or (e.get('status') not in _STATUSES):
            raise ValueError('enrollment')
        if e['status'] == 'active':
            lo, hi = (max(first, e['start']), min(last, e['end']))
            if lo <= hi:
                totals[e['plan']] = totals.get(e['plan'], 0) + (hi - lo).days + 1
    return {k: totals[k] for k in sorted(totals)}

def change_enrollment_status(requester: dict, enrollment: dict, new_status: str, reason: str='') -> dict:
    if new_status not in _STATUSES or not isinstance(reason, str) or (not reason.strip()):
        raise ValueError('change')
    current = enrollment.get('status')
    if current == 'terminated' or (new_status == 'terminated' and current not in {'active', 'suspended'}) or current == new_status:
        raise ValueError('transition')
    allowed = requester.get('tenant_id') == enrollment.get('tenant_id') and (requester.get('id') == enrollment.get('owner_id') or 'benefits_admin' in requester.get('roles', []) or 'admin' in requester.get('roles', []))
    if not allowed:
        raise PermissionError('not allowed')
    result = dict(enrollment)
    result.update(status=new_status, changed_by=requester.get('id'), reason=reason)
    return result

