            if key in seen:
                raise ValueError('duplicate lot')
            seen.add(key)
            result.append({'sku': item.attrib['sku'], 'zone': item.attrib['zone'], 'lot': lot.attrib['id'], 'expires': lot.attrib['expires'], 'quantity': qty, 'temperature_c': temp})
    return sorted(result, key=lambda x: (x['sku'], x['expires'], x['lot']))

def allocate_stock(records: list[dict], orders: list[dict]) -> list[dict]:
    required = {'sku', 'zone', 'lot', 'expires', 'quantity', 'temperature_c'}
    stock = {}
    for record in records:
        if set(record) != required or not isinstance(record['sku'], str) or (not isinstance(record['lot'], str)) or (not isinstance(record['expires'], str)) or (not isinstance(record['quantity'], int)) or isinstance(record['quantity'], bool) or (record['quantity'] < 0) or (not isinstance(record['temperature_c'], (int, float))) or isinstance(record['temperature_c'], bool) or (not math.isfinite(record['temperature_c'])):
