        for lot in item:
            if lot.tag != 'lot' or (lot.tail and lot.tail.strip()) or (lot.text and lot.text.strip()):
                raise ValueError('invalid lot')
            if set(lot.attrib) != {'id', 'expires', 'qty'}:
                raise ValueError('invalid lot')
            try:
