            if datetime.date.fromisoformat(record['expires']).isoformat() != record['expires']:
                raise ValueError
        except Exception as exc:
            raise ValueError('invalid date') from exc
        key = (record['sku'], record['lot'])
        if key in stock:
            raise ValueError('duplicate lot')
        stock[key] = record['quantity']
