import base64
import hashlib
import hmac
import math
import os

def _valid_pin(pin):
    return isinstance(pin, str) and 4 <= len(pin) <= 12 and pin.isdecimal() and pin.isascii()

def hash_pin(pin: str) -> str:
    if not _valid_pin(pin):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + ':' + digest.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not _valid_pin(pin) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = base64.b64decode(salt_text, validate=True)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def approve_refund(amount: int | float, pin: str, stored: str) -> bool:
    if isinstance(amount, bool) or not isinstance(amount, (int, float)):
        return False
    if not math.isfinite(amount) or amount <= 0 or amount > 10000:
        return False
    return verify_pin(pin, stored)

