    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    credential = 'pbkdf2$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(value).decode()
    return {'username': username, 'credential': credential}

def verify_moderator(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(record.get('username'), str) or (not record['username']) or (not isinstance(password, str)):
        return False
