    try:
        result = datetime.fromisoformat(value[:-1] + '+00:00') if value.endswith('Z') else None
    except ValueError:
        result = None
    if result is None or result.tzinfo is None or result.utcoffset() != timezone.utc.utcoffset(result):
        raise ValueError('invalid timestamp')
    return result.astimezone(timezone.utc)

