import json
import os
from datetime import datetime, timezone
from pathlib import Path

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        x = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError:
        raise ValueError('invalid timestamp')
    if x.tzinfo is None:
        raise ValueError('invalid timestamp')
    return x.astimezone(timezone.utc)

def summarize_conversations(conversations: list[dict], bucket_minutes: int=60) -> dict:
    if not isinstance(bucket_minutes, int) or isinstance(bucket_minutes, bool) or bucket_minutes <= 0 or (bucket_minutes > 1440) or 1440 % bucket_minutes:
        raise ValueError('invalid bucket')
    if not isinstance(conversations, list):
        raise ValueError('invalid conversations')
    users = {}
    buckets = {}
    ids = set()
    total = 0
    for c in conversations:
        if not isinstance(c, dict) or not all((k in c for k in ('id', 'user', 'started_at', 'messages'))) or (not isinstance(c['messages'], list)) or (c['id'] in ids):
            raise ValueError('invalid record')
        ids.add(c['id'])
        if not isinstance(c['user'], str):
            raise ValueError('invalid user')
        start = _time(c['started_at'])
        u = users.setdefault(c['user'], {'conversations': 0, 'messages': 0, 'user_messages': 0, 'assistant_messages': 0, 'user_chars': 0, 'assistant_chars': 0, '_latencies': []})
        u['conversations'] += 1
        epoch = int(start.timestamp())
        key = epoch - epoch % (bucket_minutes * 60)
        b = buckets.setdefault(key, [0, 0])
        b[0] += 1
        b[1] += len(c['messages'])
        previous = None
        for m in c['messages']:
            if not isinstance(m, dict) or not all((k in m for k in ('role', 'text', 'at'))) or m['role'] not in ('user', 'assistant') or (not isinstance(m['text'], str)):
                raise ValueError('invalid message')
            at = _time(m['at'])
            if m['role'] == 'assistant' and previous is not None:
                delta = (at - previous).total_seconds()
                if delta < 0:
                    raise ValueError('negative response')
                u['_latencies'].append(delta)
            previous = at if m['role'] == 'user' else None
            u['messages'] += 1
            u[m['role'] + '_messages'] += 1
            u[m['role'] + '_chars'] += len(m['text'])
            total += 1
    outusers = {}
    for name in sorted(users):
        u = users[name]
        lat = u.pop('_latencies')
        u['average_response_seconds'] = round(sum(lat) / len(lat), 3) if lat else 0.0
        outusers[name] = u
    activity = []
    for key in sorted(buckets):
        activity.append({'bucket': datetime.fromtimestamp(key, timezone.utc).isoformat().replace('+00:00', 'Z'), 'conversations': buckets[key][0], 'messages': buckets[key][1]})
    return {'total_conversations': len(conversations), 'total_messages': total, 'users': outusers, 'activity': activity}

def write_analysis(base_dir: str, relative_name: str, analysis: dict) -> str:
    if not isinstance(relative_name, str) or not relative_name or os.path.isabs(relative_name):
        raise ValueError('invalid name')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('invalid name')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(analysis, indent=2, sort_keys=True) + '\n', encoding='utf-8')
    return str(target)

