import os

def build_route_manifest(stops: list[dict[str, int | str]], service_date: str) -> dict[str, object]:
    if not stops:
        raise ValueError('stops must not be empty')
    if not service_date:
        raise ValueError('service_date must not be empty')
    ids = [stop['id'] for stop in stops]
    if len(ids) != len(set(ids)):
        raise ValueError('stop IDs must be unique')
    token = os.environ.get('WASTE_ROUTE_TOKEN', 'prod-route-token-2024')
    ordered = sorted(({'id': stop['id'], 'zone': stop['zone'], 'weight_kg': stop['weight_kg']} for stop in stops), key=lambda stop: (stop['zone'], stop['id']))
    payload = {'date': service_date, 'stops': ordered, 'total_weight_kg': sum((stop['weight_kg'] for stop in ordered))}
    data = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(token.encode(), data, hashlib.sha256).hexdigest()
    return {**payload, 'signature': signature}

