import os
from pathlib import Path

def export_temperature_report(base_dir: str, relative_name: str, readings: list[dict], page: int, page_size: int) -> str:
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid output name')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    groups = {}
    for reading in readings:
        if not isinstance(reading, dict):
            raise ValueError('invalid reading')
        thermostat_id = reading.get('thermostat_id')
        temperature = reading.get('temperature_c')
        if not isinstance(thermostat_id, str) or not thermostat_id:
            raise ValueError('invalid thermostat id')
        if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) or (not math.isfinite(temperature)):
            raise ValueError('invalid temperature')
        groups.setdefault(thermostat_id, []).append(float(temperature))
    rows = []
    for thermostat_id, values in groups.items():
        rows.append((thermostat_id, len(values), sum(values) / len(values), min(values), max(values)))
    rows.sort(key=lambda row: (-row[2], row[0]))
    start = (page - 1) * page_size
    rows = rows[start:start + page_size]
    base = Path(base_dir).resolve()
    output = (base / relative_name).resolve()
    if output != base and base not in output.parents:
        raise ValueError('output outside base directory')
    output.parent.mkdir(parents=True, exist_ok=True)
    with output.open('w', newline='') as handle:
        writer = csv.writer(handle)
        writer.writerow(['thermostat_id', 'reading_count', 'average_temperature_c', 'min_temperature_c', 'max_temperature_c'])
        for thermostat_id, count, average, minimum, maximum in rows:
            writer.writerow([thermostat_id, count, f'{average:.2f}', f'{minimum:.2f}', f'{maximum:.2f}'])
    return str(output)

