import csv
import datetime
import io
import math
import secrets
_ALPHABET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
_STATES = {'IDLE', 'RUNNING', 'FAULT', 'MAINTENANCE'}

def parse_status_log(text: str) -> list[dict]:
    rows = list(csv.reader(io.StringIO(text)))
    meaningful = [row for row in rows if any((field.strip() for field in row))]
    header = ['robot_id', 'timestamp', 'state', 'temperature', 'cycles']
    if not meaningful or meaningful[0] != header:
        raise ValueError('invalid header')
    result = []
    for row in meaningful[1:]:
        if len(row) != 5 or not row[0]:
            raise ValueError('invalid row')
        try:
            stamp = datetime.datetime.fromisoformat(row[1].replace('Z', '+00:00'))
            if not row[1].endswith('Z') or stamp.tzinfo is None:
                raise ValueError
            temperature = float(row[3])
            cycles = int(row[4])
        except (ValueError, OverflowError):
            raise ValueError('invalid value')
        if row[2] not in _STATES or not math.isfinite(temperature) or cycles < 0:
            raise ValueError('invalid value')
        result.append({'robot_id': row[0], 'timestamp': row[1], 'state': row[2], 'temperature': temperature, 'cycles': cycles})
    return result

def generate_maintenance_token(length: int=24) -> str:
    if length < 8 or length > 128:
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def summarize_robot(records: list[dict], robot_id: str, window: int=3) -> dict:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('invalid window')
    selected = [record for record in records if record.get('robot_id') == robot_id]
    if not selected:
        raise ValueError('unknown robot')
    selected = sorted(selected, key=lambda record: datetime.datetime.fromisoformat(record['timestamp'].replace('Z', '+00:00')))[-window:]
    return {'robot_id': robot_id, 'state': selected[-1]['state'], 'average_temperature': round(sum((x['temperature'] for x in selected)) / len(selected), 2), 'cycles_started': selected[0]['cycles'], 'cycles_finished': selected[-1]['cycles'], 'samples': len(selected)}

def issue_maintenance_ticket(records: list[dict], robot_id: str) -> dict:
    result = summarize_robot(records, robot_id, 3)
    result['ticket_id'] = generate_maintenance_token()
    return result

