import os
from pathlib import Path

def _validate_event(event):
    required = {'elevator', 'timestamp', 'floor', 'direction', 'door', 'load'}
    if not isinstance(event, dict) or set(event) != required:
        raise ValueError('invalid event')
    if not isinstance(event['elevator'], str) or not event['elevator']:
        raise ValueError('invalid event')
    if isinstance(event['timestamp'], bool) or not isinstance(event['timestamp'], int) or event['timestamp'] < 0:
        raise ValueError('invalid event')
    if isinstance(event['floor'], bool) or not isinstance(event['floor'], int):
        raise ValueError('invalid event')
    if event['direction'] not in {'up', 'down', 'idle'} or event['door'] not in {'open', 'closed'}:
        raise ValueError('invalid event')
    if isinstance(event['load'], bool) or not isinstance(event['load'], (int, float)) or (not math.isfinite(event['load'])) or (event['load'] < 0):
        raise ValueError('invalid event')

def summarize_elevator_events(events: list[dict]) -> dict[str, dict]:
    if not isinstance(events, list):
        raise ValueError('invalid events')
    groups = {}
    for index, event in enumerate(events):
        _validate_event(event)
        groups.setdefault(event['elevator'], []).append((event['timestamp'], index, event))
    result = {}
    for elevator in sorted(groups):
        ordered = [item[2] for item in sorted(groups[elevator], key=lambda x: (x[0], x[1]))]
        changes = sum((ordered[i]['direction'] != ordered[i - 1]['direction'] for i in range(1, len(ordered))))
        result[elevator] = {'event_count': len(ordered), 'first_timestamp': ordered[0]['timestamp'], 'last_timestamp': ordered[-1]['timestamp'], 'last_floor': ordered[-1]['floor'], 'max_load': max((e['load'] for e in ordered)), 'direction_changes': changes, 'door_open_events': sum((e['door'] == 'open' for e in ordered))}
    return result

def write_monitoring_report(base_dir: str, relative_name: str, events: list[dict]) -> str:
    if not isinstance(relative_name, str) or not relative_name or os.path.isabs(relative_name) or (not relative_name.endswith('.json')) or ('..' in Path(relative_name).parts):
        raise ValueError('invalid report name')
    summary = summarize_elevator_events(events)
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    if target != base and base not in target.parents:
        raise ValueError('invalid report name')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(summary, indent=2, sort_keys=True) + '\n', encoding='utf-8')
    return str(target)

