    for ride in rides:
        lift = ride['lift']
        if lift not in prices:
            raise ValueError('invalid lift')
        n = counts.get(ride['date'], 0)
        factor = 100 if n < 2 else 80 if n < 4 else 60
        total += prices[lift] * factor // 100
        counts[ride['date']] = n + 1
    return total

def make_lift_pass(holder: str, password: str, start_date: str, duration: int, rides: list[dict]) -> dict:
    if not isinstance(holder, str) or not holder.strip() or (not isinstance(password, str)) or (not password):
        raise ValueError('invalid text')
    start = _date(start_date)
    if not isinstance(duration, int) or isinstance(duration, bool) or (not 1 <= duration <= 14):
        raise ValueError('invalid duration')
    if not isinstance(rides, list):
        raise ValueError('invalid rides')
    copied = []
    end = start + datetime.timedelta(days=duration - 1)
    for ride in rides:
        if not isinstance(ride, dict) or set(ride) != {'date', 'lift'}:
            raise ValueError('invalid ride')
        day = _date(ride['date'])
        if not start <= day <= end or ride['lift'] not in {'A', 'B', 'C'}:
            raise ValueError('invalid ride')
        copied.append({'date': ride['date'], 'lift': ride['lift']})
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    credential = '100000$' + salt.hex() + '$' + digest.hex()
    return {'holder': holder, 'start_date': start_date, 'duration': duration, 'rides': copied, 'credential': credential, 'total_cents': _charge(copied)}

def verify_lift_pass(pass_record: dict, password: str) -> bool:
    if not isinstance(password, str):
        raise ValueError('invalid password')
    try:
        iterations, salt, expected = pass_record['credential'].split('$')
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt), int(iterations))
        return hmac.compare_digest(actual.hex(), expected)
    except (KeyError, AttributeError, TypeError, ValueError):
        return False

def sales_report(pass_records: list[dict]) -> list[dict]:
    grouped = {}
    for record in pass_records:
        if not isinstance(record, dict) or not isinstance(record.get('rides'), list):
            raise ValueError('invalid record')
        for ride in record['rides']:
            if not isinstance(ride, dict) or set(ride) != {'date', 'lift'}:
                raise ValueError('invalid ride')
            _date(ride['date'])
            if ride['lift'] not in {'A', 'B', 'C'}:
                raise ValueError('invalid lift')
            grouped.setdefault(ride['date'], []).append(ride)
    result = [{'date': day, 'rides': len(items), 'total_cents': _charge(items)} for day, items in grouped.items()]
    return sorted(result, key=lambda x: (-x['total_cents'], x['date']))

