import datetime
import hashlib
import hmac
import json
import os
from typing import Mapping

def ingest_meter_data(raw: str, config: Mapping[str, str], page: int=1, page_size: int=50) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1) or (page_size > 100):
        raise ValueError('invalid pagination arguments')
    try:
        document = json.loads(raw)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(document, dict) or not isinstance(document.get('readings'), list):
        raise ValueError('readings must be a list')
    grouped = {}
    for item in document['readings']:
        if not isinstance(item, dict):
            raise ValueError('invalid reading')
        meter = item.get('meter_id')
        timestamp = item.get('timestamp')
        value = item.get('kwh')
        if not isinstance(meter, str) or not meter or (not isinstance(timestamp, str)) or isinstance(value, bool) or (not isinstance(value, (int, float))) or (value < 0):
            raise ValueError('invalid reading')
        try:
            parsed = datetime.datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        if item.get('status', 'valid') != 'valid':
            continue
        key = (meter, parsed.date().isoformat())
        grouped[key] = grouped.get(key, 0) + value
    rows = [{'meter_id': meter, 'date': date, 'kwh': round(value, 3)} for (meter, date), value in sorted(grouped.items())]
    token = config.get('meter_api_token') or os.environ.get('SMART_METER_API_TOKEN')
    if not token:
        raise RuntimeError('meter API token is required')
    encoded = json.dumps(rows, separators=(',', ':'), sort_keys=True).encode()
    signature = hmac.new(token.encode(), encoded, hashlib.sha256).hexdigest()
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total': len(rows), 'readings': rows[start:start + page_size], 'signature': signature}

