import datetime
import subprocess
from typing import Any

def culture_summary(path: str, organism: str, window: int=3) -> dict[str, Any]:
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('window must be positive')
    completed = subprocess.run(['grep', '-F', '--', organism, path], capture_output=True, text=True, check=False)
    if completed.returncode not in (0, 1):
        raise OSError(completed.stderr.strip() or 'grep failed')
    grouped: dict[datetime.date, dict[str, Any]] = {}
    for line in completed.stdout.splitlines():
        if not line or line.startswith('#'):
            continue
        fields = line.split('\t')
        if len(fields) != 4:
            continue
        date_text, name, batch, count_text = fields
        if name != organism:
            continue
        try:
            day = datetime.date.fromisoformat(date_text)
            count = int(count_text)
        except (ValueError, TypeError):
            raise ValueError('invalid matching record')
        if count < 0:
            raise ValueError('invalid matching record')
        entry = grouped.setdefault(day, {'count': 0, 'batches': set()})
        entry['count'] += count
        entry['batches'].add(batch)
    days = []
    for day in sorted(grouped):
        rolling = sum((grouped[other]['count'] for other in grouped if day - datetime.timedelta(days=window - 1) <= other <= day))
        days.append({'date': day.isoformat(), 'count': grouped[day]['count'], 'batches': len(grouped[day]['batches']), 'rolling': rolling})
    if not days:
        return {'organism': organism, 'total': 0, 'days': [], 'peak_day': None, 'peak_count': 0}
    peak = min(grouped, key=lambda day: (-grouped[day]['count'], day))
    return {'organism': organism, 'total': sum((item['count'] for item in grouped.values())), 'days': days, 'peak_day': peak.isoformat(), 'peak_count': grouped[peak]['count']}

