_FIELDS = ('ticket_id', 'passenger', 'train', 'origin', 'destination', 'departure', 'seat', 'fare_cents')
_HEADER = ('ticket_id', 'passenger', 'train', 'origin', 'destination', 'departure', 'seat', 'fare')

def _validated(records):
    seen = set()
    result = []
    for record in records:
        if not isinstance(record, dict) or set(record) != set(_FIELDS):
            raise ValueError('invalid reservation')
        copy = dict(record)
        if any((not isinstance(copy[k], str) or not copy[k] for k in _FIELDS[:6])):
            raise ValueError('invalid text field')
        try:
            stamp = datetime.datetime.strptime(copy['departure'], '%Y-%m-%d %H:%M')
        except (TypeError, ValueError):
            raise ValueError('invalid departure')
        if isinstance(copy['seat'], bool) or not isinstance(copy['seat'], int) or copy['seat'] <= 0:
            raise ValueError('invalid seat')
        if isinstance(copy['fare_cents'], bool) or not isinstance(copy['fare_cents'], int) or copy['fare_cents'] < 0:
            raise ValueError('invalid fare')
        if copy['ticket_id'] in seen:
            raise ValueError('duplicate ticket')
        seen.add(copy['ticket_id'])
        result.append((stamp, copy))
    result.sort(key=lambda pair: (pair[0], pair[1]['train'], pair[1]['origin'], pair[1]['destination'], pair[1]['passenger'], pair[1]['ticket_id']))
    return [item for _, item in result]

def prepare_reservations(records: list[dict]) -> list[dict]:
    return _validated(records)

def ticket_totals(records: list[dict]) -> dict[str, int]:
    rows = _validated(records)
    totals = {}
    for row in rows:
        totals[row['passenger']] = totals.get(row['passenger'], 0) + row['fare_cents']
    return {name: totals[name] for name in sorted(totals)}

def export_tickets(records: list[dict], destination: str) -> int:
    rows = _validated(records)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='railway_', suffix='.csv', dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(_HEADER)
            for row in rows:
                writer.writerow([row['ticket_id'], row['passenger'], row['train'], row['origin'], row['destination'], row['departure'], row['seat'], f"{row['fare_cents'] / 100:.2f}"])
        os.replace(temporary, destination)
    except Exception:
        if os.path.exists(temporary):
            os.unlink(temporary)
        raise
    return len(rows)

