import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise NameError(node.id)
        return names[node.id]
    if isinstance(node, ast.BinOp):
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        if type(node.op) not in ops:
            raise ValueError('unsupported expression')
        return ops[type(node.op)](_value(node.left, names), _value(node.right, names))
    if isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.USub):
            return -_value(node.operand, names)
        if isinstance(node.op, ast.UAdd):
            return +_value(node.operand, names)
        if isinstance(node.op, ast.Not):
            return not _value(node.operand, names)
        raise ValueError('unsupported expression')
    if isinstance(node, ast.BoolOp):
        result = _value(node.values[0], names)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _value(child, names)
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        checks = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
        for op, child in zip(node.ops, node.comparators):
            if type(op) not in checks:
                raise ValueError('unsupported expression')
            right = _value(child, names)
            if not checks[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_value(x, names) for x in node.args])
    raise ValueError('unsupported expression')

def rank_jobs(jobs: list[dict[str, float]], expression: str, minimum_score: float=0.0) -> list[str]:
    if not expression.strip():
        raise ValueError('empty expression')
    try:
        tree = ast.parse(expression, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc
    scored = []
    for index, job in enumerate(jobs):
        score = _value(tree, job)
        if score >= minimum_score:
            scored.append((score, index, job['id']))
    scored.sort(key=lambda item: (-item[0], item[1]))
    return [item[2] for item in scored]

