    clauses = []
    if destination:
        clauses.append("destination LIKE '%" + destination + "%' COLLATE NOCASE")
    if max_price is not None:
        clauses.append('price_cents <= ?')
        params.append(round(max_price * 100))
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    offset = (page - 1) * page_size
    query = 'SELECT id, title, destination, start_date, nights, price_cents FROM itineraries' + where + ' ORDER BY ' + columns[sort_by] + ' ASC, id ASC LIMIT ? OFFSET ?'
