import sqlite3
from typing import Iterable

def build_pension_report(conn: sqlite3.Connection, employee_ids: Iterable[int], year: int, sort_by: str='employee_id', descending: bool=False, limit: int=50, offset: int=0) -> list[dict]:
    if not isinstance(year, int) or isinstance(year, bool) or (not 2000 <= year <= 2100):
        raise ValueError('invalid year')
    if sort_by not in {'employee_id', 'name', 'salary', 'employee_contribution', 'employer_contribution', 'total_contribution'}:
        raise ValueError('invalid sort column')
    if not isinstance(limit, int) or isinstance(limit, bool) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    ids = []
    for value in employee_ids:
        if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
            raise ValueError('invalid employee id')
        if value not in ids:
            ids.append(value)
    if not ids:
        return []
    placeholders = ','.join(('?' for _ in ids))
    start = f'{year:04d}-01-01'
    end = f'{year + 1:04d}-01-01'
    columns = {'employee_id': 'e.id', 'name': 'e.name', 'salary': 'e.salary', 'employee_contribution': 'employee_contribution', 'employer_contribution': 'employer_contribution', 'total_contribution': 'total_contribution'}
    direction = 'DESC' if descending else 'ASC'
    query = f'SELECT e.id, e.name, e.salary, COALESCE(SUM(CASE WHEN c.contribution_date >= ? AND c.contribution_date < ? THEN c.employee_amount ELSE 0 END), 0), COALESCE(SUM(CASE WHEN c.contribution_date >= ? AND c.contribution_date < ? THEN c.employer_amount ELSE 0 END), 0) FROM employees e LEFT JOIN contributions c ON c.employee_id = e.id WHERE e.id IN ({placeholders}) GROUP BY e.id, e.name, e.salary ORDER BY {columns[sort_by]} {direction}, e.id ASC LIMIT ? OFFSET ?'
    params = [start, end, start, end, *ids, limit, offset]
    result = []
    for employee_id, name, salary, employee_amount, employer_amount in conn.execute(query, params):
        employee_amount = round(employee_amount, 2)
        employer_amount = round(employer_amount, 2)
        result.append({'employee_id': employee_id, 'name': name, 'salary': round(salary, 2), 'employee_contribution': employee_amount, 'employer_contribution': employer_amount, 'total_contribution': round(employee_amount + employer_amount, 2)})
    return result

