from solution import end_session


def test_owner_can_end_active_session():
    requester = {"user_id": "u1", "tenant_id": "t1", "roles": ["player"]}
    session = {"session_id": "s1", "user_id": "u1", "tenant_id": "t1", "status": "active", "started_at": 123}
    result = end_session(requester, session)
    assert result == {"session_id": "s1", "user_id": "u1", "tenant_id": "t1", "status": "ended", "started_at": 123, "ended_by": "u1", "end_reason": "logout"}
    assert session["status"] == "active"


