        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left = _evaluate(node.left, names)
        right = _evaluate(node.right, names)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        return left / right
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        values = [_evaluate(value, names) for value in node.values]
        if isinstance(node.op, ast.And):
            result = values[0]
            for value in values[1:]:
                result = value if result else result
            return result
        result = values[0]
        for value in values[1:]:
            result = result if result else value
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, names)
        for operation, comparator in zip(node.ops, node.comparators):
            right = _evaluate(comparator, names)
            if isinstance(operation, ast.Lt):
                ok = left < right
            elif isinstance(operation, ast.LtE):
                ok = left <= right
            elif isinstance(operation, ast.Gt):
                ok = left > right
            elif isinstance(operation, ast.GtE):
                ok = left >= right
