import hashlib
import hmac
import os
import math

class VehicleFleet:

    def __init__(self):
        self._users = {}
        self._frames = {}

    def enroll(self, vehicle_id: str, pin: str) -> None:
        if not isinstance(vehicle_id, str) or not vehicle_id or any((c.isspace() for c in vehicle_id)) or ('|' in vehicle_id):
            raise ValueError('invalid vehicle')
        if not isinstance(pin, str) or not pin.isascii() or (not pin.isdigit()) or (not 4 <= len(pin) <= 12):
            raise ValueError('invalid pin')
        if vehicle_id in self._users:
            raise ValueError('duplicate vehicle')
        salt = os.urandom(16)
        digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        self._users[vehicle_id] = (salt, digest)
        self._frames[vehicle_id] = {}

    def authenticate(self, vehicle_id: str, pin: str) -> bool:
        record = self._users.get(vehicle_id)
        if record is None or not isinstance(pin, str):
            return False
        salt, expected = record
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)

    def add_frame(self, vehicle_id: str, pin: str, frame: str) -> None:
        if not self.authenticate(vehicle_id, pin):
            raise PermissionError('authentication failed')
        parts = frame.split('|')
        if len(parts) != 4 or parts[0] != vehicle_id:
            raise ValueError('invalid frame')
        try:
            timestamp = int(parts[1])
            speed = float(parts[2])
            battery = int(parts[3])
        except (TypeError, ValueError):
            raise ValueError('invalid frame')
        if not math.isfinite(speed) or not 0 <= battery <= 100:
            raise ValueError('invalid frame')
        self._frames[vehicle_id][timestamp] = (speed, battery)

    def report(self, vehicle_id: str, pin: str, start: int, end: int) -> dict:
        if not self.authenticate(vehicle_id, pin):
            raise PermissionError('authentication failed')
        if not isinstance(start, int) or not isinstance(end, int) or start > end:
            raise ValueError('invalid bounds')
        selected = [(t, *self._frames[vehicle_id][t]) for t in sorted(self._frames[vehicle_id]) if start <= t < end]
        samples = [{'timestamp': t, 'speed': s, 'battery': b} for t, s, b in selected]
        if not selected:
            return {'count': 0, 'average_speed': None, 'max_speed': None, 'minimum_battery': None, 'samples': []}
        speeds = [x[1] for x in selected]
        batteries = [x[2] for x in selected]
        return {'count': len(selected), 'average_speed': sum(speeds) / len(speeds), 'max_speed': max(speeds), 'minimum_battery': min(batteries), 'samples': samples}

