import subprocess
from datetime import date, timedelta
import os

def read_case_events(path: str) -> list[dict]:
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    try:
        result = subprocess.run(['sort', '-t,', '-k4,4', '-k1,1', path], capture_output=True, text=True, check=True)
    except (subprocess.CalledProcessError, OSError) as exc:
        raise FileNotFoundError(path) from exc
    events = []
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = [x.strip() for x in raw.split(',')]
        if len(fields) != 5 or fields[2] not in {'OPEN', 'REVIEW', 'CLOSED'}:
            raise ValueError('invalid event')
        try:
            day = date.fromisoformat(fields[3])
            hours = float(fields[4])
        except (ValueError, TypeError):
            raise ValueError('invalid event')
        if len(fields[3]) != 10 or hours < 0:
            raise ValueError('invalid event')
        events.append({'case_id': fields[0], 'worker': fields[1], 'status': fields[2], 'event_date': day, 'hours': hours})
    return events

def summarize_case_workload(path: str, as_of: str) -> dict:
    try:
        cutoff = date.fromisoformat(as_of)
    except ValueError:
        raise ValueError('invalid date')
    latest = {}
    for event in read_case_events(path):
        if event['event_date'] <= cutoff:
            latest[event['case_id']] = event
    counts = {'OPEN': 0, 'REVIEW': 0, 'CLOSED': 0}
    workers = {}
    overdue = []
    for case_id, event in latest.items():
        counts[event['status']] += 1
        workers[event['worker']] = workers.get(event['worker'], 0.0) + event['hours']
        if event['status'] in {'OPEN', 'REVIEW'} and event['event_date'] < cutoff - timedelta(days=30):
            overdue.append(case_id)
    return {'as_of': cutoff, 'total_cases': len(latest), 'by_status': counts, 'hours_by_worker': dict(sorted(workers.items())), 'overdue_case_ids': sorted(overdue)}

