import csv
import os
import tempfile
from datetime import datetime

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value[:-1] + '+00:00')
    except ValueError:
        raise ValueError('invalid timestamp')

def summarize_payouts(records: list[dict], cutoff: str) -> list[dict]:
    limit = _time(cutoff)
    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = ('seller_id', 'order_id', 'status', 'gross_cents', 'fee_cents', 'occurred_at')
        if any((key not in record for key in required)):
            raise ValueError('invalid record')
        if not all((isinstance(record[k], str) for k in ('seller_id', 'order_id', 'status', 'occurred_at'))):
            raise ValueError('invalid record')
        if type(record['gross_cents']) is not int or type(record['fee_cents']) is not int:
            raise ValueError('invalid amount')
        if record['gross_cents'] < 0 or record['fee_cents'] < 0 or record['status'] not in ('pending', 'settled', 'reversed'):
            raise ValueError('invalid record')
        when = _time(record['occurred_at'])
        if when > limit or record['status'] == 'pending':
            continue
        sign = 1 if record['status'] == 'settled' else -1
        seller = record['seller_id']
        if seller not in totals:
            totals[seller] = [0, 0, 0]
        totals[seller][0] += sign * record['gross_cents']
        totals[seller][1] += sign * record['fee_cents']
        totals[seller][2] += 1
    result = [{'seller_id': s, 'gross_cents': v[0], 'fee_cents': v[1], 'net_cents': v[0] - v[1], 'transaction_count': v[2]} for s, v in totals.items()]
    return sorted(result, key=lambda x: (-x['net_cents'], x['seller_id']))

def export_payouts(records: list[dict], cutoff: str, destination: str) -> int:
    rows = summarize_payouts(records, cutoff)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.payouts-', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.DictWriter(stream, fieldnames=['seller_id', 'gross_cents', 'fee_cents', 'net_cents', 'transaction_count'])
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(rows)

