def read_case_packet(base_dir: str, relative_name: str) -> dict:
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, relative_name))
    try:
        inside = os.path.commonpath([base, candidate]) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('path is outside base directory')
    try:
        with open(candidate, 'r', encoding='utf-8') as handle:
            data = json.load(handle)
    except json.JSONDecodeError as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict):
        raise ValueError('packet must be an object')
    required = {'case_id', 'claimant', 'issues', 'estimated_hours', 'deadlines'}
    if set(data) != required:
        raise ValueError('invalid packet fields')
    if not isinstance(data['case_id'], str) or not data['case_id']:
        raise ValueError('invalid case id')
    if not isinstance(data['claimant'], str) or not data['claimant']:
        raise ValueError('invalid claimant')
    if not isinstance(data['issues'], list) or any((not isinstance(x, str) or not x for x in data['issues'])):
        raise ValueError('invalid issues')
    if isinstance(data['estimated_hours'], bool) or not isinstance(data['estimated_hours'], (int, float)) or data['estimated_hours'] < 0:
        raise ValueError('invalid hours')
    deadlines = []
    for value in data['deadlines']:
        if not isinstance(value, str):
            raise ValueError('invalid deadline')
        try:
            date.fromisoformat(value)
        except ValueError as exc:
            raise ValueError('invalid deadline') from exc
        deadlines.append(value)
    return {'case_id': data['case_id'], 'claimant': data['claimant'], 'issues': sorted(set(data['issues'])), 'estimated_hours': float(data['estimated_hours']), 'deadlines': sorted(deadlines)}

def assign_cases(cases: list[dict], attorneys: list[dict], capacity_limit: float=40.0) -> dict:
    if isinstance(capacity_limit, bool) or not isinstance(capacity_limit, (int, float)) or capacity_limit < 0:
        raise ValueError('invalid limit')
    seen_cases = set()
    normalized = []
    for item in cases:
        try:
            cid, priority, deadline, hours, specialty = (item[x] for x in ('case_id', 'priority', 'deadline', 'estimated_hours', 'required_specialty'))
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid case') from exc
        if not isinstance(cid, str) or not cid or cid in seen_cases or (not isinstance(priority, int)) or isinstance(priority, bool) or (not isinstance(specialty, str)) or (not specialty) or isinstance(hours, bool) or (not isinstance(hours, (int, float))) or (hours < 0):
            raise ValueError('invalid case')
        try:
            date.fromisoformat(deadline)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid case') from exc
        seen_cases.add(cid)
        normalized.append((cid, priority, deadline, float(hours), specialty))
    result = {'assignments': {}, 'hours': {}, 'unassigned': []}
    records = {}
    for attorney in attorneys:
        try:
            aid, specialties, capacity = (attorney['attorney_id'], attorney['specialties'], attorney['capacity'])
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid attorney') from exc
        if not isinstance(aid, str) or not aid or aid in records or (not isinstance(specialties, list)) or any((not isinstance(x, str) or not x for x in specialties)) or isinstance(capacity, bool) or (not isinstance(capacity, (int, float))) or (capacity < 0):
            raise ValueError('invalid attorney')
        records[aid] = (set(specialties), float(capacity), [])
        result['assignments'][aid] = []
        result['hours'][aid] = 0.0
    for cid, priority, deadline, hours, specialty in sorted(normalized, key=lambda x: (-x[1], x[2], x[0])):
        eligible = [(result['hours'][aid], aid) for aid, (skills, cap, _) in records.items() if specialty in skills and result['hours'][aid] + hours <= cap and (result['hours'][aid] + hours <= float(capacity_limit))]
        if not eligible:
            result['unassigned'].append(cid)
            continue
        _, aid = min(eligible)
        result['assignments'][aid].append(cid)
        result['hours'][aid] += hours
    return result

