import re

def _time(value):
    if not isinstance(value, str) or not re.fullmatch('\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(?:\\.\\d+)?(?:Z|[+-]\\d\\d:\\d\\d)', value):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc

def schedule_interview(requester, candidates, interviews, candidate_id, start, end):
    if candidate_id not in candidates:
        raise KeyError(candidate_id)
    candidate = candidates[candidate_id]
    if not candidate.get('active', False):
        raise ValueError('inactive candidate')
    a, b = (_time(start), _time(end))
    if a.tzinfo is None or b.tzinfo is None:
        raise ValueError('timezone required')
    if b <= a or (b - a).total_seconds() < 900 or (b - a).total_seconds() > 28800:
        raise ValueError('invalid duration')
    if candidate.get('tenant') != requester.get('tenant'):
        raise ValueError('tenant mismatch')
    for old in interviews:
        if old.get('candidate_id') == candidate_id and old.get('status') == 'scheduled':
            if a < _time(old['end']) and b > _time(old['start']):
                raise ValueError('overlap')
    nums = [int(m.group(1)) for x in interviews if (m := re.fullmatch('iv-(\\d+)', str(x.get('id'))))]
    record = {'id': 'iv-' + str(max(nums, default=0) + 1), 'tenant': candidate['tenant'], 'candidate_id': candidate_id, 'organizer_id': requester['id'], 'start': start, 'end': end, 'status': 'scheduled', 'notes': ''}
    interviews.append(record)
    return record

def cancel_interview(requester, interviews, interview_id):
    for item in interviews:
        if item.get('id') == interview_id:
            if item.get('status') == 'cancelled':
                raise ValueError('already cancelled')
            allowed = item.get('tenant') == requester.get('tenant') and (item.get('organizer_id') == requester.get('id') or requester.get('role') == 'admin')
            if not allowed:
                raise PermissionError('not permitted')
            item['status'] = 'cancelled'
            return item
    raise KeyError(interview_id)

def daily_agenda(requester, interviews, day):
    try:
        target = datetime.strptime(day, '%Y-%m-%d').date()
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid day') from exc
    result = [dict(x) for x in interviews if x.get('status') == 'scheduled' and x.get('tenant') == requester.get('tenant') and (_time(x['start']).astimezone(timezone.utc).date() == target)]
    result.sort(key=lambda x: (_time(x['start']), x['candidate_id'], x['id']))
    return result

