import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_pin(stored: str, pin: str) -> bool:
    if not isinstance(stored, str) or not isinstance(pin, str) or (not pin):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_access(events: list[dict], zone: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    groups = {}
    for event in events:
        if zone is not None and event['zone'] != zone:
            continue
        name = event['zone']
        if name not in groups:
            groups[name] = {'zone': name, 'granted': 0, 'denied': 0}
        groups[name]['granted' if event['granted'] else 'denied'] += 1
    result = sorted(groups.values(), key=lambda item: (-item['granted'], item['zone']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

