def fetch_reviews(conn: sqlite3.Connection, product_id: int, search: str='', min_rating: int=1, sort_by: str='helpful', descending: bool=True) -> list[dict]:
    if not isinstance(min_rating, int) or isinstance(min_rating, bool) or (not 1 <= min_rating <= 5):
        raise ValueError('min_rating must be from 1 through 5')
    if not isinstance(descending, bool):
        raise TypeError('descending must be a boolean')
    columns = {'helpful': 'helpful', 'rating': 'rating', 'created_at': 'created_at', 'id': 'id'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    direction = 'DESC' if descending else 'ASC'
    sql = f'SELECT id, reviewer, rating, body, status, helpful, created_at FROM reviews WHERE product_id = ? AND rating >= ? AND (lower(reviewer) LIKE lower(?) OR lower(body) LIKE lower(?)) ORDER BY {columns[sort_by]} {direction}, id ASC'
    pattern = '%' + search + '%'
    rows = conn.execute(sql, (product_id, min_rating, pattern, pattern)).fetchall()
    names = ['id', 'reviewer', 'rating', 'body', 'status', 'helpful', 'created_at']
    return [dict(zip(names, row)) for row in rows]

def set_review_status(conn: sqlite3.Connection, review_id: int, status: str, moderator: str) -> None:
    if status not in {'pending', 'approved', 'rejected'}:
        raise ValueError('invalid status')
    if not isinstance(moderator, str) or not moderator.strip():
        raise ValueError('moderator is required')
    cur = conn.execute('UPDATE reviews SET status = ?, moderated_by = ? WHERE id = ?', (status, moderator.strip(), review_id))
    if cur.rowcount == 0:
        raise KeyError(review_id)
    conn.commit()

def rating_summary(conn: sqlite3.Connection, product_id: int) -> dict:
    rows = conn.execute("SELECT rating FROM reviews WHERE product_id = ? AND status = 'approved'", (product_id,)).fetchall()
    pending = conn.execute("SELECT COUNT(*) FROM reviews WHERE product_id = ? AND status = 'pending'", (product_id,)).fetchone()[0]
    distribution = {rating: 0 for rating in range(1, 6)}
    for rating, in rows:
        distribution[rating] += 1
    total = len(rows)
    average = round(sum((row[0] for row in rows)) / total, 2) if total else None
    return {'total': total, 'average': average, 'distribution': distribution, 'pending': pending}

