import hashlib
import hmac

def verify_backup_manifest(manifest: str, secret: str) -> dict | bool:
    fields = manifest.split('|')
    if len(fields) != 4:
        raise ValueError('invalid manifest')
    backup_id, size_text, checksum, signature = fields
    if not backup_id or any((ch.isspace() for ch in backup_id)):
        raise ValueError('invalid backup id')
    if not size_text.isdecimal():
        raise ValueError('invalid size')
    if not checksum or len(checksum) != 64 or any((ch not in '0123456789abcdef' for ch in checksum)):
        raise ValueError('invalid checksum')
    if len(signature) != 64 or any((ch not in '0123456789abcdef' for ch in signature)):
        raise ValueError('invalid signature')
    payload = '|'.join(fields[:3]).encode()
    expected = hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return False
    return {'backup_id': backup_id, 'size': int(size_text), 'checksum': checksum}

