import os

def save_attendance_record(base_dir: str, relative_name: str, student_id: str, attendance_date: str, present: bool) -> str:
    if not relative_name or os.path.isabs(relative_name):
        raise ValueError('invalid relative name')
    base_path = os.path.realpath(base_dir)
    requested_path = os.path.realpath(os.path.join(base_path, relative_name))
    try:
        inside = os.path.commonpath([base_path, requested_path]) == base_path
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('invalid relative name')
    os.makedirs(os.path.dirname(requested_path), exist_ok=True)
    status = 'Present' if present else 'Absent'
    with open(requested_path, 'w', encoding='utf-8') as handle:
        handle.write(f'{attendance_date},{student_id},{status}\n')
    return os.path.join(base_dir, relative_name)

import base64
import datetime
import hashlib
import hmac
import math
import os

def register_account(username: str, password: str) -> dict:
    if not isinstance(username, str) or not username.strip():
        raise ValueError('invalid username')
    if not isinstance(password, str) or len(password) < 8:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username.strip(), 'password_hash': base64.b64encode(digest).decode(), 'password_salt': base64.b64encode(salt).decode()}

def verify_account(account: dict, password: str) -> bool:
    try:
        if not isinstance(account, dict) or set(account) != {'username', 'password_hash', 'password_salt'} or (not isinstance(password, str)):
            return False
        salt = base64.b64decode(account['password_salt'].encode(), validate=True)
        expected = base64.b64decode(account['password_hash'].encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except Exception:
        return False

def summarize_emissions(events: list[dict], start: str, end: str) -> list[dict]:
    try:
        lo = datetime.date.fromisoformat(start)
        hi = datetime.date.fromisoformat(end)
    except Exception as exc:
        raise ValueError('invalid range') from exc
    if start != lo.isoformat() or end != hi.isoformat() or lo > hi:
        raise ValueError('invalid range')
    checked = []
    for pos, event in enumerate(events):
        if not isinstance(event, dict) or set(event) != {'date', 'scope', 'category', 'kg'}:
            raise ValueError('invalid event')
        try:
            day = datetime.date.fromisoformat(event['date'])
        except Exception as exc:
            raise ValueError('invalid event') from exc
        kg = event['kg']
        if event['date'] != day.isoformat() or not isinstance(event['scope'], int) or isinstance(event['scope'], bool) or (event['scope'] not in (1, 2, 3)) or (not isinstance(event['category'], str)) or (not event['category']) or (not isinstance(kg, (int, float))) or isinstance(kg, bool) or (not math.isfinite(kg)) or (kg < 0):
            raise ValueError('invalid event')
        if lo <= day <= hi:
            checked.append((day, event['scope'], event['category'], kg, pos))
    groups = {}
    for day, scope, category, kg, pos in sorted(checked, key=lambda x: (x[0], x[1], x[2], x[4])):
        key = (day.strftime('%Y-%m'), scope)
        total, cats = groups.setdefault(key, (0, {}))
        cats[category] = cats.get(category, 0) + kg
        groups[key] = (total + kg, cats)
    return [{'month': month, 'scope': scope, 'total_kg': groups[month, scope][0], 'categories': dict(sorted(groups[month, scope][1].items()))} for month, scope in sorted(groups)]

