import os
import zipfile

def extract_permit_archive(archive_path: str, base_dir: str) -> list[str]:
    base = os.path.abspath(os.path.realpath(base_dir))
    os.makedirs(base, exist_ok=True)
    names = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename
            if not name:
                raise ValueError('empty archive member')
            target = os.path.abspath(os.path.realpath(os.path.join(base, name)))
            try:
                common = os.path.commonpath([base, target])
            except ValueError:
                raise ValueError('invalid archive member')
            if common != base:
                raise ValueError('invalid archive member')
            if name.endswith('/'):
                os.makedirs(target, exist_ok=True)
                continue
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as dest:
                while True:
                    chunk = source.read(65536)
                    if not chunk:
                        break
                    dest.write(chunk)
            names.append(name)
    return sorted(names)

def parse_permit_record(line: str) -> dict[str, object]:
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 4:
        raise ValueError('wrong field count')
    permit_id, zone, vehicle, hours_text = fields
    permit_id, zone, vehicle = (permit_id.strip(), zone.strip(), vehicle.strip())
    if not permit_id or not zone or (not vehicle):
        raise ValueError('empty field')
    if not permit_id[0].isalpha() or not all(('A' <= c <= 'Z' or 'a' <= c <= 'z' or '0' <= c <= '9' or (c == '-') for c in permit_id)):
        raise ValueError('invalid permit id')
    if not hours_text.isdigit():
        raise ValueError('invalid hours')
    hours = int(hours_text)
    if hours > 24:
        raise ValueError('invalid hours')
    return {'permit_id': permit_id, 'zone': zone, 'vehicle': vehicle, 'hours': hours}

def summarize_permit_hours(lines: list[str]) -> list[dict[str, object]]:
    groups = {}
    for line in lines:
        record = parse_permit_record(line)
        zone = record['zone']
        if zone not in groups:
            groups[zone] = {'zone': zone, 'permits': 0, 'hours': 0, 'vehicles': set()}
        groups[zone]['permits'] += 1
        groups[zone]['hours'] += record['hours']
        groups[zone]['vehicles'].add(record['vehicle'])
    result = []
    for item in groups.values():
        item = dict(item)
        item['vehicles'] = sorted(item['vehicles'])
        result.append(item)
    return sorted(result, key=lambda x: (-x['hours'], -x['permits'], x['zone']))

