import datetime
import hashlib
import hmac
import json

def index_metadata(documents: list[dict], signature: str, signing_key: str, page: int, page_size: int) -> dict:
    payload = json.dumps(documents, sort_keys=True, separators=(',', ':'), ensure_ascii=True).encode('utf-8')
    expected = hmac.new(signing_key.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)) or (not hmac.compare_digest(signature, expected)):
        raise PermissionError('invalid signature')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    seen = set()
    records = []
    counts = {}
    total_size = 0
    for document in documents:
        if set(document) != {'id', 'title', 'tags', 'updated_at', 'size'}:
            raise ValueError('invalid document')
        identifier = document['id']
        title = document['title']
        tags = document['tags']
        date = document['updated_at']
        size = document['size']
        if not isinstance(identifier, str) or not identifier or (not isinstance(title, str)) or (not title):
            raise ValueError('invalid document')
        if not isinstance(tags, list) or any((not isinstance(tag, str) or not tag for tag in tags)) or len(set(tags)) != len(tags):
            raise ValueError('invalid document')
        if not isinstance(date, str) or len(date) != 10 or date[4] != '-' or (date[7] != '-'):
            raise ValueError('invalid document')
        try:
            datetime.date.fromisoformat(date)
        except ValueError:
            raise ValueError('invalid document')
        if isinstance(size, bool) or not isinstance(size, int) or size < 0 or (identifier in seen):
            raise ValueError('invalid document')
        seen.add(identifier)
        normalized_tags = sorted(tags)
        records.append({'id': identifier, 'title': title, 'tags': normalized_tags, 'updated_at': date, 'size': size})
        total_size += size
        for tag in tags:
            counts[tag] = counts.get(tag, 0) + 1
    records.sort(key=lambda item: (-int(item['updated_at'].replace('-', '')), item['id']))
    start = (page - 1) * page_size
    total = len(records)
    return {'items': records[start:start + page_size], 'page': page, 'page_size': page_size, 'total': total, 'total_pages': (total + page_size - 1) // page_size if total else 0, 'total_size': total_size, 'tag_counts': {tag: counts[tag] for tag in sorted(counts)}}

