import re

def parse_delivery_window(value: str) -> tuple[int, int]:
    if not isinstance(value, str):
        raise ValueError('invalid window')
    m = re.fullmatch('\\s*(\\d{2}):(\\d{2})-(\\d{2}):(\\d{2})\\s*', value)
    if not m:
        raise ValueError('invalid window')
    h1, m1, h2, m2 = map(int, m.groups())
    if h1 > 23 or h2 > 23 or m1 > 59 or (m2 > 59):
        raise ValueError('invalid window')
    start, end = (h1 * 60 + m1, h2 * 60 + m2)
    if end <= start:
        raise ValueError('invalid window')
    return (start, end)

def dispatch_orders(requester: dict, orders: list[dict], couriers: list[dict], at_minute: int) -> list[dict]:
    ids = [o['id'] for o in orders]
    if len(ids) != len(set(ids)):
        raise ValueError('duplicate order id')
    allowed = set(requester.get('tenant_ids', []))
    dispatcher = 'dispatcher' in requester.get('roles', [])
    parsed = []
    for order in orders:
        window = parse_delivery_window(order['delivery_window'])
        if window[0] >= at_minute and window[0] <= at_minute + 120:
            if dispatcher and order['tenant_id'] in allowed or order['restaurant_owner_id'] == requester.get('user_id'):
                parsed.append((order, window))
    parsed.sort(key=lambda x: (-x[0]['priority'], x[1][0], x[0]['id']))
    loads = {c['id']: c['assigned_count'] for c in couriers}
    result = []
    for order, window in parsed:
        candidates = []
        needed = set(order['required_skills'])
        for c in couriers:
            if c['tenant_id'] != order['tenant_id'] or c['available_from'] > at_minute:
                continue
            if loads[c['id']] >= c['capacity'] or not needed.issubset(set(c['skills'])):
                continue
            distance = abs(c['zone'] - order['zone'])
            candidates.append((distance, loads[c['id']], c['id'], c))
        if candidates:
            distance, _, cid, _ = min(candidates)
            loads[cid] += 1
            result.append({'order_id': order['id'], 'courier_id': cid, 'eta': at_minute + distance + 10, 'window': window})
    return result

