import datetime
import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_shifts(shifts: list[dict], week_start: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        begin = datetime.datetime.strptime(week_start, '%Y-%m-%d')
    except (TypeError, ValueError):
        raise ValueError('invalid week')
    finish = begin + datetime.timedelta(days=7)
    totals = {}
    for item in shifts:
        if not isinstance(item, dict) or not isinstance(item.get('employee'), str) or (not item['employee']):
            raise ValueError('invalid shift')
        try:
            start = datetime.datetime.fromisoformat(item['start'])
            end = datetime.datetime.fromisoformat(item['end'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid shift')
        if end <= start:
            raise ValueError('invalid shift')
        left, right = (max(start, begin), min(end, finish))
        if left < right:
            name = item['employee']
            entry = totals.setdefault(name, [0.0, 0])
            entry[0] += (right - left).total_seconds() / 3600
            entry[1] += 1
    result = [{'employee': name, 'hours': round(values[0], 2), 'shifts': values[1]} for name, values in totals.items()]
    result.sort(key=lambda x: (-x['hours'], x['employee']))
    start_index = (page - 1) * page_size
    return result[start_index:start_index + page_size]

