def adoption_page(path: str, species: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if species == '':
        raise ValueError('invalid species')
    with open(path, 'r', encoding='utf-8') as f:
        header = f.readline().rstrip('\n\r')
    expected = 'animal_id,name,species,age,adopted_days'
    if header != expected:
        raise ValueError('invalid header')
    completed = subprocess.run(['sort', '-t,', '-k5,5n', '-k1,1', path], capture_output=True, text=True, check=True)
    records = []
    for row in csv.reader(completed.stdout.splitlines()):
        if row == ['animal_id', 'name', 'species', 'age', 'adopted_days']:
            continue
        if len(row) != 5 or not row[0] or (not row[1]) or (not row[2]):
            raise ValueError('invalid row')
        try:
            age = int(row[3])
            adopted_days = int(row[4])
        except ValueError as exc:
            raise ValueError('invalid numeric field') from exc
        if age < 0 or adopted_days < 0:
            raise ValueError('negative numeric field')
        if species is None or row[2] == species:
            records.append({'animal_id': row[0], 'name': row[1], 'species': row[2], 'age': age, 'adopted_days': adopted_days})
    total = len(records)
    start = (page - 1) * page_size
    selected = records[start:start + page_size]
    average = round(sum((item['age'] for item in records)) / total, 2) if total else 0.0
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': math.ceil(total / page_size) if total else 0, 'records': selected, 'average_age': average}

