import math
import secrets
from decimal import Decimal, ROUND_HALF_UP

def generate_invite_code(length: int=8) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or (not 4 <= length <= 32):
        raise ValueError('length must be between 4 and 32')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXY23456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def summarize_donations(records: list[dict], min_year: int | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    if min_year is not None and (isinstance(min_year, bool) or not isinstance(min_year, int) or (not 1900 <= min_year <= 2100)):
        raise ValueError('invalid minimum year')
    totals = {}
    total = Decimal('0')
    count = 0
    for record in records:
        try:
            donor, amount, year = (record['donor'], record['amount'], record['year'])
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(donor, str) or not donor:
            raise ValueError('invalid donor')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid amount')
        if isinstance(year, bool) or not isinstance(year, int) or (not 1900 <= year <= 2100):
            raise ValueError('invalid year')
        if min_year is not None and year < min_year:
            continue
        value = Decimal(str(amount))
        total += value
        count += 1
        if donor not in totals:
            totals[donor] = [Decimal('0'), 0]
        totals[donor][0] += value
        totals[donor][1] += 1
    ordered = sorted(totals.items(), key=lambda item: (-item[1][0], item[0]))
    pages = (len(ordered) + page_size - 1) // page_size
    start = (page - 1) * page_size
    donors = [{'donor': name, 'total_amount': float(value[0].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'donation_count': value[1]} for name, value in ordered[start:start + page_size]]
    return {'total_amount': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'total_donations': count, 'pages': pages, 'donors': donors}

