import csv
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from io import StringIO
_HEADER = ['order_id', 'supplier', 'item', 'quantity', 'unit_price', 'status']

def parse_purchase_orders(text: str) -> list[dict]:
    if text == '':
        return []
    try:
        rows = list(csv.reader(StringIO(text), strict=True))
    except csv.Error as e:
        raise ValueError('invalid CSV') from e
    if not rows or [x.strip() for x in rows[0]] != _HEADER:
        raise ValueError('invalid header')
    out = []
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        oid, supplier, item, quantity, price, status = [x.strip() for x in row]
        if not oid or not supplier or (not item):
            raise ValueError('empty field')
        try:
            qty = int(quantity)
            amount = Decimal(price)
        except (ValueError, InvalidOperation) as e:
            raise ValueError('invalid number') from e
        if qty <= 0 or amount < 0 or amount.as_tuple().exponent < -2:
            raise ValueError('invalid number')
        status = status.lower()
        if status not in {'pending', 'approved', 'cancelled'}:
            raise ValueError('invalid status')
        out.append({'order_id': oid, 'supplier': supplier, 'item': item, 'quantity': qty, 'unit_price': amount, 'status': status})
    return out

def summarize_purchase_orders(orders: list[dict]) -> list[dict]:
    groups = {}
    for r in orders:
        if r['status'] == 'cancelled':
            continue
        g = groups.setdefault(r['supplier'], {'ids': set(), 'units': 0, 'total': Decimal('0')})
        g['ids'].add(r['order_id'])
        g['units'] += r['quantity']
        g['total'] += r['quantity'] * r['unit_price']
    out = [{'supplier': s, 'orders': len(g['ids']), 'units': g['units'], 'total': g['total'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)} for s, g in groups.items()]
    return sorted(out, key=lambda x: (-x['total'], x['supplier']))

def export_purchase_orders(text: str, destination: str) -> list[dict]:
    summary = summarize_purchase_orders(parse_purchase_orders(text))
    fd, tmp = tempfile.mkstemp(prefix='purchase-order-', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', newline='') as f:
            w = csv.writer(f, lineterminator='\n')
            w.writerow(['supplier', 'orders', 'units', 'total'])
            for r in summary:
                w.writerow([r['supplier'], r['orders'], r['units'], format(r['total'], '.2f')])
        os.replace(tmp, destination)
    except Exception:
        try:
            os.unlink(tmp)
        except FileNotFoundError:
            pass
        raise
    return summary

