import calendar

def build_roaming_settlement(requester: dict, usage_records: list[dict], rates_cents_per_minute: dict[str, int], month: str, offset: int=0, limit: int=100) -> dict:
    if not isinstance(month, str) or len(month) != 7 or month[4] != '-' or (not month[:4].isdigit()) or (not month[5:].isdigit()):
        raise ValueError('invalid month')
    year = int(month[:4])
    mon = int(month[5:])
    if mon < 1 or mon > 12:
        raise ValueError('invalid month')
    if not isinstance(offset, int) or offset < 0 or (not isinstance(limit, int)) or (limit <= 0):
        raise ValueError('invalid paging')
    if not isinstance(requester, dict) or not isinstance(usage_records, list) or (not isinstance(rates_cents_per_minute, dict)):
        raise ValueError('invalid input')
    try:
        requester_id = requester['id']
        requester_tenant = requester['tenant_id']
        roles = requester['roles']
    except KeyError:
        raise ValueError('invalid requester')
    grouped = {}
    count = 0
    total = 0
    for record in usage_records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            owner = record['owner_id']
            tenant = record['tenant_id']
            date = record['date']
            country = record['country']
            seconds = record['seconds']
        except KeyError:
            raise ValueError('invalid record')
        if not isinstance(date, str) or len(date) != 10 or date[:7] != month or (date[7] != '-'):
            if isinstance(date, str) and date[:7] != month:
                continue
            raise ValueError('invalid date')
        try:
            day = int(date[8:])
            if day < 1 or day > calendar.monthrange(year, mon)[1]:
                raise ValueError
        except Exception:
            raise ValueError('invalid date')
        if not isinstance(seconds, int) or isinstance(seconds, bool) or seconds < 0 or (not isinstance(country, str)) or (country not in rates_cents_per_minute) or (not isinstance(rates_cents_per_minute[country], int)) or (rates_cents_per_minute[country] < 0):
            raise ValueError('invalid usage')
        if not (owner == requester_id or ('settlement_admin' in roles and tenant == requester_tenant)):
            raise PermissionError('not allowed')
        minutes = (seconds + 59) // 60
        cents = minutes * rates_cents_per_minute[country]
        item = grouped.setdefault(country, [0, 0])
        item[0] += minutes
        item[1] += cents
        count += 1
        total += cents
    countries = [{'country': c, 'minutes': v[0], 'cents': v[1]} for c, v in grouped.items()]
    countries.sort(key=lambda x: (-x['cents'], x['country']))
    return {'month': month, 'record_count': count, 'total_cents': total, 'countries': countries[offset:offset + limit]}

