from lxml import etree

def summarize_calibration(xml_text: str, min_accuracy: float=0.0, page: int=1, page_size: int=50) -> list[dict]:
    if not isinstance(xml_text, str):
        raise ValueError('xml_text must be a string')
    if not 0 <= min_accuracy <= 100 or page < 1 or page_size < 1:
        raise ValueError('invalid pagination or accuracy')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'calibration_report':
        raise ValueError('invalid root')
    results = []
    seen = set()
    for sensor in root.findall('sensor'):
        sid = sensor.get('id')
        model = sensor.get('model')
        if sid is None or model is None or sid in seen:
            raise ValueError('invalid sensor')
        seen.add(sid)
        errors = []
        for reading in sensor.findall('reading'):
            value = reading.get('value')
            reference = reading.get('reference')
            status = reading.get('status')
            if value is None or reference is None or status is None:
                raise ValueError('invalid reading')
            if status == 'valid':
                try:
                    errors.append(abs(float(value) - float(reference)))
                except Exception as exc:
                    raise ValueError('invalid number') from exc
        if not errors:
            continue
        mean = sum(errors) / len(errors)
        accuracy = round(100 / (1 + mean), 3)
        if accuracy >= min_accuracy:
            results.append({'id': sid, 'model': model, 'readings': len(errors), 'mean_error': round(mean, 3), 'max_error': round(max(errors), 3), 'accuracy': accuracy})
    results.sort(key=lambda item: (-item['accuracy'], item['id']))
    start = (page - 1) * page_size
    return results[start:start + page_size]

