import hashlib
import hmac
import os

def create_evaluator(name: str, password: str) -> dict:
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    rounds = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds)
    return {'name': name.strip(), 'password': f'pbkdf2${rounds}${salt.hex()}${digest.hex()}'}

def verify_evaluator(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(record.get('name'), str) or (not isinstance(password, str)):
        return False
    try:
        kind, count, salt_text, digest_text = record['password'].split('$')
        if kind != 'pbkdf2':
            return False
        rounds = int(count)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

def rank_talents(records: list[dict], window: int=3) -> list[dict]:
    if not isinstance(records, list) or isinstance(window, bool) or (not isinstance(window, int)) or (window <= 0):
        raise ValueError('invalid arguments')
    grouped = {}
    for item in records:
        if not isinstance(item, dict):
            raise ValueError('invalid evaluation')
        if not isinstance(item.get('talent'), str) or not isinstance(item.get('scout'), str):
            raise ValueError('invalid evaluation')
        r, score, conf = (item.get('round'), item.get('score'), item.get('confidence'))
        if isinstance(r, bool) or not isinstance(r, int) or r < 1 or isinstance(score, bool) or (not isinstance(score, (int, float))) or (not 0 <= score <= 100) or isinstance(conf, bool) or (not isinstance(conf, (int, float))) or (not 1 <= conf <= 5):
            raise ValueError('invalid evaluation')
        grouped.setdefault(item['talent'], {})[item['scout'], r] = (score, conf)
    result = []
    for talent, values in grouped.items():
        rounds = sorted({r for _, r in values}, reverse=True)[:window]
        chosen = [(s, c) for (_, r), (s, c) in values.items() if r in rounds]
        total = sum((c for s, c in chosen))
        result.append({'talent': talent, 'score': round(sum((s * c for s, c in chosen)) / total, 2), 'confidence': round(sum((c for s, c in chosen)) / len(chosen), 2), 'evaluations': len(chosen)})
