    allowed = {'plot_number', 'section', 'status', 'occupant', 'last_inspection'}
    if sort_by not in allowed:
        raise ValueError('invalid sort column')
    clauses = []
    params = []
    if section is not None:
        clauses.append('section = ?')
        params.append(section)
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    if search:
        clauses.append("(LOWER(plot_number) LIKE ? OR LOWER(COALESCE(occupant, '')) LIKE ?)")
        value = '%' + search.lower() + '%'
        params.extend([value, value])
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    null_order = f'{sort_by} IS NULL ASC'
    sql = f'SELECT plot_number, section, status, occupant, last_inspection FROM plots{where} ORDER BY {null_order}, {sort_by} {direction}, plot_number ASC'
    cursor = conn.execute(sql, params)
    names = [item[0] for item in cursor.description]
    return [dict(zip(names, row)) for row in cursor.fetchall()]

