    value = occupant.strip()
    if not value:
        raise ValueError('occupant must not be blank')
    cur = conn.execute("UPDATE plots SET status = ?, occupant = ? WHERE plot_number = ? AND status = 'available'", ('reserved', value, plot_number))
    conn.commit()
    return cur.rowcount == 1

