    rows = conn.execute('SELECT section, status, last_inspection FROM plots ORDER BY section').fetchall()
    groups = {}
    for section, status, inspection in rows:
        group = groups.setdefault(section, {'section': section, 'total': 0, 'available': 0, 'reserved': 0, 'latest_inspection': None})
        group['total'] += 1
        if status == 'available':
            group['available'] += 1
        if status == 'reserved':
            group['reserved'] += 1
        if inspection is not None and (group['latest_inspection'] is None or inspection > group['latest_inspection']):
            group['latest_inspection'] = inspection
    result = []
    for group in groups.values():
        group['occupancy_rate'] = round((group['total'] - group['available']) / group['total'], 3)
        result.append({'section': group['section'], 'total': group['total'], 'available': group['available'], 'reserved': group['reserved'], 'occupancy_rate': group['occupancy_rate'], 'latest_inspection': group['latest_inspection']})
    return result

