import hashlib
import hmac
import json
import os
from datetime import date
_STATUSES = ('submitted', 'under_review', 'approved', 'rejected')

def build_report(records: list[dict], config: dict[str, str]) -> dict:
    if not isinstance(records, list) or not isinstance(config, dict):
        raise TypeError('records and config must be dictionaries or lists as specified')
    seen = set()
    applications = []
    for record in records:
        ident = record.get('id')
        agency = record.get('agency')
        amount = record.get('amount')
        events = record.get('events')
        if not isinstance(ident, str) or not ident or ident in seen:
            raise ValueError('application IDs must be unique and nonempty')
        if not isinstance(agency, str) or not agency:
            raise ValueError('agency must be nonempty')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0:
            raise ValueError('amount must be a nonnegative number')
        if not isinstance(events, list) or not events:
            raise ValueError('each application needs an event')
        chosen = None
        for event in events:
            status = event.get('status')
            stamp = event.get('at')
            if status not in _STATUSES:
                raise ValueError('invalid status')
            try:
                parsed = date.fromisoformat(stamp)
            except (TypeError, ValueError):
                raise ValueError('invalid event date')
            if chosen is None or parsed >= chosen[0]:
                chosen = (parsed, stamp, status)
        seen.add(ident)
        applications.append({'id': ident, 'agency': agency, 'amount': amount, 'status': chosen[2], 'as_of': chosen[1]})
    applications.sort(key=lambda x: (-date.fromisoformat(x['as_of']).toordinal(), x['id']))
    agencies = {}
    for item in applications:
        group = agencies.setdefault(item['agency'], {'count': 0, 'total_amount': 0, 'statuses': {s: 0 for s in _STATUSES}})
        group['count'] += 1
        group['total_amount'] += item['amount']
        group['statuses'][item['status']] += 1
    return {'applications': applications, 'agencies': {key: agencies[key] for key in sorted(agencies)}}

def sign_report(records: list[dict], config: dict[str, str]) -> str:
    report = build_report(records, config)
    key = config.get('GRANT_SIGNING_KEY') or os.environ.get('GRANT_SIGNING_KEY')
    if key is None:
        raise ValueError('GRANT_SIGNING_KEY is required')
    payload = json.dumps(report, sort_keys=True, separators=(',', ':'))
    digest = hmac.new(key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return payload + '.' + digest

