import ast
import operator

def _evaluate(text, values):
    try:
        tree = ast.parse(text, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name) and node.id in values:
                return values[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
            if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](visit(node.left), visit(node.right))
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                result = visit(node.values[0])
                for part in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not result):
                        return result
                    if isinstance(node.op, ast.Or) and result:
                        return result
                    result = visit(part)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, right_node in zip(node.ops, node.comparators):
                    right = visit(right_node)
                    if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
                args = [visit(x) for x in node.args]
                return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError() from exc

def generate_alerts(readings: list[dict], rule: str, window: int=3) -> list[dict]:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError()
    histories = {}
    counts = {}
    previous = {}
    result = []
    for item in readings:
        if not isinstance(item, dict) or set(item) != {'device', 'timestamp', 'temp', 'humidity', 'battery'}:
            raise ValueError()
        if not isinstance(item['device'], str) or not item['device'] or (not isinstance(item['timestamp'], int)):
            raise ValueError()
        if any((not isinstance(item[k], (int, float)) or isinstance(item[k], bool) for k in ('temp', 'humidity', 'battery'))):
            raise ValueError()
        device = item['device']
        values = histories.setdefault(device, [])
        values.append(item['temp'])
        del values[:-window]
        counts[device] = counts.get(device, 0) + 1
        delta = item['temp'] - previous.get(device, item['temp'])
        previous[device] = item['temp']
        avg = sum(values) / len(values)
        env = {'temp': item['temp'], 'humidity': item['humidity'], 'battery': item['battery'], 'avg_temp': avg, 'delta': delta, 'count': counts[device]}
        if _evaluate(rule, env):
            severity = 'critical' if item['temp'] >= 8 else 'warning' if item['temp'] >= 5 else 'notice'
            result.append({'device': device, 'timestamp': item['timestamp'], 'temp': item['temp'], 'avg_temp': avg, 'delta': delta, 'severity': severity})
    return result

def summarize_alerts(alerts: list[dict]) -> dict:
    result = {}
    for alert in alerts:
        device = alert['device']
        if device not in result:
            result[device] = {'count': 0, 'max_temp': alert['temp'], 'first_timestamp': alert['timestamp']}
        result[device]['count'] += 1
        result[device]['max_temp'] = max(result[device]['max_temp'], alert['temp'])
    return result

