import subprocess

def rank_grant_drafts(paths: list[str], max_words: int | None=None, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not isinstance(paths, list) or any((not isinstance(path, str) for path in paths)):
        raise TypeError('paths must be a list of strings')
    if max_words is not None and (isinstance(max_words, bool) or not isinstance(max_words, int) or max_words < 0):
        raise ValueError('max_words must be a non-negative integer or None')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('page_size must be between 1 and 100')
    records = []
    for path in paths:
        if not os.path.isfile(path):
            raise FileNotFoundError(path)
        result = subprocess.run(['wc', '-w', path], capture_output=True, text=True, check=True)
        words = int(result.stdout.split()[0])
        if max_words is None or words <= max_words:
            records.append((words, os.path.basename(path), path))
    records.sort(key=lambda item: (-item[0], item[1], item[2]))
    start = (page - 1) * page_size
    selected = records[start:start + page_size]
    return [{'name': name, 'words': words} for words, name, path in selected]

