from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def read_card_activity(path: str, minimum_visits: int=0, page: int=1, page_size: int=10) -> dict:
    if isinstance(minimum_visits, bool) or not isinstance(minimum_visits, int) or minimum_visits < 0:
        raise ValueError('invalid minimum_visits')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page_size')
    completed = subprocess.run(['sort', '-t,', '-k2,2nr', '-k1,1', path], capture_output=True, text=True, check=True)
    records = []
    seen = set()
    total = Decimal('0')
    for raw in completed.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 3:
            raise ValueError('malformed record')
        card_id, visits_text, fees_text = (field.strip() for field in fields)
        if not card_id or card_id in seen:
            raise ValueError('invalid card_id')
        try:
            visits = int(visits_text)
            fees = Decimal(fees_text)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid record')
        if visits < 0 or str(visits) != visits_text.strip() or (not fees.is_finite()) or (fees < 0):
            raise ValueError('invalid record')
        seen.add(card_id)
        if visits >= minimum_visits:
            rounded = fees.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            records.append({'card_id': card_id, 'visits': visits, 'fees': float(rounded)})
            total += fees
    start = (page - 1) * page_size
    finish = start + page_size
    return {'total_cards': len(records), 'total_fees': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'entries': records[start:finish]}

