from decimal import Decimal, ROUND_HALF_UP
import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_access_code(length: int=16) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 64):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def _tax(x, brackets):
    total = Decimal('0')
    previous = Decimal('0')
    for limit, rate in brackets:
        part = max(Decimal('0'), min(x, limit) - previous)
        total += part * rate
        previous = limit
        if x <= limit:
            break
    return total

def _check_brackets(brackets):
    if not brackets:
        raise ValueError('invalid brackets')
    previous = Decimal('0')
    converted = []
    for limit, rate in brackets:
        try:
            limit, rate = (Decimal(limit), Decimal(rate))
        except Exception as e:
            raise ValueError('invalid brackets') from e
        if limit <= previous or rate < 0 or rate > 1:
            raise ValueError('invalid brackets')
        converted.append((limit, rate))
        previous = limit
    if converted[-1][0] != Decimal('Infinity'):
        raise ValueError('invalid brackets')

def calculate_withholding(gross: Decimal, pre_tax: Decimal, prior_taxable: Decimal, brackets: list[tuple[Decimal, Decimal]]) -> tuple[Decimal, Decimal]:
    try:
        gross, pre_tax, prior_taxable = (Decimal(gross), Decimal(pre_tax), Decimal(prior_taxable))
    except Exception as e:
        raise ValueError('invalid amount') from e
    _check_brackets(brackets)
    current = gross - pre_tax
    if current < 0 or prior_taxable < 0:
        raise ValueError('negative taxable wages')
    cumulative = prior_taxable + current
    value = (_tax(cumulative, brackets) - _tax(prior_taxable, brackets)).quantize(Decimal('.01'), rounding=ROUND_HALF_UP)
    return (value, cumulative)

def process_payroll(records: list[dict], brackets: list[tuple[Decimal, Decimal]]) -> list[dict]:
    _check_brackets(brackets)
    import datetime
    rows = []
    for item in records:
        if set(item) != {'employee', 'date', 'gross', 'pre_tax'}:
            raise ValueError('invalid record')
        employee, date = (item['employee'], item['date'])
        if not isinstance(employee, str) or not employee or (not isinstance(date, str)):
            raise ValueError('invalid record')
        try:
            if datetime.date.fromisoformat(date).isoformat() != date:
                raise ValueError
            gross, pre = (Decimal(item['gross']), Decimal(item['pre_tax']))
        except Exception as e:
            raise ValueError('invalid record') from e
        if gross < 0 or pre < 0 or pre > gross:
            raise ValueError('invalid record')
        rows.append((date, employee, gross, pre))
    rows.sort(key=lambda x: (x[0], x[1]))
    ytd, output = ({}, [])
    for date, employee, gross, pre in rows:
