from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
_HEADER = ['claim_id', 'traveler', 'country', 'amount', 'status', 'days']
_STATUSES = {'approved', 'pending', 'denied'}
_CENTS = Decimal('0.01')

def _money(value):
    try:
        d = Decimal(value.strip())
    except (AttributeError, InvalidOperation):
        raise ValueError('invalid amount')
    if not d.is_finite() or d < 0 or d != d.quantize(_CENTS):
        raise ValueError('invalid amount')
    return d.quantize(_CENTS)

def parse_claims(data: str) -> list[dict]:
    if not data or not data.strip():
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(data.splitlines()))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    while rows and (not any((x.strip() for x in rows[-1]))):
        rows.pop()
    if not rows or rows[0] != _HEADER:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if not any((x.strip() for x in row)):
            continue
        if len(row) != 6:
            raise ValueError('invalid row')
        claim_id, traveler, country, amount, status, days = [x.strip() for x in row]
        if not claim_id or not traveler or (not country) or (claim_id in seen):
            raise ValueError('invalid identity')
        if status not in _STATUSES:
            raise ValueError('invalid status')
        try:
            day_count = int(days)
        except ValueError as exc:
            raise ValueError('invalid days') from exc
        if str(day_count) != days or day_count < 0:
            raise ValueError('invalid days')
        result.append({'claim_id': claim_id, 'traveler': traveler, 'country': country, 'amount': _money(amount), 'status': status, 'days': day_count})
        seen.add(claim_id)
    if not result:
        raise ValueError('no claims')
    return result

def export_claims(data: str, destination: str) -> dict:
    claims = parse_claims(data)
    order = {'approved': 0, 'pending': 1, 'denied': 2}
    claims.sort(key=lambda x: (x['country'], order[x['status']], -x['amount'], x['claim_id']))
    totals = {s: Decimal('0.00') for s in _STATUSES}
    payout_total = Decimal('0.00')
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.claims-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.writer(stream)
            writer.writerow(_HEADER + ['payout'])
            for claim in claims:
                amount = claim['amount']
                payout = amount if claim['status'] == 'approved' else Decimal('0.00')
                totals[claim['status']] += amount
                payout_total += payout
                writer.writerow([claim['claim_id'], claim['traveler'], claim['country'], f'{amount:.2f}', claim['status'], claim['days'], f'{payout:.2f}'])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'claim_count': len(claims), 'approved_total': totals['approved'].quantize(_CENTS), 'pending_total': totals['pending'].quantize(_CENTS), 'denied_total': totals['denied'].quantize(_CENTS), 'payout_total': payout_total.quantize(_CENTS)}

