import re

def parse_deductions(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('deductions')
    entries = []
    cur = []
    esc = False
    for ch in text:
        if esc:
            cur.append(('lit', ch))
            esc = False
        elif ch == '\\':
            esc = True
        elif ch == ';':
            entries.append(cur)
            cur = []
        else:
            cur.append(('raw', ch))
    if esc:
        raise ValueError('escape')
    entries.append(cur)
    out = []
    seen = set()
    for item in entries:
        if not item:
            continue
        sep = None
        for i, (kind, ch) in enumerate(item):
            if kind == 'raw' and ch == ':':
                sep = i
                break
        if sep is None:
            raise ValueError('entry')
        left = ''.join((ch for _, ch in item[:sep]))
        right = ''.join((ch for _, ch in item[sep + 1:]))
        if not left or not re.fullmatch('[A-Za-z0-9 _:-]+', left) or (not re.fullmatch('[0-9]+', right)):
            raise ValueError('entry')
        if left in seen:
            raise ValueError('duplicate')
        seen.add(left)
        out.append({'category': left, 'cents': int(right)})
    return out

def calculate_tax(tax_return: dict, prior_returns: list[dict]) -> dict:
    try:
        owner = tax_return['owner_id']
        year = tax_return['tax_year']
        gross = tax_return['gross_cents']
        credits = tax_return['credits_cents']
        deductions_text = tax_return['deductions']
    except (KeyError, TypeError):
        raise ValueError('return')
    if not all((isinstance(x, int) and (not isinstance(x, bool)) for x in (year, gross, credits))) or gross < 0 or credits < 0:
        raise ValueError('values')
    total = sum((x['cents'] for x in parse_deductions(deductions_text)))
    deductions = min(total, gross * 40 // 100)
    taxable = gross - deductions
    bracket = min(taxable, 10000) * 10 // 100 + max(0, min(taxable - 10000, 40000)) * 20 // 100 + max(0, taxable - 50000) * 30 // 100
    carry = max((x.get('final_tax_cents', 0) for x in prior_returns if x.get('owner_id') == owner and x.get('tax_year', year) < year), default=0)
    used = min(bracket, credits + min(carry, bracket * 10 // 100))
    return {'tax_year': year, 'gross_cents': gross, 'deductions_cents': deductions, 'taxable_cents': taxable, 'bracket_tax_cents': bracket, 'credits_used_cents': used, 'final_tax_cents': bracket - used}

def submit_filing(requester: dict, tax_return: dict, ledger: list[dict]) -> dict:
    required = ['return_id', 'owner_id', 'tenant_id', 'tax_year', 'gross_cents', 'deductions', 'credits_cents', 'status']
    if not isinstance(requester, dict) or not isinstance(tax_return, dict) or (not isinstance(ledger, list)) or any((x not in tax_return for x in required)) or (tax_return['status'] != 'draft'):
        raise ValueError('filing')
    if requester.get('tenant_id') != tax_return['tenant_id'] or not (requester.get('user_id') == tax_return['owner_id'] or 'tax_agent' in requester.get('roles', [])):
        raise PermissionError('forbidden')
    if any((x.get('return_id') == tax_return['return_id'] for x in ledger)):
        raise ValueError('duplicate')
    result = dict(tax_return)
    result.update(calculate_tax(tax_return, ledger))
    result['status'] = 'submitted'
    ledger.append(result)
    return result

