        raise ValueError('orders must be a list')
    fields = {'id', 'machine', 'duration', 'due', 'priority'}
    result = []
    seen = set()
    for item in value:
        if not isinstance(item, dict) or set(item) != fields:
            raise ValueError('invalid order fields')
        if not isinstance(item['id'], str) or not item['id']:
            raise ValueError('invalid id')
        if not isinstance(item['machine'], str) or not item['machine']:
            raise ValueError('invalid machine')
        if any((isinstance(item[k], bool) or not isinstance(item[k], int) for k in ('duration', 'due', 'priority'))):
