            raise ValueError('invalid order')
        seen.add(item['id'])
        result.append({k: item[k] for k in ('id', 'machine', 'duration', 'due', 'priority')})
    return result

def make_schedule(orders: list[dict], config: dict[str, str]) -> dict:
    token = config.get('scheduler_token') if isinstance(config, dict) else None
    if not isinstance(token, str) or not token:
        raise ValueError('scheduler_token is required')
    groups = {}
    for order in orders:
        groups.setdefault(order['machine'], []).append(order)
    jobs = []
    for machine, group in groups.items():
        current = 0
        for order in sorted(group, key=lambda x: (x['due'], -x['priority'], x['id'])):
            finish = current + order['duration']
            jobs.append({'id': order['id'], 'machine': machine, 'start': current, 'finish': finish, 'due': order['due'], 'priority': order['priority']})
            current = finish
    jobs.sort(key=lambda x: (x['start'], x['machine'], x['id']))
    canonical = json.dumps(jobs, sort_keys=True, separators=(',', ':')).encode()
    digest = hmac.new(token.encode(), canonical, hashlib.sha256).hexdigest()
    return {'jobs': jobs, 'digest': digest}

def serialize_schedule(schedule: dict) -> str:
    if not isinstance(schedule, dict) or 'jobs' not in schedule or 'digest' not in schedule:
        raise ValueError('invalid schedule')
    return json.dumps({'jobs': schedule['jobs'], 'digest': schedule['digest']}, sort_keys=True, separators=(',', ':'))

