        total += amount
        entry = vendors.setdefault(vendor, {'invoice_count': 0, 'outstanding_count': 0})
        entry['invoice_count'] += 1
        if not paid:
            outstanding += amount
            entry['outstanding_count'] += 1
    parent = os.path.dirname(os.path.abspath(output_path))
