            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['invoice_id', 'vendor', 'amount', 'status', 'due_date'])
            for invoice_id, vendor, amount, paid, due_date in normalized:
                writer.writerow([invoice_id, vendor, f'{amount:.2f}', 'paid' if paid else 'outstanding', due_date.isoformat()])
        os.replace(temporary_path, output_path)
    except Exception:
        try:
            os.unlink(temporary_path)
        except FileNotFoundError:
            pass
        raise
    return {'invoice_count': len(normalized), 'total_amount': f'{total:.2f}', 'outstanding_amount': f'{outstanding:.2f}', 'vendors': dict(sorted(vendors.items()))}

