import datetime
import math
import subprocess

def feeding_summary(path: str, species: str | None=None, page: int=1, page_size: int=20) -> list[tuple[str, float]]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if species == '':
        raise ValueError('empty species')
    result = subprocess.run(['sort', '-t,', '-k1,1', '-k2,2', path], capture_output=True, text=True, check=True)
    totals: dict[str, float] = {}
    for line in result.stdout.splitlines():
        fields = line.split(',')
        if len(fields) != 3:
            raise ValueError('invalid record')
        date_text, record_species, kilograms_text = fields
        try:
            datetime.date.fromisoformat(date_text)
            kilograms = float(kilograms_text)
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if not record_species or not math.isfinite(kilograms) or kilograms < 0:
            raise ValueError('invalid record')
        if species is None or record_species == species:
            totals[date_text] = totals.get(date_text, 0.0) + kilograms
    ordered = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    return [(date, round(total, 2)) for date, total in ordered[start:start + page_size]]

