import hashlib
import hmac
import json
import math

def verify_webhook(body: str, signature: str, secret: str) -> bool:
    if not isinstance(body, str) or not isinstance(signature, str) or (not isinstance(secret, str)):
        return False
    try:
        expected = hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()
        int(signature, 16)
    except (TypeError, ValueError, UnicodeError):
        return False
    if len(signature) != 64:
        return False
    return hmac.compare_digest(expected, signature)

def handle_webhook(body: str, signature: str, secret: str, page: int=1, page_size: int=2) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    if not verify_webhook(body, signature, secret):
        return {'accepted': False, 'items': [], 'total': 0}
    try:
        records = json.loads(body)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid JSON')
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    groups = {}
    ranks = {'low': 0, 'medium': 1, 'high': 2}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        sensor = record.get('sensor')
        liters = record.get('liters')
        severity = record.get('severity')
        if not isinstance(sensor, str) or not sensor:
            raise ValueError('invalid sensor')
        if isinstance(liters, bool) or not isinstance(liters, (int, float)) or (not math.isfinite(liters)) or (liters <= 0):
            raise ValueError('invalid liters')
        if severity not in ranks:
            raise ValueError('invalid severity')
        group = groups.setdefault(sensor, {'sensor': sensor, 'total_liters': 0.0, 'count': 0, 'max_severity': severity})
        group['total_liters'] += liters
        group['count'] += 1
        if ranks[severity] > ranks[group['max_severity']]:
            group['max_severity'] = severity
    items = list(groups.values())
    for item in items:
        item['total_liters'] = round(item['total_liters'], 2)
    items.sort(key=lambda item: (-item['total_liters'], item['sensor']))
    start = (page - 1) * page_size
    return {'accepted': True, 'items': items[start:start + page_size], 'total': len(items)}

