from decimal import Decimal, InvalidOperation, ROUND_DOWN
from lxml import etree

def _amount(value):
    try:
        d = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid amount')
    if not d.is_finite() or d < 0 or d.as_tuple().exponent < -2:
        raise ValueError('invalid amount')
    return int((d * 100).to_integral_value(rounding=ROUND_DOWN))

def parse_tax_return(xml_text: str) -> dict:
    try:
        root = etree.fromstring(xml_text.encode(), etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'tax_return' or set(root.attrib) != {'year'}:
        raise ValueError('invalid root')
    try:
        year = int(root.get('year'))
    except Exception as exc:
        raise ValueError('invalid year') from exc
    if not 1900 <= year <= 2100:
        raise ValueError('invalid year')
    allowed = {'taxpayer', 'income', 'deductions', 'credits'}
    if any((x.tag not in allowed or set(x.attrib) - {'id', 'filing_status'} for x in root)):
        raise ValueError('invalid structure')
    taxpayers = root.xpath('./taxpayer')
    if len(taxpayers) != 1:
        raise ValueError('taxpayer required')
    person = taxpayers[0]
    if set(person.attrib) != {'id', 'filing_status'}:
        raise ValueError('invalid taxpayer')
    ident = person.get('id').strip()
    status = person.get('filing_status')
    if not ident or status not in {'single', 'married', 'head_of_household'} or len(person) or person.tail:
        raise ValueError('invalid taxpayer')
    result = {'year': year, 'taxpayer_id': ident, 'filing_status': status, 'incomes': [], 'deductions': [], 'credits': []}
    sections = {'income': 'incomes', 'deductions': 'deductions', 'credits': 'credits'}
    for section in root:
        if section.tag == 'taxpayer':
            continue
        if section.attrib or len([x for x in root if x.tag == section.tag]) > 1:
            raise ValueError('invalid section')
        target = sections[section.tag]
        seen = set()
        for item in section:
            if item.tag != 'item' or set(item.attrib) != ({'category', 'amount'} if target == 'incomes' else {'code', 'amount'}) or len(item):
                raise ValueError('invalid item')
            keyname = 'category' if target == 'incomes' else 'code'
            key = item.get(keyname).strip()
            if not key or key in seen:
                raise ValueError('duplicate item')
            seen.add(key)
            result[target].append({keyname: key, 'amount': _amount(item.get('amount'))})
    return result

def calculate_tax(return_data: dict) -> dict:
    out = dict(return_data)
    income = sum((x['amount'] for x in return_data['incomes']))
    deductions = sum((x['amount'] for x in return_data['deductions']))
    credits = sum((x['amount'] for x in return_data['credits']))
    taxable = max(0, income - deductions)
    first = min(taxable, 1000000)
    second = min(max(0, taxable - 1000000), 4000000)
    rest = max(0, taxable - 5000000)
    before = first // 10 + second // 5 + rest * 3 // 10
    out.update(income_total=income, deduction_total=deductions, credit_total=credits, taxable_income=taxable, tax_before_credits=before, tax_due=max(0, before - credits))
    return out

def summarize_returns(xml_documents: list[str]) -> list[dict]:
    results = [calculate_tax(parse_tax_return(x)) for x in xml_documents]
    ids = [x['taxpayer_id'] for x in results]
    if len(ids) != len(set(ids)):
        raise ValueError('duplicate taxpayer')
    return sorted(results, key=lambda x: (-x['tax_due'], x['taxpayer_id']))

