def verify_certificates(xml_text: str, current_height: int) -> list[dict[str, object]]:
    if not isinstance(xml_text, str) or isinstance(current_height, bool) or (not isinstance(current_height, int)) or (current_height < 0):
        raise ValueError('invalid input')
    parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
    try:
        root = etree.fromstring(xml_text.encode(), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'certificates':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for node in root:
        if node.tag != 'certificate':
            raise ValueError('invalid element')
        required = ('txid', 'subject', 'issuer', 'status', 'block')
        if any((node.get(k) is None or node.get(k) == '' for k in required)):
            raise ValueError('missing attribute')
        txid = node.get('txid')
        if txid in seen:
            raise ValueError('duplicate transaction')
        seen.add(txid)
        status = node.get('status')
        try:
            block = int(node.get('block'))
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid block') from exc
        if block < 0 or status not in ('valid', 'revoked'):
            raise ValueError('invalid certificate')
        confirmations = current_height - block + 1
        if status == 'valid' and confirmations >= 6:
            result.append({'txid': txid, 'subject': node.get('subject'), 'issuer': node.get('issuer'), 'confirmations': confirmations})
    result.sort(key=lambda item: (-item['confirmations'], item['txid']))
    return result

