def process_provisioning_request(payload: str, headers: dict[str, str]) -> dict[str, object]:
    token = headers.get('X-Provisioning-Token')
    if not isinstance(token, str) or not hmac.compare_digest(token, 'telco-provisioning-v1'):
        raise ValueError('invalid token')
    try:
        data = json.loads(payload)
        if not isinstance(data, dict):
