        raise PermissionError('forbidden')
    if requester['user_id'] not in u['owner_ids'] and requester['tenant_id'] != u['tenant_id']:
        raise PermissionError('forbidden')
    start = date.fromisoformat(u['start_date'])
    if cutoff < start:
        raise ValueError('date before start')
    lines = []
    cur = start.replace(day=1)
    while cur <= cutoff:
        d = start if cur.year == start.year and cur.month == start.month else cur
        lines.append({'id': f'due-{cur:%Y-%m}', 'date': d.isoformat(), 'kind': 'charge', 'amount_cents': u['monthly_due_cents'], 'memo': 'monthly dues'})
        cur = (cur.replace(day=28) + timedelta(days=4)).replace(day=1)
    seen = set()
    txs = []
    for t in transactions:
        if t['id'] in seen:
            raise ValueError('duplicate transaction')
        seen.add(t['id'])
