        if t['amount_cents'] < 0 or t['kind'] not in {'payment', 'credit'}:
            raise ValueError('invalid transaction')
        if t['unit_id'] == unit_id and d <= cutoff:
            txs.append((d, t))
    charges = [x for x in lines if x['kind'] == 'charge']
    remaining = [x['amount_cents'] for x in charges]
    for _, t in sorted(txs, key=lambda z: (z[0], z[1]['id'])):
        amount = t['amount_cents']
        for i in range(len(remaining)):
            take = min(amount, remaining[i])
            remaining[i] -= take
            amount -= take
            if not amount:
                break
    for c, rem in zip(charges, remaining):
        due = date.fromisoformat(c['date'])
        if rem and cutoff > due + timedelta(days=u['grace_days']) and late_fee_cents:
