    for _, t in txs:
        lines.append({'id': t['id'], 'date': t['date'], 'kind': t['kind'], 'amount_cents': t['amount_cents'], 'memo': t.get('memo', '')})
    lines.sort(key=lambda x: (x['date'], x['id']))
    charges_total = sum((x['amount_cents'] for x in lines if x['kind'] in {'charge', 'late_fee'}))
    credits = sum((x['amount_cents'] for x in lines if x['kind'] in {'payment', 'credit'}))
    return {'unit_id': unit_id, 'as_of': as_of, 'lines': lines, 'total_charges_cents': charges_total, 'total_credits_cents': credits, 'balance_cents': charges_total - credits, 'delinquent': bool(any(remaining) or charges_total > credits)}

