def list_warranty_claims(conn: sqlite3.Connection, status: str | None=None, search: str | None=None, min_cost: float | None=None, sort_by: str='filed_date', descending: bool=False, limit: int=20, offset: int=0) -> list[dict]:
    columns = {'filed_date': 'filed_date', 'repair_cost': 'repair_cost', 'vehicle_id': 'vehicle_id', 'id': 'id'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    if type(limit) is not int or type(offset) is not int:
        raise TypeError('limit and offset must be integers')
    if limit < 1 or offset < 0:
        raise ValueError('invalid pagination')
    if min_cost is not None and type(min_cost) not in (int, float):
        raise TypeError('min_cost must be numeric')
    if min_cost is not None and min_cost < 0:
        raise ValueError('min_cost must be nonnegative')
    if type(descending) is not bool:
        raise ValueError('descending must be boolean')
    clauses = []
    if status is not None:
        clauses.append("status = '" + status + "'")
    if search is not None:
        clauses.append("lower(vehicle_id) LIKE lower('%" + search + "%')")
    if min_cost is not None:
        clauses.append('repair_cost >= ' + str(min_cost))
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = ' DESC' if descending else ' ASC'
    sql = 'SELECT id, vehicle_id, status, repair_cost, filed_date FROM claims' + where + ' ORDER BY ' + columns[sort_by] + direction + ', id ASC LIMIT ' + str(limit) + ' OFFSET ' + str(offset)
