import hashlib
import hmac
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode('utf-8'), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        raise TypeError('arguments must be strings')
    try:
        salt_text, digest_text = stored.split('$')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

