import re
import secrets
from datetime import date

def make_invite_code(length: int=12) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 6 <= length <= 32):
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def _fields(line: str) -> list[str]:
    result = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            result.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    result.append(''.join(current))
    if len(result) != 4:
        raise ValueError('wrong field count')
    return result

def _parsed_date(value: str) -> date:
    if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', value):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def parse_case_log(text: str) -> list[dict]:
    records = []
    statuses = {'RECEIVED', 'REVIEW', 'INTERVIEW', 'APPROVED', 'DENIED'}
    for raw in text.splitlines():
        if not raw.strip():
            continue
        case_id, when, status, note = _fields(raw)
        if not re.fullmatch('[A-Z]{2}-\\d{4}', case_id):
            raise ValueError('invalid case id')
        _parsed_date(when)
        if status not in statuses:
            raise ValueError('invalid status')
        records.append({'case_id': case_id, 'date': when, 'status': status, 'note': note})
    return records

def summarize_cases(text: str, as_of: str) -> dict:
    cutoff = _parsed_date(as_of)
    grouped = {}
    for index, record in enumerate(parse_case_log(text)):
        when = _parsed_date(record['date'])
        if when > cutoff:
            raise ValueError('future event')
        grouped.setdefault(record['case_id'], []).append((when, index, record))
    result = {}
    for case_id in sorted(grouped):
        events = sorted(grouped[case_id], key=lambda item: (item[0], item[1]))
        first = events[0][0]
        latest = events[-1][2]
        result[case_id] = {'status': latest['status'], 'updated': latest['date'], 'history': [item[2]['status'] for item in events], 'notes': sum((bool(item[2]['note']) for item in events)), 'age_days': (cutoff - first).days}
    return result

