import json
import os
from datetime import date, timedelta

def load_campaign(base_dir: str, filename: str) -> dict:
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, filename))
    if os.path.commonpath([base, path]) != base:
        raise ValueError('invalid filename')
    try:
        with open(path, encoding='utf-8') as handle:
            value = json.load(handle)
    except (OSError, ValueError, TypeError) as exc:
        raise ValueError('invalid campaign') from exc
    if not isinstance(value, dict):
        raise ValueError('invalid campaign')
    return value

def select_recipients(campaign: dict, contacts: list[dict], as_of: str) -> list[dict]:
    if not isinstance(campaign, dict) or not isinstance(campaign.get('subject'), str) or (not isinstance(campaign.get('conditions'), list)):
        raise ValueError('invalid campaign')
    try:
        end = date.fromisoformat(as_of)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc
    conditions = campaign['conditions']
    allowed = {'country', 'email', 'first_name', 'engagement'}
    for condition in conditions:
        if not isinstance(condition, dict) or set(('field', 'op', 'value')) - condition.keys():
            raise ValueError('invalid condition')
        if condition['field'] not in allowed or condition['op'] not in {'eq', 'in', 'gte', 'lte'}:
            raise ValueError('invalid condition')
        if condition['op'] == 'in' and (not isinstance(condition['value'], list)):
            raise ValueError('invalid condition')
    result = []
    for contact in contacts:
        if not isinstance(contact, dict) or not isinstance(contact.get('id'), str) or (not isinstance(contact.get('email'), str)):
            raise ValueError('invalid contact')
        events = contact.get('events', [])
        if not isinstance(events, list):
            raise ValueError('invalid events')
        count = 0
        for event in events:
            if not isinstance(event, dict) or not isinstance(event.get('type'), str) or (not isinstance(event.get('date'), str)):
                raise ValueError('invalid event')
            try:
                event_day = date.fromisoformat(event['date'])
            except ValueError as exc:
                raise ValueError('invalid event date') from exc
            if event['type'] == 'open' and end - timedelta(days=30) <= event_day <= end:
                count += 1
        matched = True
        for condition in conditions:
            field, op, expected = (condition['field'], condition['op'], condition['value'])
            actual = count if field == 'engagement' else contact.get(field)
            if field != 'engagement' and field not in contact:
                matched = False
                break
            try:
                ok = actual == expected if op == 'eq' else actual in expected if op == 'in' else actual >= expected if op == 'gte' else actual <= expected
            except TypeError:
                ok = False
            if not ok:
                matched = False
                break
        if matched:
            result.append((count, contact['email'], contact['id'], {'id': contact['id'], 'email': contact['email'], 'subject': campaign['subject'].replace('{{first_name}}', contact.get('first_name', ''))}))
    result.sort(key=lambda item: (-item[0], item[1].casefold(), item[2]))
    return [item[3] for item in result]

