import ast
import numbers

def _evaluate(expression, values):
    try:
        tree = ast.parse(expression, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, bool):
                return node.value
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
                return node.value
            if isinstance(node, ast.Name) and node.id in values:
                return values[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                a, b = (visit(node.left), visit(node.right))
                return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                result = visit(node.values[0])
                for item in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not result):
                        return result
                    if isinstance(node.op, ast.Or) and result:
                        return result
                    result = visit(item)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, part in zip(node.ops, node.comparators):
                    right = visit(part)
                    result = {ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right, ast.Eq: left == right, ast.NotEq: left != right}[type(op)]
                    if not result:
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                args = [visit(x) for x in node.args]
                return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        raise ValueError() from exc

def process_particles(events: list[dict[str, object]], selection: str, score: str, limit: int=10) -> dict[str, object]:
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError()
    required = {'id', 'pt', 'eta', 'energy', 'charge'}
    selected = []
    for event in events:
        if set(event) != required or not isinstance(event['id'], str):
            raise ValueError()
        if any((not isinstance(event[k], numbers.Real) or isinstance(event[k], bool) for k in required - {'id'})):
            raise ValueError()
        values = {k: event[k] for k in required if k != 'id'}
        values['abs_eta'] = abs(values['eta'])
        if _evaluate(selection, values):
            value = _evaluate(score, values)
            if not isinstance(value, numbers.Real) or isinstance(value, bool):
                raise ValueError()
            selected.append((value, event['id'], event['energy']))
    selected.sort(key=lambda x: (-x[0], x[1]))
    return {'count': len(selected), 'total_energy': round(sum((x[2] for x in selected)), 2), 'top': [{'id': x[1], 'score': round(x[0], 3)} for x in selected[:limit]]}

