import csv
import datetime
import os
import tempfile
HEADERS = ['booking_id', 'couple', 'date', 'guests', 'package', 'status']
PRICES = {'classic': 120000, 'deluxe': 185000, 'premium': 260000}
STATUSES = {'confirmed', 'pending', 'cancelled'}

def load_bookings(text: str) -> list[dict]:
    if not text:
        raise ValueError('invalid input')
    try:
        rows = list(csv.reader((io_string := __import__('io').StringIO(text))))
    except (csv.Error, UnicodeError):
        raise ValueError('invalid csv')
    if not rows or rows[0] != HEADERS:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for number, row in enumerate(rows[1:], 2):
        if not row and number == len(rows):
            continue
        if len(row) != 6:
            raise ValueError('invalid row')
        values = [x.strip() for x in row]
        bid, couple, date, guests, package, status = values
        if not bid or not couple or bid in seen or (package not in PRICES) or (status not in STATUSES):
            raise ValueError('invalid value')
        try:
            datetime.date.fromisoformat(date)
            count = int(guests)
        except (ValueError, TypeError):
            raise ValueError('invalid value')
        if str(count) != guests or not 1 <= count <= 1000:
            raise ValueError('invalid guests')
        seen.add(bid)
        result.append({'booking_id': bid, 'couple': couple, 'date': date, 'guests': count, 'package': package, 'status': status})
    return sorted(result, key=lambda x: (x['date'], x['booking_id']))

def summarize_bookings(text: str) -> dict[str, dict[str, int]]:
    result = {}
    for booking in load_bookings(text):
        if booking['status'] == 'confirmed':
            month = booking['date'][:7]
            value = result.setdefault(month, {'bookings': 0, 'guests': 0, 'revenue': 0})
            value['bookings'] += 1
            value['guests'] += booking['guests']
            value['revenue'] += PRICES[booking['package']]
    return result

def export_bookings(text: str, destination: str) -> int:
    bookings = load_bookings(text)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.bookings-')
    try:
        with os.fdopen(fd, 'w', newline='') as f:
            writer = csv.writer(f, lineterminator='\n')
            writer.writerow(HEADERS)
            for b in bookings:
                writer.writerow([b[h] for h in HEADERS])
        os.replace(temporary, destination)
        return len(bookings)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise

