            count = int(guests)
        except (ValueError, TypeError):
            raise ValueError('invalid value')
        if str(count) != guests or not 1 <= count <= 1000:
            raise ValueError('invalid guests')
        seen.add(bid)
        result.append({'booking_id': bid, 'couple': couple, 'date': date, 'guests': count, 'package': package, 'status': status})
    return sorted(result, key=lambda x: (x['date'], x['booking_id']))

def summarize_bookings(text: str) -> dict[str, dict[str, int]]:
    result = {}
    for booking in load_bookings(text):
        if booking['status'] == 'confirmed':
            month = booking['date'][:7]
            value = result.setdefault(month, {'bookings': 0, 'guests': 0, 'revenue': 0})
            value['bookings'] += 1
            value['guests'] += booking['guests']
            value['revenue'] += PRICES[booking['package']]
    return result

def export_bookings(text: str, destination: str) -> int:
    bookings = load_bookings(text)
    parent = os.path.dirname(os.path.abspath(destination))
    temporary = tempfile.mktemp(dir=parent, prefix='.bookings-')
    try:
        with open(temporary, 'w', newline='') as f:
            writer = csv.writer(f, lineterminator='\n')
            writer.writerow(HEADERS)
            for b in bookings:
                writer.writerow([b[h] for h in HEADERS])
        os.replace(temporary, destination)
        return len(bookings)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise

