import csv
import io
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _allowed(requester, tenant, owner):
    return requester['tenant_id'] == tenant and (requester['id'] == owner or 'publisher_admin' in requester.get('roles', []))

def generate_royalty_statement(requester: dict, book: dict, sales_csv: str, rate_table: dict) -> dict:
    try:
        if not _allowed(requester, book['tenant_id'], book['owner_id']):
            raise PermissionError()
        bid, title = (book['id'], book['title'])
        list(requester['roles'])
    except KeyError:
        raise ValueError()
    try:
        rows = list(csv.reader(io.StringIO(sales_csv), strict=True))
    except csv.Error:
        raise ValueError()
    header = ['date', 'units', 'price', 'territory']
    if not rows or rows[0] != header or len(set(rows[0])) != len(rows[0]):
        raise ValueError()
    groups = {}
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError()
        try:
            d = date.fromisoformat(row[0])
            if not date(2000, 1, 1) <= d <= date(2100, 12, 31):
                raise ValueError()
            units = int(row[1])
            if units < 0 or str(units) != row[1]:
                raise ValueError()
            raw_price = row[2].replace(',', '')
            price = Decimal(raw_price)
            if price < 0 or price.as_tuple().exponent < -2:
                raise ValueError()
            if row[3] not in rate_table:
                raise ValueError()
            rate = Decimal(str(rate_table[row[3]]))
            if not 0 <= rate <= 100:
                raise ValueError()
            cents = int((price * 100).to_integral_exact())
            gross = units * cents
            royalty = int((Decimal(gross) * rate / 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            if gross and rate and (royalty == 0):
                royalty = 1
        except (ValueError, InvalidOperation, ArithmeticError, KeyError):
            raise ValueError()
        m = d.strftime('%Y-%m')
        g = groups.setdefault(m, [0, 0, 0])
        g[0] += units
        g[1] += gross
        g[2] += royalty
    months = [{'month': m, 'units': v[0], 'gross_cents': v[1], 'royalty_cents': v[2]} for m, v in sorted(groups.items())]
    return {'book_id': bid, 'title': title, 'currency': 'USD', 'months': months, 'total_units': sum((x['units'] for x in months)), 'total_gross_cents': sum((x['gross_cents'] for x in months)), 'total_royalty_cents': sum((x['royalty_cents'] for x in months))}

def approve_payout(requester: dict, payout: dict, ledger: list[dict]) -> dict:
    try:
        if not _allowed(requester, payout['tenant_id'], payout['recipient_id']):
            raise PermissionError()
        if payout['status'] != 'pending' or not isinstance(payout['amount_cents'], int) or isinstance(payout['amount_cents'], bool) or (payout['amount_cents'] <= 0):
            raise ValueError()
        if any((x.get('payout_id') == payout['payout_id'] for x in ledger)):
            raise ValueError()
        return {**payout, 'status': 'approved', 'approved_by': requester['id']}
    except KeyError:
        raise ValueError()

