import zipfile

def deploy_keys(archive_path: str, base_dir: str, environment: str, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid pagination')
    with zipfile.ZipFile(archive_path) as zf:
        try:
            records = json.loads(zf.read('manifest.json').decode('utf-8'))
        except (KeyError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError('invalid manifest') from exc
        if not isinstance(records, list):
            raise ValueError('invalid manifest')
        selected = []
        for item in records:
            if not isinstance(item, dict):
                raise ValueError('invalid record')
            keys = ('id', 'label', 'file', 'environment', 'active', 'created_at', 'scopes')
            if any((k not in item for k in keys)):
                raise ValueError('invalid record')
            if not isinstance(item['id'], str) or not item['id'] or (not isinstance(item['label'], str)) or (not isinstance(item['file'], str)) or (not item['file']) or (not isinstance(item['environment'], str)) or (not isinstance(item['active'], bool)) or (not isinstance(item['created_at'], str)) or (not isinstance(item['scopes'], list)) or (not all((isinstance(x, str) for x in item['scopes']))):
                raise ValueError('invalid record')
            if item['environment'] == environment and item['active']:
                selected.append(item)
        selected.sort(key=lambda x: (x['created_at'], x['id']), reverse=False)
        selected.sort(key=lambda x: x['created_at'], reverse=True)
        start = (page - 1) * page_size
        selected = selected[start:start + page_size]
        base = Path(base_dir).resolve()
        for item in selected:
            target = (base / item['file']).resolve()
            try:
                if os.path.commonpath((str(base), str(target))) != str(base):
                    raise ValueError('invalid file path')
            except ValueError:
                raise ValueError('invalid file path')
            try:
                data = zf.read(item['file'])
            except KeyError as exc:
                raise ValueError('missing archive member') from exc
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)
        return [{'id': x['id'], 'label': x['label'], 'environment': x['environment'], 'created_at': x['created_at'], 'scopes': sorted(x['scopes']), 'scope_count': len(x['scopes'])} for x in selected]

