from lxml import etree

def _read(xml_text):
    try:
        parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'responses':
        raise ValueError('invalid root')
    wave = root.get('wave')
    expected_text = root.get('expected')
    if not wave or not expected_text:
        raise ValueError('missing document attributes')
    try:
        expected = int(expected_text)
    except Exception as exc:
        raise ValueError('invalid expected') from exc
    if expected < 1:
        raise ValueError('invalid expected')
    records = []
    seen_ids = set()
    for person in root:
        if person.tag != 'respondent':
            raise ValueError('invalid respondent')
        ident, segment = (person.get('id'), person.get('segment'))
        if not ident or not segment or ident in seen_ids:
            raise ValueError('invalid respondent')
        seen_ids.add(ident)
        questions = set()
        for answer in person:
            if answer.tag != 'answer':
                raise ValueError('invalid answer')
            question = answer.get('question')
            if not question or question in questions:
                raise ValueError('invalid question')
            questions.add(question)
            try:
                value = int(answer.get('value'))
                duration = int(answer.get('duration'))
            except Exception as exc:
                raise ValueError('invalid answer') from exc
            if not 1 <= value <= 5 or duration < 0:
                raise ValueError('invalid answer')
            records.append({'respondent': ident, 'segment': segment, 'question': question, 'value': value, 'duration': duration})
    records.sort(key=lambda item: (item['respondent'], item['question']))
    return {'wave': wave, 'expected': expected, 'records': records}

def parse_panel(xml_text: str) -> dict:
    return _read(xml_text)

def summarize_panel(xml_text: str, window: int=2) -> dict:
    if isinstance(window, bool) or not isinstance(window, int) or window < 1:
        raise ValueError('invalid window')
    data = _read(xml_text)
    grouped = {}
    for record in data['records']:
        grouped.setdefault(record['segment'], []).append(record)
    segments = {}
    for name in sorted(grouped):
        rows = grouped[name]
        people = {row['respondent'] for row in rows}
        complete = sum((sum((row['respondent'] == person for row in rows)) == data['expected'] for person in people))
        rolling = [round(sum((item['duration'] for item in rows[max(0, i - window + 1):i + 1])) / min(window, i + 1), 2) for i in range(len(rows))]
        segments[name] = {'respondents': len(people), 'answers': len(rows), 'mean_score': round(sum((row['value'] for row in rows)) / len(rows), 2), 'completion_rate': round(complete / len(people), 2), 'rolling_duration': rolling}
    return {'wave': data['wave'], 'segments': segments}

