_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
_RANK = {'minor': 0, 'major': 1, 'total': 2}

def generate_assessment_token(length: int=24) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 8 <= length <= 64):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def _split_line(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_damage_events(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split_line(raw)
        if len(fields) != 5 or any((field == '' for field in fields)):
            raise ValueError('invalid record')
        timestamp, vehicle, part, severity, cost = fields
        if not timestamp.isdigit() or severity not in _RANK:
            raise ValueError('invalid field')
        if not re.fullmatch('\\d+(?:\\.\\d{1,2})?', cost):
            raise ValueError('invalid cost')
        whole, _, fraction = cost.partition('.')
        cents = int(whole) * 100 + int((fraction + '00')[:2])
        result.append({'timestamp': int(timestamp), 'vehicle_id': vehicle, 'part': part, 'severity': severity, 'cost_cents': cents})
    return sorted(result, key=lambda e: (e['timestamp'], e['vehicle_id'], e['part']))

