        item['total_cost_cents'] += event['cost_cents']
        if _RANK[event['severity']] > _RANK[item['highest_severity']]:
            item['highest_severity'] = event['severity']
        item['latest_timestamp'] = max(item['latest_timestamp'], event['timestamp'])
        old = item['parts'].get(event['part'], 'minor')
        if _RANK[event['severity']] > _RANK[old]:
            item['parts'][event['part']] = event['severity']
        else:
            item['parts'].setdefault(event['part'], old)
    output = {}
