import csv
import datetime as dt
import os
from pathlib import Path
import zipfile
_HEADER = ['child_id', 'child_name', 'date', 'check_in', 'check_out', 'room']

def extract_attendance_archive(archive_path: str, base_dir: str) -> list[str]:
    base = Path(base_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    result = []
    with zipfile.ZipFile(archive_path) as z:
        for info in z.infolist():
            if info.is_dir():
                continue
            target = (base / info.filename).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('archive member is outside base directory')
            target.parent.mkdir(parents=True, exist_ok=True)
            with z.open(info) as source, open(target, 'wb') as dest:
                while True:
                    chunk = source.read(65536)
                    if not chunk:
                        break
                    dest.write(chunk)
            result.append(info.filename)
    return sorted(result)

def _date(value):
    try:
        return dt.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _minutes(start, end):
    try:
        a = dt.time.fromisoformat(start)
        b = dt.time.fromisoformat(end)
    except (TypeError, ValueError):
        raise ValueError('invalid time')
    x = a.hour * 60 + a.minute
    y = b.hour * 60 + b.minute
    if y <= x:
        raise ValueError('check-out must be later')
    return y - x

def summarize_attendance(base_dir: str, week_start: str) -> list[dict]:
    first = _date(week_start)
    last = first + dt.timedelta(days=6)
    groups = {}
    files = sorted(Path(base_dir).rglob('*.csv'))
    for path in files:
        with path.open(newline='') as handle:
            reader = csv.reader(handle)
            try:
                if next(reader) != _HEADER:
                    raise ValueError('invalid header')
            except StopIteration:
                raise ValueError('invalid header')
            for row in reader:
                if len(row) != 6:
                    raise ValueError('invalid row')
                child, _, dates, start, end, room = row
                day = _date(dates)
                minutes = _minutes(start, end)
                if first <= day <= last:
                    item = groups.setdefault(day, {'children': [], 'seen': set(), 'total_minutes': 0, 'rooms': {}})
                    if child not in item['seen']:
                        item['seen'].add(child)
                        item['children'].append(child)
                    item['total_minutes'] += minutes
                    item['rooms'][room] = item['rooms'].get(room, 0) + 1
    output = []
    for day in sorted(groups):
        item = groups[day]
        output.append({'date': day.isoformat(), 'children': item['children'], 'total_minutes': item['total_minutes'], 'rooms': dict(sorted(item['rooms'].items()))})
    return output

