import csv
import datetime
import os
import tempfile

def _validate(record):
    if set(record) != {'guide', 'date', 'guests', 'duration', 'status'}:
        raise ValueError('invalid booking')
    if not isinstance(record['guide'], str) or not record['guide'].strip():
        raise ValueError('invalid booking')
    if not isinstance(record['date'], str):
        raise ValueError('invalid booking')
    try:
        value = datetime.date.fromisoformat(record['date'])
    except Exception as exc:
        raise ValueError('invalid booking') from exc
    if value.isoformat() != record['date']:
        raise ValueError('invalid booking')
    if isinstance(record['guests'], bool) or not isinstance(record['guests'], int) or record['guests'] <= 0:
        raise ValueError('invalid booking')
    if isinstance(record['duration'], bool) or not isinstance(record['duration'], int) or record['duration'] <= 0:
        raise ValueError('invalid booking')
    if record['status'] not in ('confirmed', 'cancelled'):
        raise ValueError('invalid booking')

def parse_booking_text(text: str) -> list[dict]:
    rows = list(csv.reader(text.splitlines()))
    rows = [row for row in rows if any((field.strip() for field in row))]
    if not rows or rows[0] != ['guide', 'date', 'guests', 'duration', 'status']:
        raise ValueError('invalid input')
    result = []
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid input')
        record = {'guide': row[0].strip(), 'date': row[1].strip(), 'guests': row[2].strip(), 'duration': row[3].strip(), 'status': row[4].strip()}
        try:
            record['guests'] = int(record['guests'])
            record['duration'] = int(record['duration'])
        except Exception as exc:
            raise ValueError('invalid input') from exc
        _validate(record)
        result.append(record)
    return result

def summarize_bookings(bookings: list[dict]) -> list[dict]:
    groups = {}
    for record in bookings:
        _validate(record)
        if record['status'] == 'confirmed':
            key = (record['date'], record['guide'].strip())
            item = groups.setdefault(key, {'guide': key[1], 'date': key[0], 'bookings': 0, 'guests': 0, 'total_minutes': 0})
            item['bookings'] += 1
            item['guests'] += record['guests']
            item['total_minutes'] += record['guests'] * record['duration']
    return [groups[key] for key in sorted(groups)]

def export_itinerary(bookings: list[dict], destination: str) -> list[dict]:
    summaries = summarize_bookings(bookings)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['guide', 'date', 'bookings', 'guests', 'total_minutes'])
            for row in summaries:
                writer.writerow([row['guide'], row['date'], row['bookings'], row['guests'], row['total_minutes']])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return summaries

