import datetime
import secrets
ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def parse_inventory(text: str) -> list[dict]:
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip() or line.lstrip().startswith('#'):
            continue
        fields, current, escaped = ([], [], False)
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current).strip())
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('unterminated escape')
        fields.append(''.join(current).strip())
        if len(fields) != 6:
            raise ValueError('wrong field count')
        freezer, shelf, slot, sample, quantity, expiry = fields
        if not all((freezer, shelf, slot, sample)):
            raise ValueError('empty field')
        try:
            quantity = int(quantity)
            datetime.date.fromisoformat(expiry)
        except Exception as exc:
            raise ValueError('invalid record') from exc
        if quantity <= 0:
            raise ValueError('invalid quantity')
        result.append({'freezer': freezer, 'shelf': shelf, 'slot': slot, 'sample': sample, 'quantity': quantity, 'expiry': expiry})
    return result

def generate_code(length: int=12) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or length <= 0:
        raise ValueError('invalid length')
    return ''.join((secrets.choice(ALPHABET) for _ in range(length)))

def reserve_samples(records: list[dict], requests: list[dict]) -> dict:
    checked = []
    for index, request in enumerate(requests):
        if not isinstance(request, dict) or not isinstance(request.get('sample'), str) or (not request['sample']):
            raise ValueError('invalid request')
        quantity = request.get('quantity')
        priority = request.get('priority', 0)
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        if isinstance(priority, bool) or not isinstance(priority, int):
            raise ValueError('invalid priority')
        checked.append((index, request['sample'], quantity, priority))
    available = [dict(record) for record in records]
    allocations = []
    for index, sample, needed, priority in sorted(checked, key=lambda x: (-x[3], x[0])):
        candidates = sorted((r for r in available if r['sample'] == sample and r['quantity'] > 0), key=lambda r: (r['expiry'], r['freezer'], r['shelf'], r['slot']))
        items = []
        for record in candidates:
            amount = min(needed, record['quantity'])
            if amount:
                record['quantity'] -= amount
                needed -= amount
                items.append({k: record[k] for k in ('freezer', 'shelf', 'slot', 'expiry')} | {'quantity': amount})
            if not needed:
                break
        if needed:
            raise ValueError('insufficient stock')
        allocations.append({'request_index': index, 'sample': sample, 'items': items})
    for original, updated in zip(records, available):
        original['quantity'] = updated['quantity']
    return {'code': generate_code(), 'allocations': allocations}

