def count_request_lines(file_paths: list[str]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for path in file_paths:
        if path in counts:
            continue
        result = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=False)
        if result.returncode != 0:
            raise FileNotFoundError(path)
        fields = result.stdout.split()
        if not fields:
            raise FileNotFoundError(path)
        counts[path] = int(fields[0])
    return counts

