from datetime import datetime, timezone
_STATUSES = ('AVAILABLE', 'RENTED', 'MAINTENANCE')

def _split(line):
    out = []
    cur = []
    esc = False
    for ch in line:
        if esc:
            if ch not in '|\\':
                raise ValueError('invalid escape')
            cur.append(ch)
            esc = False
        elif ch == '\\':
            esc = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if esc:
        raise ValueError('trailing escape')
    out.append(''.join(cur))
    return out

def _time(value):
    try:
        p = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except Exception as e:
        raise ValueError('invalid timestamp') from e
    if p.tzinfo is None or p.utcoffset() != timezone.utc.utcoffset(p):
        raise ValueError('timestamp must be UTC')
    return p

def parse_event(line):
    p = _split(line)
    if len(p) != 5 or not p[0] or (not p[4]) or (p[2] not in _STATUSES):
        raise ValueError('invalid event')
    _time(p[1])
    try:
        n = int(p[3])
    except Exception as e:
        raise ValueError('invalid odometer') from e
    if n < 0 or str(n) != p[3]:
        raise ValueError('invalid odometer')
    return {'vehicle_id': p[0], 'timestamp': p[1], 'status': p[2], 'odometer': n, 'location': p[4]}

def _key(config):
    v = config.get('signing_key') if config is not None else None
    if not v:
        v = os.environ.get('FLEET_SIGNING_KEY')
    if not v:
        raise ValueError('signing key is missing')
    return v.encode()

def _canonical(x):
    return json.dumps(x, sort_keys=True, separators=(',', ':')).encode()

def build_fleet_report(events, as_of, config=None):
    cutoff = _time(as_of)
    latest = {}
    for e in events:
        if not isinstance(e, dict):
            raise ValueError('invalid event')
        try:
            v, s, st, o, l = (e['vehicle_id'], e['timestamp'], e['status'], e['odometer'], e['location'])
            t = _time(s)
        except (KeyError, TypeError) as x:
            raise ValueError('invalid event') from x
        if not isinstance(v, str) or not v or (not isinstance(s, str)) or (not isinstance(st, str)) or (st not in _STATUSES) or (not isinstance(o, int)) or isinstance(o, bool) or (o < 0) or (not isinstance(l, str)) or (not l):
            raise ValueError('invalid event')
