    vehicles = [latest[k][1] for k in sorted(latest)]
    report = {'as_of': as_of, 'vehicles': vehicles, 'status_counts': {s: sum((v['status'] == s for v in vehicles)) for s in _STATUSES}, 'total_odometer': sum((v['odometer'] for v in vehicles))}
    report['signature'] = hmac.new(_key(config), _canonical(report), hashlib.sha256).hexdigest()
    return report

