    if not isinstance(report, dict) or not isinstance(report.get('signature'), str):
        raise ValueError('invalid report')
    try:
        payload = {k: report[k] for k in ('as_of', 'vehicles', 'status_counts', 'total_odometer')}
    except KeyError as e:
        raise ValueError('invalid report') from e
    return hmac.compare_digest(hmac.new(_key(config), _canonical(payload), hashlib.sha256).hexdigest(), report['signature'])

