import hashlib
import hmac
import re

def make_signature(key: bytes, fields: list[str]) -> str:
    return hmac.new(key, ','.join(fields).encode('utf-8'), hashlib.sha256).hexdigest()

def parse_observation(line: str, keys: dict[str, bytes], now: int) -> dict:
    parts = line.split(',')
    if len(parts) != 8:
        raise ValueError('invalid field count')
    key_id, ts_s, obsid, ra_s, dec_s, dur_s, pri_s, signature = parts
    if key_id not in keys or not signature:
        raise ValueError('invalid key or signature')
    expected = make_signature(keys[key_id], parts[:7])
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        timestamp = int(ts_s)
        ra = float(ra_s)
        dec = float(dec_s)
        duration = int(dur_s)
        priority = int(pri_s)
    except (TypeError, ValueError):
        raise ValueError('invalid value')
    if abs(timestamp - now) > 300:
        raise ValueError('timestamp outside tolerance')
    if not re.fullmatch('[A-Za-z0-9_-]+', obsid):
        raise ValueError('invalid observation id')
    if not 0 <= ra < 360 or not -90 <= dec <= 90:
        raise ValueError('invalid coordinates')
    if not 1 <= duration <= 120 or not 0 <= priority <= 9:
        raise ValueError('invalid scheduling values')
    return {'key_id': key_id, 'timestamp': timestamp, 'observation_id': obsid, 'ra': ra, 'dec': dec, 'duration': duration, 'priority': priority}

def schedule_observations(lines: list[str], keys: dict[str, bytes], now: int, horizon: int) -> list[tuple[str, int, int, int]]:
    if not isinstance(horizon, int) or isinstance(horizon, bool) or horizon < 0:
        raise ValueError('invalid horizon')
    candidates = []
    for line in lines:
        item = parse_observation(line, keys, now)
        start = item['timestamp']
        end = start + item['duration']
        if start >= now and end <= now + horizon:
            candidates.append(item)
    candidates.sort(key=lambda x: (-x['priority'], x['timestamp'], x['observation_id']))
    accepted = []
    for item in candidates:
        start = item['timestamp']
        end = start + item['duration']
        if all((end <= a or start >= b for _, a, b, _ in accepted)):
            accepted.append((item['observation_id'], start, end, item['priority']))
    accepted.sort(key=lambda x: (x[1], -x[3], x[0]))
    return accepted

