import json
import os
import zipfile

def _time(value):
    if not isinstance(value, str):
        raise ValueError()
    try:
        text = value[:-1] + '+00:00' if value.endswith('Z') else value
        result = datetime.datetime.fromisoformat(text)
        if result.tzinfo is None:
            raise ValueError()
        return result.astimezone(datetime.timezone.utc)
    except (TypeError, ValueError):
        raise ValueError()

def build_consent_report(base_dir: str, archive_path: str, subject_id: str, as_of: str) -> dict:
    cutoff = _time(as_of)
    incoming = os.path.join(base_dir, 'incoming')
    os.makedirs(incoming, exist_ok=True)
    try:
        with zipfile.ZipFile(archive_path) as archive:
            root = os.path.realpath(incoming)
            for info in archive.infolist():
                target = os.path.realpath(os.path.join(incoming, info.filename))
                if os.path.commonpath((root, target)) != root:
                    raise ValueError()
                if info.is_dir():
                    os.makedirs(target, exist_ok=True)
                    continue
                os.makedirs(os.path.dirname(target), exist_ok=True)
                with archive.open(info) as source, open(target, 'wb') as dest:
                    dest.write(source.read())
    except (zipfile.BadZipFile, OSError, ValueError):
        raise ValueError()
    chosen = {}
    for directory, _, names in os.walk(incoming):
        for name in names:
            if not name.endswith('.jsonl'):
                continue
            try:
                handle = open(os.path.join(directory, name), encoding='utf-8')
            except OSError:
                continue
            with handle:
                for line in handle:
                    if not line.strip():
                        continue
                    try:
                        item = json.loads(line)
                        if not isinstance(item, dict):
                            continue
                        if any((not isinstance(item.get(k), str) for k in ('subject', 'purpose', 'decision', 'timestamp', 'source'))):
                            continue
                        if item['subject'] != subject_id or not item['purpose'] or item['decision'] not in ('grant', 'deny'):
                            continue
                        moment = _time(item['timestamp'])
                        if moment > cutoff:
                            continue
                        if 'expires' in item:
                            expiry = _time(item['expires'])
                            if expiry <= cutoff:
                                continue
                        old = chosen.get(item['purpose'])
                        if old is None or (moment, item['source']) > (old[0], old[1]['source']):
                            chosen[item['purpose']] = (moment, item)
                    except (ValueError, TypeError, KeyError, json.JSONDecodeError):
                        continue
    decisions = []
    for purpose in sorted(chosen):
        item = chosen[purpose][1]
        decisions.append({k: item[k] for k in ('purpose', 'decision', 'timestamp', 'source')})
    result = {'subject': subject_id, 'decisions': decisions}
    os.makedirs(base_dir, exist_ok=True)
    with open(os.path.join(base_dir, 'report.json'), 'w', encoding='utf-8') as handle:
        json.dump(result, handle, sort_keys=True, separators=(',', ':'))
        handle.write('\n')
    return result

