from decimal import Decimal, ROUND_HALF_UP
import math

def ingest_rates(requester: dict, observations: list[dict], catalog: dict) -> list[dict]:
    if requester.get('tenant_id') != catalog.get('tenant_id') or not (requester.get('role') in {'owner', 'ingestion_admin'} or requester.get('user_id') == catalog.get('owner_id')):
        raise PermissionError('not authorized')
    if not isinstance(observations, list):
        raise ValueError('observations must be a list')
    parsed = []
    groups = {}
    for item in observations:
        if not isinstance(item, dict):
            raise ValueError('invalid observation')
        base, quote = (item.get('base'), item.get('quote'))
        rate, stamp, source = (item.get('rate'), item.get('observed_at'), item.get('source'))
        if not isinstance(base, str) or not isinstance(quote, str) or len(base) != 3 or (len(quote) != 3) or (not base.isascii()) or (not quote.isascii()) or (not base.isupper()) or (not quote.isupper()) or (base == quote):
            raise ValueError('invalid pair')
        if not isinstance(rate, (int, float)) or isinstance(rate, bool) or (not math.isfinite(rate)) or (rate <= 0):
            raise ValueError('invalid rate')
        if not isinstance(stamp, str) or not stamp.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            datetime.fromisoformat(stamp[:-1] + '+00:00')
        except ValueError:
            raise ValueError('invalid timestamp')
        if not isinstance(source, str) or not source:
            raise ValueError('invalid source')
        value = Decimal(str(rate))
        rounded = value.quantize(Decimal('0.000001'), rounding=ROUND_HALF_UP)
        normalized = {'base': base, 'quote': quote, 'rate': float(rounded), 'observed_at': stamp, 'source': source}
        parsed.append(normalized)
        groups.setdefault(base + '/' + quote, []).append(value)
    catalog['rates'].extend(parsed)
    result = []
    for pair, values in groups.items():
        q = Decimal('0.000001')
        result.append({'pair': pair, 'count': len(values), 'average': float((sum(values) / len(values)).quantize(q, rounding=ROUND_HALF_UP)), 'minimum': float(min(values).quantize(q, rounding=ROUND_HALF_UP)), 'maximum': float(max(values).quantize(q, rounding=ROUND_HALF_UP))})
    result.sort(key=lambda x: (-x['count'], x['pair']))
    return result

