import sqlite3

def _like(value):
    return value.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')

def list_panels(conn: sqlite3.Connection, roof_type: str | None=None, search: str='', sort_by: str='price', descending: bool=False) -> list[dict]:
    allowed = {'id', 'name', 'watts', 'price', 'stock'}
    if sort_by not in allowed:
        raise ValueError(sort_by)
    direction = 'DESC' if descending else 'ASC'
    sql = "select id, name, watts, price, roof_type, stock from panels where (? is null or roof_type = ?) and lower(name) like lower(?) escape '\\' order by " + sort_by + ' ' + direction + ', id ' + direction
    pattern = '%' + _like(search) + '%'
    rows = conn.execute(sql, (roof_type, roof_type, pattern)).fetchall()
