import csv
import datetime
import os
import tempfile

def _timestamp(value):
    try:
        parsed = datetime.datetime.fromisoformat(value)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid timestamp') from exc
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=datetime.timezone.utc)
    return parsed.astimezone(datetime.timezone.utc)

def _validate(document):
    if not isinstance(document, dict):
        raise ValueError('invalid document')
    required = ('id', 'title', 'category', 'updated_at', 'size')
    if any((key not in document for key in required)):
        raise ValueError('invalid document')
    if isinstance(document['id'], bool) or not isinstance(document['id'], int) or document['id'] < 0:
        raise ValueError('invalid id')
    if not isinstance(document['title'], str) or not isinstance(document['category'], str):
        raise ValueError('invalid text')
    if isinstance(document['size'], bool) or not isinstance(document['size'], int) or document['size'] < 0:
        raise ValueError('invalid size')
    parsed = _timestamp(document['updated_at'])
    return parsed

def export_documents(documents: list[dict], category: str | None, page: int, page_size: int) -> bytes:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    prepared = []
    for document in documents:
        timestamp = _validate(document)
        if category is None or document['category'] == category:
            prepared.append((timestamp, document))
    prepared.sort(key=lambda item: (-item[0].timestamp(), item[1]['id']))
    start = (page - 1) * page_size
    selected = [item[1] for item in prepared[start:start + page_size]]
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('id', 'title', 'category', 'updated_at', 'size'))
            for document in selected:
                writer.writerow(tuple((document[key] for key in ('id', 'title', 'category', 'updated_at', 'size'))))
        with open(path, 'rb') as handle:
            return handle.read()
    finally:
        os.unlink(path)

