import hashlib
import hmac
import os

def create_operator_record(username: str, password: str) -> dict:
    if not isinstance(username, str) or not username:
        raise ValueError('invalid username')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    salt = os.urandom(16).hex()
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt), 100000).hex()
    return {'username': username, 'salt': salt, 'password_digest': digest}

def verify_operator_password(record: dict, password: str) -> bool:
    if not all((key in record for key in ('username', 'salt', 'password_digest'))):
        raise ValueError('invalid record')
    if not all((isinstance(record[key], str) for key in ('username', 'salt', 'password_digest'))):
        raise ValueError('invalid record')
    if not isinstance(password, str):
        return False
    try:
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(record['salt']), 100000).hex()
    except ValueError:
        raise ValueError('invalid record')
    return hmac.compare_digest(actual, record['password_digest'])

