from lxml import etree
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def parse_variance_requests(xml_text: str) -> list[dict]:
    try:
        root = etree.fromstring(xml_text.encode() if isinstance(xml_text, str) else xml_text, etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'requests' or not root.getchildren():
        raise ValueError('invalid root')
    result, seen = ([], set())
    for node in root:
        if node.tag != 'request' or node.get('id') is None or node.get('id').strip() in seen:
            raise ValueError('invalid request')
        attrs = {k: node.get(k) for k in ('id', 'district', 'status', 'submitted')}
        if any((v is None or not v.strip() for v in attrs.values())) or attrs['status'].strip() not in ('pending', 'approved', 'denied'):
            raise ValueError('invalid attributes')
        submitted = attrs['submitted'].strip()
        _day(submitted)
        children = list(node)
        apps = [x for x in children if x.tag == 'applicant']
        props = [x for x in children if x.tag == 'property']
        vars_ = [x for x in children if x.tag == 'variance']
        if len(apps) != 1 or len(props) != 1 or len(vars_) != 1 or (len(children) != 3):
            raise ValueError('invalid children')
        applicant = (apps[0].text or '').strip()
        addresses = [x for x in props[0] if x.tag == 'address']
        address = (addresses[0].text or '').strip() if len(addresses) == 1 else ''
        v = vars_[0]
        if any((x is not None and (not x.strip()) for x in (v.get('type'), v.get('amount'), v.get('unit')))) or any((v.get(x) is None for x in ('type', 'amount', 'unit'))):
            raise ValueError('invalid variance')
        try:
            amount = float(Decimal(v.get('amount').strip()))
            if amount < 0:
                raise ValueError
        except (InvalidOperation, ValueError):
            raise ValueError('invalid amount')
        notes = [x for x in v if x.tag == 'notes']
        if len(notes) > 1 or any((x.tag != 'notes' for x in v)):
            raise ValueError('invalid notes')
        notes_text = (notes[0].text or '').strip() if notes else ''
        if not applicant or not address or (not notes_text and notes):
            raise ValueError('empty text')
        seen.add(attrs['id'].strip())
        result.append({'id': attrs['id'].strip(), 'district': attrs['district'].strip(), 'status': attrs['status'].strip(), 'submitted': submitted, 'applicant': applicant, 'address': address, 'variance_type': v.get('type').strip(), 'amount': amount, 'unit': v.get('unit').strip(), 'notes': notes_text})
    return result

def rank_requests(requests: list[dict], as_of: str) -> list[str]:
    today = _day(as_of)
    order = {'pending': 0, 'approved': 1, 'denied': 2}
    rows = []
    for r in requests:
        try:
            amount = Decimal(str(r['amount']))
            submitted = _day(r['submitted'])
            status = r['status']
            if status not in order:
                raise ValueError
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid request')
        rows.append((order[status], -(today - submitted).days, -amount, r['id']))
    return [x[3] for x in sorted(rows)]

def district_totals(requests: list[dict]) -> dict[str, dict]:
    groups = {}
    for r in requests:
        try:
            d = r['district']
            submitted = _day(r['submitted'])
            amount = Decimal(str(r['amount']))
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid request')
        g = groups.setdefault(d, {'count': 0, 'pending': Decimal('0'), 'latest': submitted})
        g['count'] += 1
        if r['status'] == 'pending':
            g['pending'] += amount
        if submitted > g['latest']:
            g['latest'] = submitted
    return {d: {'count': g['count'], 'pending_amount': float(g['pending'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'latest_submission': g['latest'].isoformat()} for d, g in sorted(groups.items())}

