from datetime import date
import secrets
_TYPES = {'O-', 'O+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+'}
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def parse_inventory(text: str) -> list[dict]:
    result = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = [x.strip() for x in raw.split('|')]
        if len(fields) != 4:
            raise ValueError('invalid inventory row')
        ident, blood, date_text, volume_text = fields
        if not ident or blood not in _TYPES or ident in seen:
            raise ValueError('invalid inventory field')
        try:
            expires = date.fromisoformat(date_text)
            volume = int(volume_text)
        except (TypeError, ValueError):
            raise ValueError('invalid inventory field')
        if volume <= 0 or str(volume) != volume_text:
            raise ValueError('invalid volume')
        seen.add(ident)
        result.append({'id': ident, 'blood_type': blood, 'expires': expires, 'volume': volume})
    return result

def _compatible(donor: str, recipient: str) -> bool:
    dabo, drh = (donor[:-1], donor[-1])
    rabo, rrh = (recipient[:-1], recipient[-1])
    abo = dabo == 'O' or dabo == rabo or (dabo in ('A', 'B') and rabo == 'AB')
    return abo and (drh == '-' or rrh == '+')

def issue_tracking_code() -> str:
    return ''.join((secrets.choice(_ALPHABET) for _ in range(12)))

def fulfill_requests(units: list[dict], requests: list[dict], today: date) -> list[dict]:
    available = list(units)
    planned = []
    for request in requests:
        rid = request.get('request_id')
        recipient = request.get('recipient')
        amount = request.get('volume')
        if not isinstance(rid, str) or recipient not in _TYPES or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount <= 0):
            raise ValueError('invalid request')
        candidates = [u for u in available if u['expires'] >= today and _compatible(u['blood_type'], recipient)]
        candidates.sort(key=lambda u: (u['expires'], u.get('donated', today), u['id']))
        chosen = []
        total = 0
        for unit in candidates:
            chosen.append(unit)
            total += unit['volume']
            if total >= amount:
                break
        if total < amount:
            raise ValueError('insufficient inventory')
        chosen_ids = {u['id'] for u in chosen}
        available = [u for u in available if u['id'] not in chosen_ids]
        planned.append({'request_id': rid, 'units': [u['id'] for u in chosen], 'volume': total, 'tracking_code': issue_tracking_code()})
    return planned

