import hashlib
import hmac
import json
from datetime import date

def _check_record(obj):
    if not isinstance(obj, dict) or set(obj) != {'facility', 'inspection_date', 'score', 'violations'}:
        raise ValueError('invalid record')
    if not isinstance(obj['facility'], str) or not obj['facility']:
        raise ValueError('invalid record')
    try:
        date.fromisoformat(obj['inspection_date'])
    except (TypeError, ValueError):
        raise ValueError('invalid record')
    if type(obj['score']) is not int or not 0 <= obj['score'] <= 100:
        raise ValueError('invalid record')
    vals = obj['violations']
    if not isinstance(vals, list) or any((not isinstance(x, str) or not x for x in vals)) or len(set(vals)) != len(vals):
        raise ValueError('invalid record')

def verify_submission(blob: str, secrets: dict[str, bytes], now: int, max_age: int=300) -> dict:
    try:
        key, stamp, supplied, payload = blob.split('|', 3)
        timestamp = int(stamp)
        secret = secrets[key]
        if abs(now - timestamp) > max_age:
            raise ValueError('expired')
        expected = hmac.new(secret, f'{key}|{stamp}|{payload}'.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, supplied):
            raise ValueError('digest')
        obj = json.loads(payload)
        _check_record(obj)
        return obj
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        raise ValueError('invalid submission')

def summarize_inspections(records: list[dict], start_date: str, end_date: str) -> list[dict]:
    try:
        begin = date.fromisoformat(start_date)
        finish = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid dates')
    if begin > finish:
        raise ValueError('invalid dates')
    groups = {}
    for obj in records:
        _check_record(obj)
        day = date.fromisoformat(obj['inspection_date'])
        if begin <= day <= finish:
            groups.setdefault(obj['facility'], []).append(obj)
    result = []
    for facility, items in groups.items():
        violations = set().union(*(set(x['violations']) for x in items))
        average = round(sum((x['score'] for x in items)) / len(items), 2)
        result.append({'facility': facility, 'inspections': len(items), 'average_score': average, 'violations': len(violations)})
    result.sort(key=lambda x: (-x['violations'], x['average_score'], x['facility']))
    return result

