import csv
import os
import zipfile

def extract_receipt_csvs(archive_path: str, output_dir: str) -> list[str]:
    with zipfile.ZipFile(archive_path) as zf:
        names = [x for x in zf.namelist() if x.startswith('receipts/') and x.endswith('.csv') and (not x.endswith('/'))]
        if len(names) != len(set(names)):
            raise ValueError('duplicate archive member')
        root = os.path.realpath(output_dir)
        for name in sorted(names):
            candidate = os.path.realpath(os.path.join(root, name))
            try:
                common = os.path.commonpath([root, candidate])
            except ValueError:
                raise ValueError('invalid archive member')
            if common != root:
                raise ValueError('invalid archive member')
            os.makedirs(os.path.dirname(candidate), exist_ok=True)
            with zf.open(name) as source, open(candidate, 'wb') as target:
                target.write(source.read())
        return sorted(names)

def summary_receipts(output_dir: str) -> list[dict[str, object]]:
    files = []
    for root, dirs, names in os.walk(output_dir):
        dirs.sort()
        for name in sorted(names):
            if name.endswith('.csv'):
                files.append(os.path.join(root, name))
    data = {}
    header = ['receipt_id', 'sku', 'quantity', 'unit_price_cents']
    for path in sorted(files):
        with open(path, newline='') as f:
            rows = list(csv.reader(f))
        if not rows or rows[0] != header or len(rows) == 1:
            raise ValueError('invalid receipt file')
        for row in rows[1:]:
            if len(row) != 4:
                raise ValueError('invalid receipt row')
            rid, sku = (row[0].strip(), row[1].strip())
            if not rid or not sku:
                raise ValueError('invalid receipt row')
            try:
                quantity = int(row[2].strip())
                price = int(row[3].strip())
            except ValueError:
                raise ValueError('invalid receipt row')
            if quantity < 0 or price < 0:
                raise ValueError('invalid receipt row')
            receipt = data.setdefault(rid, {})
            item = receipt.setdefault(sku, [0, 0])
            item[0] += quantity
            item[1] += quantity * price
    result = []
    for rid in sorted(data):
        items = [{'sku': sku, 'units': data[rid][sku][0], 'cents': data[rid][sku][1]} for sku in sorted(data[rid])]
        result.append({'receipt_id': rid, 'total_units': sum((x['units'] for x in items)), 'total_cents': sum((x['cents'] for x in items)), 'items': items})
    return result

