from lxml import etree

def summarize_subscriptions(xml_text: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid pagination')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'feed':
        raise ValueError('invalid root')
    seen = set()
    rows = []
    total = Decimal('0')
    try:
        for sub in root.findall('subscription'):
            sid = sub.get('id')
            status = sub.get('status')
            customer_node = sub.find('customer')
            if not sid or sid in seen or status not in ('active', 'cancelled') or (customer_node is None):
                raise ValueError('invalid subscription')
            seen.add(sid)
            customer = (customer_node.text or '').strip()
            if not customer:
                raise ValueError('invalid customer')
            if status != 'active':
                continue
            quantity = 0
            value = Decimal('0')
            deliveries = sub.findall('delivery')
            for delivery in deliveries:
                title = delivery.find('title')
                qty = delivery.find('quantity')
                price = delivery.find('unit_price')
                if title is None or qty is None or price is None or (not (title.text or '').strip()):
                    raise ValueError('invalid delivery')
                q = int((qty.text or '').strip())
                p = Decimal((price.text or '').strip())
                if q <= 0 or p < 0:
                    raise ValueError('invalid amount')
                quantity += q
                value += Decimal(q) * p
            rows.append((customer.lower(), sid, {'id': sid, 'customer': customer, 'quantity': quantity, 'value': value}))
            total += value
    except (ValueError, InvalidOperation, TypeError) as exc:
        raise ValueError('invalid content') from exc
    rows.sort(key=lambda row: (row[0], row[1]))
    start = (page - 1) * page_size
    selected = []
    for _, _, item in rows[start:start + page_size]:
        selected.append({**item, 'value': str(item['value'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))})
    return {'total': len(rows), 'total_value': str(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'items': selected}

