from pathlib import Path

def write_change_order_report(base_dir: str, relative_name: str, project: str, change_orders: list[dict], page: int=1, page_size: int=10) -> str:
    if not isinstance(project, str) or not project:
        raise ValueError('invalid project')
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid name')
    if not isinstance(change_orders, list):
        raise ValueError('invalid orders')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    for order in change_orders:
        if not isinstance(order, dict):
            raise ValueError('invalid order')
        contractor = order.get('contractor')
        amount = order.get('amount')
        status = order.get('status')
        if not isinstance(contractor, str) or not contractor:
            raise ValueError('invalid contractor')
        if not isinstance(amount, numbers.Real) or isinstance(amount, bool) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid amount')
        if status not in {'proposed', 'approved', 'rejected'}:
            raise ValueError('invalid status')
        item = groups.setdefault(contractor, [0, 0.0])
        item[0] += 1
        if status == 'approved':
            item[1] += amount
    rows = [{'contractor': name, 'change_orders': values[0], 'approved_amount': round(values[1], 2)} for name, values in groups.items()]
    rows.sort(key=lambda row: (-row['approved_amount'], row['contractor'].casefold()))
    start = (page - 1) * page_size
    report = {'project': project, 'page': page, 'page_size': page_size, 'total_contractors': len(rows), 'contractors': rows[start:start + page_size]}
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('invalid output path')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
    return str(target)

