    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def aggregate_readings(readings: list[dict], window_minutes: int=15) -> list[dict]:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes < 1 or (window_minutes > 60) or 60 % window_minutes:
        raise ValueError('invalid window')
    groups = {}
    for item in readings:
