            temp = item['temperature']
            humidity = item['humidity']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(temp, (int, float)) or isinstance(temp, bool) or (not math.isfinite(temp)):
            raise ValueError('invalid temperature')
        if not isinstance(humidity, (int, float)) or isinstance(humidity, bool) or (not math.isfinite(humidity)) or (not 0 <= humidity <= 100):
            raise ValueError('invalid humidity')
        try:
            text = stamp[:-1] + '+00:00' if isinstance(stamp, str) and stamp.endswith('Z') else stamp
            dt = datetime.fromisoformat(text)
            if dt.tzinfo is None:
                raise ValueError
            dt = dt.astimezone(timezone.utc).replace(second=0, microsecond=0)
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')
        minute = dt.minute // window_minutes * window_minutes
        start = dt.replace(minute=minute)
        groups.setdefault(start, []).append(float(temp))
