import csv
import os
import tempfile

def export_kb_articles(articles: list[dict], destination: str, category: str | None=None, page: int=1, page_size: int=50) -> dict:
    if page < 1 or page_size < 1 or page_size > 1000:
        raise ValueError('invalid pagination')
    selected = []
    for article in articles:
        required = ('id', 'title', 'category', 'status', 'updated_at', 'views')
        if any((key not in article for key in required)):
            raise ValueError('malformed article')
        if not isinstance(article['id'], int) or isinstance(article['id'], bool):
            raise ValueError('invalid id')
        if not isinstance(article['views'], int) or isinstance(article['views'], bool) or article['views'] < 0:
            raise ValueError('invalid views')
        if not isinstance(article['updated_at'], str) or not article['updated_at']:
            raise ValueError('invalid date')
        if article['status'] not in ('published', 'draft'):
            raise ValueError('invalid status')
        if article['status'] == 'published' and (category is None or article['category'] == category):
            selected.append(article)
    selected.sort(key=lambda item: (-item['views'], item['id']))
    total = len(selected)
    start = (page - 1) * page_size
    page_items = selected[start:start + page_size]
    page_count = (total + page_size - 1) // page_size
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.writer(stream)
            writer.writerow(['id', 'title', 'category', 'updated_at', 'views'])
            for article in page_items:
