import math
from datetime import date

def build_maintenance_report(records: list[dict], config: dict[str, str], start_date: str, end_date: str, page: int=1, page_size: int=20) -> dict:
    try:
        first = date.fromisoformat(start_date)
        last = date.fromisoformat(end_date)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if first > last or page < 1 or page_size < 1:
        raise ValueError('invalid range or pagination')
    key = config.get('signing_key')
    if not isinstance(key, str) or not key:
        raise ValueError('missing signing_key')
    levels = {'low': 0, 'medium': 1, 'high': 2}
    grouped = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('turbine_id'), str) or (not record['turbine_id']):
            raise ValueError('invalid record')
        try:
            record_date = date.fromisoformat(record['date'])
        except Exception as exc:
            raise ValueError('invalid record date') from exc
        hours = record.get('downtime_hours')
        severity = record.get('severity')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or (not math.isfinite(hours)) or (hours < 0) or (severity not in levels):
            raise ValueError('invalid record')
        if first <= record_date <= last:
            item = grouped.setdefault(record['turbine_id'], [0, 0.0, 'low'])
            item[0] += 1
            item[1] += hours
            if levels[severity] > levels[item[2]]:
                item[2] = severity
    complete = [{'turbine_id': n, 'incidents': v[0], 'downtime_hours': round(v[1], 2), 'highest_severity': v[2]} for n, v in grouped.items()]
    complete.sort(key=lambda x: (-x['downtime_hours'], x['turbine_id']))
    payload = {'start_date': start_date, 'end_date': end_date, 'turbines': complete}
    signature = hmac.new(key.encode(), json.dumps(payload, sort_keys=True, separators=(',', ':')).encode(), hashlib.sha256).hexdigest()
    offset = (page - 1) * page_size
    return {'turbines': complete[offset:offset + page_size], 'page': page, 'page_size': page_size, 'total_turbines': len(complete), 'signature': signature}

