import hashlib
import hmac
import os

def register_guest(guests: dict[str, str], username: str, password: str) -> None:
    if not isinstance(username, str) or not username.strip() or any((c.isspace() for c in username.strip())):
        raise ValueError('invalid username')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    name = username.strip()
    if name in guests:
        raise ValueError('duplicate username')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    guests[name] = salt.hex() + '$' + digest.hex()

def authenticate_guest(guests: dict[str, str], username: str, password: str) -> bool:
    if not isinstance(username, str) or not isinstance(password, str):
        return False
    name = username.strip()
    if name not in guests:
        return False
    try:
        salt_text, digest_text = guests[name].split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, AttributeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def reservation_report(reservations: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    totals = {}
    for item in reservations:
        try:
            campsite = item['campsite']
            nights = item['nights']
            rate = item['nightly_rate']
            status = item['status']
        except (KeyError, TypeError):
            raise ValueError('invalid reservation')
        if not isinstance(campsite, str) or not campsite:
            raise ValueError('invalid campsite')
        if isinstance(nights, bool) or not isinstance(nights, int) or nights <= 0:
            raise ValueError('invalid nights')
        if isinstance(rate, bool) or not isinstance(rate, (int, float)) or rate < 0:
            raise ValueError('invalid rate')
        if not isinstance(status, str):
            raise ValueError('invalid status')
        if status == 'confirmed':
            if campsite not in totals:
                totals[campsite] = [0, 0.0]
            totals[campsite][0] += nights
            totals[campsite][1] += nights * rate
    rows = [{'campsite': name, 'nights': value[0], 'revenue': round(value[1], 2)} for name, value in totals.items()]
    rows.sort(key=lambda row: (-row['revenue'], row['campsite']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

