import sqlite3
from datetime import date

def setup_database(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS treatments (id INTEGER PRIMARY KEY AUTOINCREMENT, property_name TEXT NOT NULL, technician TEXT NOT NULL, pesticide TEXT NOT NULL, treated_on TEXT NOT NULL, area_sq_m REAL NOT NULL, status TEXT NOT NULL)')
    conn.commit()

def add_treatment(conn: sqlite3.Connection, property_name: str, technician: str, pesticide: str, treated_on: str, area_sq_m: float, status: str) -> int:
    values = [property_name, technician, pesticide]
    if any((not isinstance(x, str) or not x.strip() for x in values)):
        raise ValueError('blank value')
    try:
        date.fromisoformat(treated_on)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if not isinstance(area_sq_m, (int, float)) or area_sq_m <= 0 or status not in {'scheduled', 'completed', 'cancelled'}:
        raise ValueError('invalid treatment')
    cur = conn.execute('INSERT INTO treatments (property_name, technician, pesticide, treated_on, area_sq_m, status) VALUES (?, ?, ?, ?, ?, ?)', (property_name.strip(), technician.strip(), pesticide.strip(), treated_on, area_sq_m, status))
    conn.commit()
    return cur.lastrowid

def find_treatments(conn: sqlite3.Connection, search: str='', status: str | None=None, sort_by: str='treated_on', descending: bool=False, limit: int | None=None, offset: int=0) -> list[dict]:
    allowed = {'treated_on': 'treated_on', 'property_name': 'property_name', 'technician': 'technician', 'area_sq_m': 'area_sq_m', 'status': 'status'}
    if sort_by not in allowed or (status is not None and status not in {'scheduled', 'completed', 'cancelled'}) or (not isinstance(offset, int)) or (offset < 0) or (limit is not None and (not isinstance(limit, int) or limit < 0)):
        raise ValueError('invalid query')
    where = []
    args = []
    if search:
        where.append('(lower(property_name) LIKE lower(?) OR lower(technician) LIKE lower(?) OR lower(pesticide) LIKE lower(?))')
        args.extend([f'%{search}%'] * 3)
    if status is not None:
        where.append('status = ?')
        args.append(status)
    sql = 'SELECT id, property_name, technician, pesticide, treated_on, area_sq_m, status FROM treatments'
    if where:
        sql += ' WHERE ' + ' AND '.join(where)
    sql += ' ORDER BY ' + allowed[sort_by] + (' DESC' if descending else ' ASC') + ', id ASC'
    if limit is not None:
        sql += ' LIMIT ? OFFSET ?'
        args.extend([limit, offset])
    elif offset:
        sql += ' LIMIT -1 OFFSET ?'
        args.append(offset)
    return [dict(zip(('id', 'property_name', 'technician', 'pesticide', 'treated_on', 'area_sq_m', 'status'), row)) for row in conn.execute(sql, args)]

def monthly_report(conn: sqlite3.Connection, year: int) -> list[dict]:
    if not isinstance(year, int) or isinstance(year, bool) or year < 1 or (year > 9999):
        raise ValueError('invalid year')
    result = [{'month': m, 'treatment_count': 0, 'total_area_sq_m': 0.0, 'properties': [], 'status_counts': {'scheduled': 0, 'completed': 0, 'cancelled': 0}} for m in range(1, 13)]
    for row in conn.execute('SELECT treated_on, area_sq_m, property_name, status FROM treatments WHERE treated_on >= ? AND treated_on < ?', (f'{year:04d}-01-01', f'{year + 1:04d}-01-01')):
        m = int(row[0][5:7])
        item = result[m - 1]
        item['treatment_count'] += 1
        item['total_area_sq_m'] += row[1]
        item['status_counts'][row[3]] += 1
        if row[2] not in item['properties']:
            item['properties'].append(row[2])
    for item in result:
