import json
import os
import zipfile
from decimal import Decimal, ROUND_HALF_UP

def extract_project_bundle(zip_path: str, output_dir: str) -> list[str]:
    with zipfile.ZipFile(zip_path) as zf:
        infos = zf.infolist()
        names = [i.filename for i in infos]
        if 'manifest.json' not in names:
            raise ValueError('manifest.json is required')
        if len(names) != len(set(names)):
            raise ValueError('duplicate archive member')
        base = os.path.realpath(output_dir)
        os.makedirs(base, exist_ok=True)
        files = []
        for info in infos:
            name = info.filename.replace('\\', '/')
            if info.is_dir():
                continue
            target = os.path.realpath(os.path.join(base, *name.split('/')))
            try:
                inside = os.path.commonpath([base, target]) == base
            except ValueError:
                inside = False
            if not inside:
                raise ValueError('invalid member path')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with zf.open(info) as source, open(target, 'wb') as dest:
                dest.write(source.read())
            files.append(name)
        return sorted(files)

def summarize_procurement(manifest_path: str) -> list[dict]:
    try:
        with open(manifest_path, encoding='utf-8') as f:
            data = json.load(f)
    except (OSError, ValueError, TypeError):
        raise ValueError('invalid manifest')
    if not isinstance(data, dict) or not isinstance(data.get('orders'), list):
        raise ValueError('invalid manifest')
    groups = {}
    for order in data['orders']:
        if not isinstance(order, dict):
            raise ValueError('invalid order')
        required = ('vendor', 'sku', 'room', 'quantity', 'unit_price', 'delivery_days')
        if any((k not in order for k in required)):
            raise ValueError('invalid order')
        if not all((isinstance(order[k], str) for k in ('vendor', 'sku', 'room'))):
            raise ValueError('invalid order')
        q, price, days = (order['quantity'], order['unit_price'], order['delivery_days'])
        if isinstance(q, bool) or not isinstance(q, int) or q <= 0:
            raise ValueError('invalid quantity')
        if isinstance(days, bool) or not isinstance(days, int) or days < 0:
            raise ValueError('invalid delivery')
        if isinstance(price, bool) or not isinstance(price, (int, float)) or price < 0:
            raise ValueError('invalid price')
        g = groups.setdefault(order['vendor'], {'vendor': order['vendor'], 'quantity': 0, 'spend': Decimal('0'), 'max_delivery_days': 0, 'rooms': set()})
        g['quantity'] += q
        g['spend'] += Decimal(str(price)) * q
        g['max_delivery_days'] = max(g['max_delivery_days'], days)
        g['rooms'].add(order['room'])
    result = []
    for g in groups.values():
        result.append({'vendor': g['vendor'], 'quantity': g['quantity'], 'spend': float(g['spend'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'max_delivery_days': g['max_delivery_days'], 'rooms': sorted(g['rooms'])})
    return sorted(result, key=lambda x: (-x['spend'], x['vendor']))

