def hash_access_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_access_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        return False
    try:
        iterations_text, salt_text, digest_text = stored.split('$')
        iterations = int(iterations_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def capacity_report(shelters: list[dict], region: str | None=None, page: int=1, page_size: int=10) -> dict:
