def prepare_enrollment_batch(records: list[dict], page: int=1, page_size: int=3) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    selected = {}
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be a dictionary')
        if set(record) != {'subject_id', 'modality', 'quality', 'enrolled'}:
            raise ValueError('invalid record fields')
        subject_id = record['subject_id']
        modality = record['modality']
        quality = record['quality']
        enrolled = record['enrolled']
        if not isinstance(subject_id, str) or not subject_id:
            raise ValueError('invalid subject_id')
        if not isinstance(modality, str) or not modality:
            raise ValueError('invalid modality')
        if isinstance(quality, bool) or not isinstance(quality, (int, float)) or (not 0 <= quality <= 1):
            raise ValueError('invalid quality')
        if not isinstance(enrolled, bool):
            raise ValueError('invalid enrolled value')
        if enrolled or quality < 0.75:
            continue
        old = selected.get(subject_id)
        if old is None or quality > old['quality'] or (quality == old['quality'] and modality < old['modality']):
            selected[subject_id] = {'subject_id': subject_id, 'modality': modality, 'quality': quality}
    ordered = sorted(selected.values(), key=lambda item: (-item['quality'], item['subject_id']))
    start = (page - 1) * page_size
    entries = []
    for item in ordered[start:start + page_size]:
        code = ''.join((secrets.choice(alphabet) for _ in range(12)))
        entries.append({'subject_id': item['subject_id'], 'modality': item['modality'], 'quality': round(item['quality'], 2), 'invite_code': code})
    return {'page': page, 'page_size': page_size, 'total': len(ordered), 'entries': entries}

