import json
import os
import zipfile

def extract_brand_assets(archive_path: str, destination_dir: str, category: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive')
    os.makedirs(destination_dir, exist_ok=True)
    base = os.path.realpath(destination_dir)
    with zipfile.ZipFile(archive_path) as archive:
        if 'manifest.json' not in archive.namelist():
            raise FileNotFoundError('manifest.json')
        for member in archive.infolist():
            if member.is_dir():
                continue
            target = os.path.realpath(os.path.join(destination_dir, member.filename))
            if os.path.commonpath((base, target)) != base:
                raise ValueError('archive member is outside destination')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(member) as source, open(target, 'wb') as output:
                output.write(source.read())
    with open(os.path.join(destination_dir, 'manifest.json'), encoding='utf-8') as stream:
        manifest = json.load(stream)
    if not isinstance(manifest, list):
        raise ValueError('manifest must be a list')
    records = []
    required = ('name', 'brand', 'category', 'file', 'width', 'height')
    for item in manifest:
        if not isinstance(item, dict) or any((key not in item for key in required)):
            raise ValueError('invalid manifest item')
        if any((not isinstance(item[key], str) for key in required[:4])) or any((type(item[key]) is not int for key in required[4:])):
            raise ValueError('invalid manifest item')
        if category is not None and item['category'] != category:
            continue
        path = os.path.join(destination_dir, item['file'])
        if not os.path.isfile(path):
            raise FileNotFoundError(item['file'])
        records.append({'name': item['name'], 'brand': item['brand'], 'category': item['category'], 'area': item['width'] * item['height'], 'size': os.path.getsize(path)})
    records.sort(key=lambda value: (-value['area'], value['brand'], value['name']))
    start = (page - 1) * page_size
    return records[start:start + page_size]

import xml.etree.ElementTree as ET

def summarize_crashes(xml_text: str, offset: int=0, limit: int=10) -> list[dict]:
    if not isinstance(xml_text, str) or offset < 0 or limit <= 0:
        raise ValueError('invalid arguments')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'reports':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for report in root.findall('report'):
        attrs = report.attrib
        required = ('id', 'app', 'version', 'platform', 'timestamp')
        if any((not attrs.get(name) for name in required)) or attrs['id'] in seen:
            raise ValueError('invalid report')
        seen.add(attrs['id'])
        try:
            timestamp = int(attrs['timestamp'])
            if timestamp < 0:
                raise ValueError
        except Exception as exc:
            raise ValueError('invalid timestamp') from exc
        exception = report.find('exception')
        if exception is None or not exception.get('type'):
            raise ValueError('invalid exception')
        frames = report.find('frames')
        frame_nodes = [] if frames is None else frames.findall('frame')
        top = None
        for frame in frame_nodes:
            if not all((frame.get(x) for x in ('file', 'function', 'line'))):
                raise ValueError('invalid frame')
            try:
                line = int(frame.get('line'))
                if line < 0:
                    raise ValueError
            except Exception as exc:
                raise ValueError('invalid line') from exc
            if top is None:
                top = {'file': frame.get('file'), 'function': frame.get('function'), 'line': line}
        result.append({'id': attrs['id'], 'app': attrs['app'], 'version': attrs['version'], 'platform': attrs['platform'], 'timestamp': timestamp, 'exception_type': exception.get('type'), 'message': (exception.text or '').strip(), 'top_frame': top, 'frame_count': len(frame_nodes)})
    result.sort(key=lambda item: (-item['timestamp'], item['id']))
    return result[offset:offset + limit]

