import subprocess

def rank_campaign_sessions(log_path: str, character: str, page: int, page_size: int) -> list[dict]:
    if not character or '\n' in character or '\r' in character:
        raise ValueError('invalid character')
    if page < 1:
        raise ValueError('invalid page')
    if page_size < 1 or page_size > 100:
        raise ValueError('invalid page size')
    result = subprocess.run(['grep', '-F', '--', character, log_path], capture_output=True, text=True, check=False)
    if result.returncode not in (0, 1):
        raise subprocess.CalledProcessError(result.returncode, result.args)
    totals = {}
    for line in result.stdout.splitlines():
        fields = line.split('|')
        if len(fields) != 3:
            continue
        session, name, value = fields
        if not session or not name or name != character:
            continue
        try:
            xp = int(value)
        except ValueError:
            continue
        if xp < 0:
            continue
        if session not in totals:
            totals[session] = [0, 0]
        totals[session][0] += xp
        totals[session][1] += 1
    ordered = sorted(totals.items(), key=lambda item: (-item[1][0], item[0]))
    start = (page - 1) * page_size
    return [{'session': session, 'xp': values[0], 'entries': values[1]} for session, values in ordered[start:start + page_size]]

