import ast
import operator

def _evaluate(expression, variables):
    tree = ast.parse(expression, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise NameError(node.id)
            return variables[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = visit(node.values[0])
            for part in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = visit(part)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for operation, part in zip(node.ops, node.comparators):
                right = visit(part)
                if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}[type(operation)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
        raise ValueError('unsupported expression')
    return visit(tree)

def generate_probation_report(records: list[dict], rule: str, score_formula: str) -> dict:
    selected = []
    for record in records:
        score = _evaluate(score_formula, {'violations': record['violations'], 'months': record['months']})
        variables = {'violations': record['violations'], 'months': record['months'], 'score': score}
        if _evaluate(rule, variables):
            selected.append({'id': record['id'], 'score': score})
    selected.sort(key=lambda item: (-item['score'], item['id']))
    average = round(sum((item['score'] for item in selected)) / len(selected), 2) if selected else 0.0
    return {'count': len(selected), 'average_score': average, 'records': selected}

