import csv
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_refund_report(records: list[dict], output_path: str, page: int=1, page_size: int=50) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 1000):
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('order_id'), str) or not record['order_id']:
            raise ValueError('invalid order id')
        if not isinstance(record.get('customer'), str) or not record['customer']:
            raise ValueError('invalid customer')
        if record.get('status') not in {'approved', 'pending', 'rejected'}:
            raise ValueError('invalid status')
        amount = record.get('amount')
        if isinstance(amount, bool):
            raise ValueError('invalid amount')
        try:
            value = Decimal(str(amount))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount')
        if not value.is_finite() or value < 0:
            raise ValueError('invalid amount')
        if record['status'] == 'approved':
            customer = record['customer']
            count, total = groups.get(customer, (0, Decimal('0')))
            groups[customer] = (count + 1, total + value)
    rounded = {name: (count, total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)) for name, (count, total) in groups.items()}
    ordered = sorted(rounded.items(), key=lambda item: (-item[1][1], item[0]))
    rows = [{'customer': name, 'refund_count': data[0], 'total_amount': f'{data[1]:.2f}'} for name, data in ordered]
    total = sum((data[1] for data in rounded.values()), Decimal('0'))
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='refund-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['customer', 'refund_count', 'total_amount'])
            for row in rows:
                writer.writerow([row['customer'], row['refund_count'], row['total_amount']])
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    start = (page - 1) * page_size
    return {'total_customers': len(rows), 'total_refunded': f"{total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}", 'page': page, 'page_size': page_size, 'rows': rows[start:start + page_size]}

