import hashlib
import hmac
import json

def process_bank_webhook(payload: bytes, signature: str, secret: str) -> dict:
    expected = hmac.new(secret.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(value, dict) or set(value) != {'event', 'account_id', 'balance_cents', 'currency'}:
        raise ValueError('invalid payload')
    if value['event'] != 'balance.updated':
        raise ValueError('invalid payload')
    if not isinstance(value['account_id'], str) or not value['account_id']:
        raise ValueError('invalid payload')
    if isinstance(value['balance_cents'], bool) or not isinstance(value['balance_cents'], int):
        raise ValueError('invalid payload')
    if not isinstance(value['currency'], str) or len(value['currency']) != 3 or (not value['currency'].isupper()) or (not value['currency'].isalpha()):
        raise ValueError('invalid payload')
    return {'account_id': value['account_id'], 'balance_cents': value['balance_cents'], 'currency': value['currency']}

