import os

def hash_access_code(code: str) -> str:
    if not isinstance(code, str) or not code:
        raise ValueError('invalid access code')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_access_code(code: str, stored: str) -> bool:
    if not isinstance(code, str) or not code or (not isinstance(stored, str)):
        return False
    try:
        salt_text, digest_text = stored.split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

