import subprocess

def summarize_benefit_files(paths: list[str], marker: str, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not paths or not marker or page < 1 or (page_size < 1):
        raise ValueError('invalid arguments')
    counts = []
    for path in paths:
        result = subprocess.run(['grep', '-F', '-c', '--', marker, path], capture_output=True, text=True)
        if result.returncode == 2:
            raise FileNotFoundError(path)
        try:
            count = int(result.stdout.strip())
        except ValueError:
            raise FileNotFoundError(path)
        if count:
            counts.append((path, count))
    total = sum((count for _, count in counts))
    counts.sort(key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    selected = counts[start:start + page_size]
    return [{'path': path, 'matches': count, 'percentage': round(count * 100 / total, 2)} for path, count in selected]

