import csv
import os
import tempfile

def export_review_summary(reviews: list[dict], destination: str) -> str:
    if not isinstance(reviews, list):
        raise ValueError('reviews must be a list')
    groups = {}
    for record in reviews:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('paper'), str) or not record['paper']:
            raise ValueError('invalid paper')
        if not isinstance(record.get('reviewer'), str) or not record['reviewer']:
            raise ValueError('invalid reviewer')
        score = record.get('score')
        if isinstance(score, bool) or not isinstance(score, int) or (not 1 <= score <= 5):
            raise ValueError('invalid score')
        recommendation = record.get('recommendation')
        if recommendation not in {'accept', 'revise', 'reject'}:
            raise ValueError('invalid recommendation')
        if record['paper'] not in groups:
            groups[record['paper']] = {'scores': [], 'counts': {'accept': 0, 'revise': 0, 'reject': 0}}
        groups[record['paper']]['scores'].append(score)
        groups[record['paper']]['counts'][recommendation] += 1
    rows = []
    for paper, data in groups.items():
        average = sum(data['scores']) / len(data['scores'])
        rows.append((paper, len(data['scores']), average, data['counts']))
    rows.sort(key=lambda row: (-row[2], row[0]))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.review-')
    try:
        with os.fdopen(fd, 'w', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['paper', 'reviews', 'average_score', 'accept_count', 'revise_count', 'reject_count'])
            for paper, count, average, counts in rows:
                writer.writerow([paper, count, format(average, '.2f'), counts['accept'], counts['revise'], counts['reject']])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return destination

