from datetime import date, timedelta
from lxml import etree

def _tree(text):
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        return etree.fromstring(text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def _day(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def parse_policies(xml_text: str) -> list[dict]:
    root = _tree(xml_text)
    if root.tag != 'retention' or root.attrib:
        raise ValueError('invalid document')
    result = []
    names = set()
    for node in root:
        if node.tag != 'policy':
            raise ValueError('invalid policy')
        name = node.get('name')
        priority = node.get('priority')
        if not name or name in names or priority is None or (len(node.attrib) != 2):
            raise ValueError('invalid policy')
        try:
            priority = int(priority)
        except ValueError as exc:
            raise ValueError('invalid priority') from exc
        defaults = [x for x in node if x.tag == 'default']
        rules = [x for x in node if x.tag == 'rule']
        if len(defaults) != 1 or len(defaults[0].attrib) != 1:
            raise ValueError('invalid default')
        try:
            default_days = int(defaults[0].get('days'))
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid days') from exc
        if default_days < 0:
            raise ValueError('invalid days')
        mapping = {}
        for rule in rules:
            category = rule.get('category')
            raw_days = rule.get('days')
            if not category or len(rule.attrib) != 2 or category in mapping:
                raise ValueError('invalid rule')
            try:
                days = int(raw_days)
            except (TypeError, ValueError) as exc:
                raise ValueError('invalid days') from exc
            if days < 0:
                raise ValueError('invalid days')
            mapping[category] = days
        if any((x.tag not in ('default', 'rule') for x in node)):
            raise ValueError('invalid policy')
        names.add(name)
        result.append({'name': name, 'priority': priority, 'default_days': default_days, 'rules': mapping})
    return sorted(result, key=lambda p: (-p['priority'], p['name']))

def retention_deadline(policy: dict, category: str, created: str) -> str:
    if not isinstance(category, str):
        raise ValueError('invalid category')
    try:
        days = policy['rules'].get(category, policy['default_days'])
        if not isinstance(days, int) or days < 0:
            raise ValueError
        return (_day(created) + timedelta(days=days)).isoformat()
    except (KeyError, TypeError, ValueError, OverflowError) as exc:
        raise ValueError('invalid policy or date') from exc

def retention_report(xml_text: str, records: list[dict], as_of: str) -> list[dict]:
    policies = parse_policies(xml_text)
    point = _day(as_of)
    by_name = {p['name']: p for p in policies}
    groups = {}
    for record in records:
        if not all((isinstance(record.get(k), str) for k in ('policy', 'category', 'created'))):
            raise ValueError('invalid record')
        if record['policy'] not in by_name:
            raise ValueError('unknown policy')
        deadline = retention_deadline(by_name[record['policy']], record['category'], record['created'])
        key = (record['policy'], record['category'])
        item = groups.setdefault(key, {'policy': key[0], 'category': key[1], 'count': 0, 'expired': 0, 'latest_deadline': deadline})
        item['count'] += 1
        item['expired'] += _day(deadline) < point
        item['latest_deadline'] = max(item['latest_deadline'], deadline)
    return sorted(groups.values(), key=lambda x: (-by_name[x['policy']]['priority'], x['policy'], x['category']))

