import hashlib
import hmac
import os

def create_trace_access_record(secret: str, scopes: list[str]) -> dict:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not isinstance(scopes, list):
        raise TypeError('scopes must be a list')
    if not secret:
        raise ValueError('secret must not be empty')
    if any((not isinstance(scope, str) or not scope for scope in scopes)):
        raise ValueError('invalid scope')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000).hex()
    return {'digest': digest, 'salt': salt.hex(), 'scopes': list(scopes)}

def verify_trace_access(record: dict, candidate: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(candidate, str):
            return False
        salt = bytes.fromhex(record['salt'])
        expected = record['digest']
        actual = hashlib.pbkdf2_hmac('sha256', candidate.encode(), salt, 100000).hex()
        return isinstance(expected, str) and hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def summarize_spans(spans: list[dict], service: str | None=None, page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(spans, list):
        raise TypeError('spans must be a list')
    if not isinstance(page, int) or not isinstance(page_size, int) or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    groups = {}
    for span in spans:
        if not isinstance(span, dict):
            raise TypeError('span must be a dictionary')
        if not all((key in span for key in ('trace_id', 'service', 'status', 'duration_ms'))):
            raise ValueError('missing field')
        if not isinstance(span['trace_id'], str) or not isinstance(span['service'], str) or (not isinstance(span['status'], str)):
            raise ValueError('invalid field')
        duration = span['duration_ms']
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or duration < 0:
            raise ValueError('invalid duration')
        if not span['service']:
            raise ValueError('empty service')
        if service is not None and span['service'] != service:
            continue
        group = groups.setdefault(span['service'], [0, 0, 0.0])
        group[0] += 1
        group[1] += span['status'] == 'error'
        group[2] += duration
    result = [{'service': name, 'count': values[0], 'error_count': values[1], 'total_ms': round(values[2], 2), 'average_ms': round(values[2] / values[0], 2)} for name, values in groups.items()]
    result.sort(key=lambda item: (-item['total_ms'], item['service']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

