import re

def parse_plan(document: str) -> dict:
    components = {}
    raw = {}
    pattern = re.compile('^([A-Za-z0-9_-]+)\\s*\\[\\s*([A-Za-z0-9_-]+)\\s*\\]\\s*=\\s*(.*?)\\s*$')
    for line in document.splitlines():
        text = line.strip()
        if not text or text.startswith('#'):
            continue
        match = pattern.fullmatch(text)
        if not match:
            raise ValueError('malformed line')
        name, owner, deps_text = match.groups()
        if name in components:
            raise ValueError('duplicate component')
        if deps_text == '-':
            deps = []
        else:
            deps = [x.strip() for x in deps_text.split(',')]
            if any((not re.fullmatch('[A-Za-z0-9_-]+', x) for x in deps)) or len(set(deps)) != len(deps):
                raise ValueError('invalid dependencies')
        components[name] = owner
        raw[name] = deps
    for deps in raw.values():
        if any((dep not in components for dep in deps)):
            raise ValueError('unknown dependency')
    return {'components': {k: components[k] for k in sorted(components)}, 'edges': {k: raw[k] for k in sorted(raw)}}

def make_version(plan_id: str, number: int, author_id: str, document: str, timestamp: int) -> dict:
    if not isinstance(plan_id, str) or not plan_id or (not isinstance(author_id, str)) or (not author_id):
        raise ValueError('invalid identity')
    if not isinstance(number, int) or isinstance(number, bool) or number <= 0:
        raise ValueError('invalid number')
    if not isinstance(timestamp, int) or isinstance(timestamp, bool) or timestamp < 0:
        raise ValueError('invalid timestamp')
    return {'plan_id': plan_id, 'number': number, 'author_id': author_id, 'timestamp': timestamp, 'document': document, 'parsed': parse_plan(document)}

def publish_version(requester: dict, plan: dict, version: dict, history: list[dict]) -> list[dict]:
    if requester.get('tenant_id') != plan.get('tenant_id'):
        raise PermissionError('not permitted')
    roles = plan.get('roles', {}).get(requester.get('id'), [])
    if requester.get('id') != plan.get('owner_id') and 'plan_admin' not in roles:
        raise PermissionError('not permitted')
    if version.get('plan_id') != plan.get('id'):
        raise ValueError('wrong plan')
    numbers = [item.get('number') for item in history]
    if version.get('number') in numbers:
        raise ValueError('duplicate version')
    expected = max(numbers, default=0) + 1
    if version.get('number') != expected:
        raise ValueError('invalid sequence')
    return list(history) + [version]

