def register_beneficiary(registry: dict, beneficiary_id: str, name: str, birth_year: int, monthly_amount: int, pin: str) -> None:
    if not isinstance(beneficiary_id, str) or not re.fullmatch('[A-Za-z0-9-]+', beneficiary_id):
        raise ValueError('invalid identifier')
    if beneficiary_id in registry:
        raise KeyError(beneficiary_id)
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if not isinstance(birth_year, int) or isinstance(birth_year, bool) or (not 1900 <= birth_year <= 2100):
        raise ValueError('invalid birth year')
    if not isinstance(monthly_amount, int) or isinstance(monthly_amount, bool) or monthly_amount <= 0:
        raise ValueError('invalid amount')
    if not isinstance(pin, str) or not re.fullmatch('[0-9]{4}', pin):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    registry[beneficiary_id] = {'name': name.strip(), 'birth_year': birth_year, 'monthly_amount': monthly_amount, 'salt': base64.b64encode(salt).decode(), 'pin_hash': digest.hex()}

def authenticate_beneficiary(registry: dict, beneficiary_id: str, pin: str) -> bool:
    if beneficiary_id not in registry or not isinstance(pin, str) or (not re.fullmatch('[0-9]{4}', pin)):
        return False
    record = registry[beneficiary_id]
    salt = base64.b64decode(record['salt'])
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000).hex()
    return hmac.compare_digest(actual, record['pin_hash'])

def monthly_report(registry: dict, entries: list[tuple[str, str, int]], month: str) -> list[dict]:
    if not isinstance(month, str) or not re.fullmatch('[0-9]{4}-[0-9]{2}', month):
        raise ValueError('invalid month')
    try:
        datetime.date.fromisoformat(month + '-01')
    except ValueError:
        raise ValueError('invalid month')
    totals = {key: 0 for key in registry}
    for entry in entries:
        if not isinstance(entry, (tuple, list)) or len(entry) != 3:
            raise ValueError('invalid entry')
        key, date_text, amount = entry
        if not isinstance(date_text, str):
            raise ValueError('invalid date')
        try:
            date = datetime.date.fromisoformat(date_text)
        except ValueError:
            raise ValueError('invalid date')
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            raise ValueError('invalid amount')
        if key in totals and date_text[:7] == month:
            totals[key] += amount
    result = []
    for key, record in registry.items():
        contribution = totals[key]
        result.append({'id': key, 'name': record['name'], 'birth_year': record['birth_year'], 'contributions': contribution, 'pension': record['monthly_amount'] + min(contribution // 50, 5000)})
    return sorted(result, key=lambda x: (-x['pension'], x['name'].casefold(), x['id']))

