import datetime
import hashlib
import hmac
import json
import os

def build_reservation_report(records: list[dict], lab_id: str, date: str, page: int, page_size: int) -> dict:
    try:
        datetime.date.fromisoformat(date)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    groups = {}
    total_minutes = 0
    total_reservations = 0
    for record in records:
        if not all((key in record for key in ('reservation_id', 'lab_id', 'date', 'status', 'equipment', 'start', 'end'))):
            raise ValueError('malformed reservation')
        if record['lab_id'] != lab_id or record['date'] != date or record['status'] != 'confirmed':
            continue
        try:
            start = datetime.datetime.strptime(record['start'], '%H:%M')
            end = datetime.datetime.strptime(record['end'], '%H:%M')
        except Exception as exc:
            raise ValueError('invalid time') from exc
        minutes = int((end - start).total_seconds() // 60)
        if minutes <= 0:
            raise ValueError('end must be later than start')
        name = record['equipment']
        if not isinstance(name, str):
            raise ValueError('invalid equipment')
        group = groups.setdefault(name, [0, 0])
        group[0] += 1
        group[1] += minutes
        total_reservations += 1
        total_minutes += minutes
    ordered = sorted(groups.items(), key=lambda item: (-item[1][1], item[0]))
    pages = (len(ordered) + page_size - 1) // page_size
    selected = ordered[(page - 1) * page_size:page * page_size]
    report = {'lab_id': lab_id, 'date': date, 'total_reservations': total_reservations, 'total_minutes': total_minutes, 'equipment': [{'name': name, 'reservations': values[0], 'minutes': values[1]} for name, values in selected], 'page': page, 'page_size': page_size, 'pages': pages}
    token = os.environ.get('LAB_REPORT_SIGNING_TOKEN')
    if token is None:
        raise RuntimeError('LAB_REPORT_SIGNING_TOKEN is not set')
    payload = json.dumps(report, sort_keys=True, separators=(',', ':')).encode()
    report['signature'] = hmac.new(token.encode(), payload, hashlib.sha256).hexdigest()
    return report

