import csv
import hashlib
import hmac
import io
import os
from datetime import datetime, timezone, timedelta

def parse_meter_events(text: str) -> list[dict]:
    events = []
    for row in csv.reader(io.StringIO(text)):
        if not row or all((not field.strip() for field in row)):
            continue
        if len(row) != 4:
            raise ValueError('each event must have four fields')
        user_id, article_id, stamp, action = [x.strip() for x in row]
        if not user_id or not article_id or action not in ('view', 'preview'):
            raise ValueError('invalid event')
        try:
            value = datetime.fromisoformat(stamp.replace('Z', '+00:00'))
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        if value.tzinfo is None:
            raise ValueError('timestamp must include timezone')
        value = value.astimezone(timezone.utc)
        events.append({'user_id': user_id, 'article_id': article_id, 'timestamp': value, 'action': action})
    events.sort(key=lambda event: event['timestamp'])
    return events

def decide_access(user_id: str, article_id: str, event_text: str, now: datetime, settings: dict) -> dict:
    if now.tzinfo is None:
        raise ValueError('now must include timezone')
    key = os.environ.get('PAYWALL_SIGNING_KEY')
    if key is None:
        raise RuntimeError('PAYWALL_SIGNING_KEY is required')
    limit = settings['free_limit']
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError('free_limit must be a non-negative integer')
    current = now.astimezone(timezone.utc)
    start = current - timedelta(hours=24)
    articles = {event['article_id'] for event in parse_meter_events(event_text) if event['user_id'] == user_id and event['action'] == 'view' and (start <= event['timestamp'] <= current) and (event['article_id'] != article_id)}
    if user_id in set(settings['subscribers']):
        allowed, reason, remaining = (True, 'subscriber', limit)
    else:
        remaining = max(0, limit - len(articles))
        allowed = len(articles) < limit
        reason = 'meter_available' if allowed else 'meter_exhausted'
    payload = f'{user_id}|{article_id}|{allowed}|{remaining}'.encode()
    receipt = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return {'allowed': allowed, 'reason': reason, 'remaining': remaining, 'receipt': receipt}

