from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from lxml import etree

def dispatch_orders(xml: str, page: int=1, page_size: int=10, statuses: tuple[str, ...]=()) -> list[dict[str, object]]:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    try:
        root = etree.fromstring(xml.encode(), parser=etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'orders':
        raise ValueError('invalid root')
    rows = []
    required = ('id', 'restaurant', 'courier', 'status', 'subtotal', 'delivery_fee', 'eta_minutes')
    for node in root.findall('order'):
        try:
            if any((name not in node.attrib for name in required)):
                raise ValueError('missing attribute')
            total = (Decimal(node.get('subtotal')) + Decimal(node.get('delivery_fee'))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            eta_text = node.get('eta_minutes')
            eta = int(eta_text)
            if str(eta) != eta_text or eta < 0:
                raise ValueError('invalid eta')
        except (InvalidOperation, TypeError, ValueError) as exc:
            raise ValueError('invalid order') from exc
        if statuses and node.get('status') not in statuses:
            continue
        rows.append((total, node.get('id'), {'id': node.get('id'), 'restaurant': node.get('restaurant'), 'courier': node.get('courier'), 'status': node.get('status'), 'total': format(total, '.2f'), 'eta_minutes': eta}))
    rows.sort(key=lambda item: (-item[0], item[1]))
    start = (page - 1) * page_size
    return [item[2] for item in rows[start:start + page_size]]

