from decimal import Decimal, ROUND_HALF_UP
import subprocess

def paginate_confirmations(path: str, broker: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or page <= 0 or (page_size <= 0):
        raise ValueError('page and page_size must be positive integers')
    completed = subprocess.run(['sort', '-t', '|', '-k2,2', '-k1,1', path], check=True, capture_output=True, text=True)
    records = []
    for raw in completed.stdout.splitlines():
        if not raw.strip():
            continue
        fields = [field.strip() for field in raw.split('|')]
        if len(fields) != 5 or any((not field for field in fields[:3])):
            raise ValueError('malformed confirmation')
        trade_id, row_broker, symbol, quantity_text, price_text = fields
        try:
            quantity = int(quantity_text, 10)
            price = Decimal(price_text)
        except Exception as exc:
            raise ValueError('malformed confirmation') from exc
        if quantity <= 0 or not price.is_finite() or price <= 0:
            raise ValueError('malformed confirmation')
        if broker is not None and row_broker != broker:
            continue
        records.append({'trade_id': trade_id, 'broker': row_broker, 'symbol': symbol, 'quantity': quantity, 'price': price, 'notional': (price * quantity).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)})
    start = (page - 1) * page_size
    return records[start:start + page_size]

