import sqlite3
from datetime import date

def get_cleaning_schedule(conn: sqlite3.Connection, start_date: str, end_date: str, cleaner: str | None=None, statuses: list[str] | None=None, sort_by: str='scheduled_date', page: int=1, page_size: int=20) -> list[dict]:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc
    if start > end:
        raise ValueError('start_date must not be later than end_date')
    if statuses is not None:
        if not isinstance(statuses, list) or not all((isinstance(value, str) for value in statuses)):
            raise TypeError('statuses must be a list of strings')
        if not statuses:
            return []
    if sort_by not in {'scheduled_date', 'minutes', 'property_name'}:
        raise ValueError('invalid sort_by')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid paging')
    order = {'scheduled_date': 'scheduled_date ASC', 'minutes': 'minutes DESC', 'property_name': 'property_name ASC'}[sort_by]
    clauses = ['scheduled_date BETWEEN ? AND ?']
    params: list[object] = [start_date, end_date]
    if cleaner is not None:
        clauses.append('cleaner = ?')
        params.append(cleaner)
    if statuses is not None:
        clauses.append('status IN (' + ','.join(('?' for _ in statuses)) + ')')
        params.extend(statuses)
    offset = (page - 1) * page_size
    query = 'SELECT id, property_name, scheduled_date, cleaner, status, minutes FROM cleaning_tasks WHERE ' + ' AND '.join(clauses) + ' ORDER BY ' + order + ', id ASC LIMIT ? OFFSET ?'
    params.extend([page_size, offset])
    rows = conn.execute(query, params).fetchall()
    keys = ['id', 'property_name', 'scheduled_date', 'cleaner', 'status', 'minutes']
    return [dict(zip(keys, row)) for row in rows]

